insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.name.per.concept$txt$, null, $txt$dairy$txt$, $txt$Наименование продукта на упаковке соответствует понятию, установленному ТР ТС 033/2013 («молоко питьевое», «молочный напиток» и т. п.)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Понижено с checkable. Норма требует СООТВЕТСТВИЯ наименования понятию раздела II, а не просто наличия слова: продукт, названный «молоко», но фактически являющийся молочным напитком (восстановленным из сухого молока) или молокосодержащим продуктом, по фотографии неотличим. Фото надёжно подтверждает только то, что на лицевой панели напечатано регламентированное слово. Второй чек (нет ли только фанта$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS033TXT","clause":"раздел XII, п. 69","quote_ru":"«Наименования молока и молочной продукции должны соответствовать понятиям, установленным в разделе II настоящего технического регламента». Допускается любой порядок слов."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.name.per.concept$txt$, $txt$dairy.name.concept_term$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$identity$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Присутствует ли на лицевой стороне наименование продукта, использующее регламентированное понятие («молоко», «молоко питьевое», «молочный напиток»)?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["молоко","молоко питьевое","питьевое молоко","молочный напиток","sut","ichimlik sut"],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Снять лицевую панель целиком, без бликов и обрезки верхнего края$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.name.per.concept$txt$, $txt$dairy.name.no_fantasy_only$txt$, 1, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$trademark$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Ограничивается ли маркировка только фантазийным названием (бренд) без регламентированного наименования продукта рядом с ним?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"Лицевая панель, на которой присутствует только торговая марка/логотип и нет слова «молоко» либо иного установленного понятия"}$txt$::jsonb, $txt$Если видна только торговая марка — сделать дополнительный снимок боковых панелей$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.reconstituted.declared$txt$, null, $txt$dairy$txt$, $txt$Питьевое молоко, произведённое из концентрированного/сгущённого/сухого молока, обозначается как восстановленное с указанием исходного сырья$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Слово «восстановленное» на фото читается, но факт восстановления из сухого молока по изображению установить нельзя$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS033TXT","clause":"раздел XII, п. 69 (абзац о наименовании восстановленного молока)","quote_ru":"«При формировании наименования восстановленного молока требуется указание непосредственно в наименовании основного сырья, используемого при изготовлении продукта, шрифтом одинакового размера, например: «восстановленное молоко из сухого молока», «восстановленное молоко из концентрированного молока». Номер пункта (69) сверен по двум зеркалам действующей редакции; официальный текст ЕЭК не читался."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.reconstituted.declared$txt$, $txt$dairy.reconstituted.term_present$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Указано ли в наименовании, что молоко восстановленное, и названо ли исходное сырьё (сухое/концентрированное/сгущённое молоко)?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["восстановленное","из сухого молока","из концентрированного молока","qayta tiklangan"],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Снять наименование крупным планом вместе с подстрочником под ним$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.reconstituted.declared$txt$, $txt$dairy.reconstituted.same_font_size$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$geometry$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$reconstituted_source_text$txt$, null, $txt$relative_size$txt$, $txt${"target":"reconstituted_source_text","min_mm":null,"min_area_fraction":null,"surface":"front_panel","reference_scale":"Сравнение высоты строчных букв слова «восстановленное» с высотой букв основного наименования в том же кадре — относительная метрика, физический масштаб не требуется","note":"Мера намеренно НЕ min_size_mm: норма «шрифтом одинакового размера» относительная, миллиметры не нужны и min_mm не задан. Прежняя пометка min_size_mm обещала измерение в мм, которого этот чек не делает."}$txt$::jsonb, $txt$Наименование и указание сырья должны попасть в один кадр под прямым углом$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.fat.fraction.percent$txt$, null, $txt$dairy$txt$, $txt$На потребительской упаковке указана массовая доля жира в процентах$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Жирность традиционно печатается крупно на лицевой панели и извлекается как «число + %». Оставлено checkable СОЗНАТЕЛЬНО: требование сформулировано как обязанность НАПЕЧАТАТЬ значение, и именно это фото проверяет полностью. Достоверность самого числа лежит вне фото и вынесена в not_checkable_summary. Ограничение нормы «за исключением обезжиренных продуктов» на питьевое молоко практически не влияет.$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS033TXT","clause":"раздел XII, п. 86 (подпункт «б»)","quote_ru":"На потребительскую упаковку наносится информация о массовой доле жира в процентах — за исключением обезжиренных продуктов; для сыра указывается массовая доля жира в сухом веществе."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.fat.fraction.percent$txt$, $txt$dairy.fat.value_with_unit$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$composition$txt$, $txt$fat_content$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Указана ли массовая доля жира числом с единицей «%»?$txt$, null, $txt${"expect":"value_with_unit","unit":"%","pattern_hints":["жирность","м.д.ж.","массовая доля жира","% жира","yog'lilik","yog' massa ulushi"],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Если процент не найден на лицевой стороне — снять боковую и оборотную панели$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.heat.treatment.declared$txt$, null, $txt$dairy$txt$, $txt$После наименования указан способ термической обработки (пастеризованное / ультрапастеризованное / стерилизованное / топлёное)$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Слово о термообработке размещается вплотную к наименованию на лицевой панели и надёжно распознаётся; требование сформулировано как обязанность указать термин после наименования, и это фото проверяет целиком. Достоверность самого режима (реально ли молоко ультрапастеризовано) фото не проверяет — вынесено в not_checkable_summary.$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS033TXT","clause":"раздел XII, п. 71","quote_ru":"«Понятия, характеризующие способ термической обработки, указываются после понятия «молоко» или наименований продуктов переработки молока», например «молоко пастеризованное», «сливки стерилизованные»."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.heat.treatment.declared$txt$, $txt$dairy.heat.term_present$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$identity$txt$, $txt$heat_treatment$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Указан ли способ термической обработки рядом с наименованием продукта?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["пастеризованное","ультрапастеризованное","стерилизованное","топлёное","топленое","УВТ","ultrapasterizatsiya","pasterizatsiyalangan","sterillangan"],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Снять наименование вместе со строкой под ним — термин часто набран меньшим кеглем$txt$, null)
