insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.heat.treatment.declared$txt$, $txt$dairy.heat.position_after_name$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$geometry$txt$, $txt$heat_treatment$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$heat_treatment_text$txt$, null, $txt$position$txt$, $txt${"target":"heat_treatment_text","min_mm":null,"min_area_fraction":null,"surface":"front_panel","reference_scale":"Относительное положение bounding-box термина и bounding-box наименования в одном кадре; физический масштаб не нужен","note":"Мера «position» локальным движком не реализована — чек сознательно уйдёт в unreadable/на человека, а не в зелёную галочку."}$txt$::jsonb, $txt$Наименование и термин должны попасть в один кадр$txt$, null)
