insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.no.dairy.terms.with.fat.substitute$txt$, null, $txt$dairy$txt$, $txt$Запрет использовать понятие «молоко» и производные от него в наименовании молокосодержащего продукта с заменителем молочного жира$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Наличие запрещённых слов на фото видно, но ТРИГГЕР запрета — фактическое использование заменителя молочного жира — по изображению не определяется, а условной применимости («если в составе заявлены растительные масла») в схеме чекпойнтов нет. Поэтому список forbidden_terms намеренно оставлен пустым: со словом «молоко» внутри он давал бы критический FAIL на КАЖДОМ обычном пакете молока. Проверка вын$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS033TXT","clause":"раздел XII, п. 82","quote_ru":"«Для молокосодержащих продуктов (за исключением сквашенных) не допускается использование понятий, установленных настоящим техническим регламентом для молока, молочной продукции и молочных составных продуктов, в том числе слов или частей слов, входящих в эти понятия, их различных сочетаний, в наименованиях товарных знаков при маркировке молокосодержащих продуктов, на их этикетках, в рекламе или ины"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.no.dairy.terms.with.fat.substitute$txt$, $txt$dairy.substitute.forbidden_dairy_terms$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$prohibitions$txt$, $txt$veg_fat_notice$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на упаковке, где в составе заявлены растительные масла/жиры или ЗМЖ, слова «молоко», «молочко», «сливки», «сливочный» и производные в наименовании продукта?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"Наименование продукта, начинающееся не со слов «молокосодержащий продукт с заменителем молочного жира», при заявленных в составе растительных маслах/жирах","forbidden_terms_if_vegetable_fat_declared":["молоко","молочко","молочный","сливки","сливочный","сливочки","маслице","творожок"],"precondition":"Применять ТОЛЬКО если в распознанном составе заявлены растительные масла/жиры или ЗМЖ. Без выполнения предусловия чек не должен давать FAIL: движок absence сравнивает forbidden_terms со всем OCR-текстом и сработал бы на слове «молоко» у любого честного питьевого молока."}$txt$::jsonb, $txt$Обязателен парный снимок: лицевая панель с наименованием + макро-снимок блока состава. Без блока состава чек неприменим — предусловие не проверено.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.no.dairy.terms.with.fat.substitute$txt$, $txt$dairy.substitute.prefix_wording$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$veg_fat_notice$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Начинается ли наименование со слов «молокосодержащий продукт с заменителем молочного жира», если в составе заявлены растительные масла?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["молокосодержащий продукт с заменителем молочного жира","ЗМЖ"],"expected_value":"молокосодержащий продукт с заменителем молочного жира","language":["ru"],"precondition":"Применять ТОЛЬКО если в распознанном составе заявлены растительные масла/жиры. Иначе чек даёт FAIL на любом обычном молоке (искомой строки там нет и быть не должно)."}$txt$::jsonb, $txt$Снять первую строку наименования целиком. Severity понижена с critical до major: без подтверждённого предусловия чек — генератор ложных тревог, а не ловушка для нарушения.$txt$, null)
