insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.vegetable.oils.notice$txt$, null, $txt$dairy$txt$, $txt$Надпись «Содержит растительные масла» на выделенном контрастным цветом информационном поле, шрифт не менее 3 мм$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Наличие надписи и контраст поля определимы, а высота шрифта 3 мм требует эталона масштаба в кадре; сама обязанность возникает только для молокосодержащих продуктов$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"EEC102","clause":"ТР ТС 033/2013, раздел XII, п. 81 (в ред. Решения Совета ЕЭК от 10.11.2017 № 102, применяется с 15.07.2018)","quote_ru":"«Содержит растительные масла» — надпись размещается на выделенном контрастным цветом по отношению к фону этикетки информационном поле; размер шрифта надписи должен быть не менее 3 мм, цвет шрифта контрастен цвету информационного поля. Номер пункта (81) и порог 3 мм подтверждены двумя независимыми источниками."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.vegetable.oils.notice$txt$, $txt$dairy.vegoil.notice_text$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$warnings$txt$, $txt$veg_fat_notice$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Присутствует ли надпись «Содержит растительные масла» на упаковке продукта, в составе которого заявлены растительные масла/жиры?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["Содержит растительные масла","содержит растительные жиры"],"expected_value":"Содержит растительные масла","language":["ru"]}$txt$::jsonb, $txt$Искать выделенный прямоугольник-плашку на лицевой или боковой панели, снять его крупно$txt$, null)
