insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.vegetable.oils.notice$txt$, $txt$dairy.vegoil.field_contrast$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$geometry$txt$, $txt$veg_fat_notice$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$vegetable_oils_info_field$txt$, null, $txt$contrast_ratio$txt$, $txt${"target":"vegetable_oils_info_field","min_mm":null,"min_area_fraction":null,"surface":"front_panel","reference_scale":"Контраст измеряется по яркости пикселей плашки и окружающего фона на том же кадре; нормативное числовое значение контраста регламентом не задано — только качественное «контрастный»","note":"Severity понижена с major до minor: числового порога контраста регламент не задаёт («контрастный» — качественная характеристика), а локальный движок contrast_ratio прямо отвечает, что контраст печати по фото не измеряется (зависит от освещения и баланса белого). Нормативного FAIL этот чек породить не может."}$txt$::jsonb, $txt$Снимать при равномерном освещении, без вспышки и бликов$txt$, null)
