insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.net.quantity$txt$, null, $txt$dairy$txt$, $txt$Указано количество продукции (объём в л/мл или масса нетто)$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Объём печатается крупно на лицевой панели и распознаётся как число с единицей измерения; требование сформулировано как обязанность УКАЗАТЬ количество, и это фото проверяет полностью. Фактический недолив (1 л на пачке / 0,9 л в упаковке) фото не ловит — вынесено в not_checkable_summary.$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4, ч. 4.1, п. 3","quote_ru":"Маркировка упакованной пищевой продукции должна содержать «количество пищевой продукции» — объём, массу нетто или количество штук."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
