insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.storage.after.opening$txt$, null, $txt$dairy$txt$, $txt$Указаны условия хранения после вскрытия упаковки$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Текст относится к мелкому шрифту и требует макро-снимка; сама обязанность условна — она возникает, только если качество меняется после вскрытия (для питьевого молока это практически всегда так, но по фото не устанавливается)$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4, ч. 4.1, п. 6 (второй абзац)","quote_ru":"«Для пищевой продукции, качество и безопасность которой изменяется после вскрытия упаковки, защищавшей продукцию от порчи, указывают также условия хранения после вскрытия упаковки»."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
