insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.nutrition.value$txt$, null, $txt$dairy$txt$, $txt$Указаны показатели пищевой ценности (энергетическая ценность, белки, жиры, углеводы)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Таблица пищевой ценности набирается минимальным допустимым кеглем; распознаётся только с отдельного макро-снимка, а достоверность цифр по фото не проверяется$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4, ч. 4.1, п. 9; порядок — ч. 4.9","quote_ru":"Маркировка должна содержать «показатели пищевой ценности пищевой продукции». Указываются энергетическая ценность и количество белков, жиров, углеводов в расчёте на 100 г или 100 мл либо на порцию."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
