insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.eac.mark$txt$, null, $txt$dairy$txt$, $txt$На упаковку нанесён единый знак обращения продукции на рынке ЕАЭС (EAC) базовым размером не менее 5 мм$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Понижено с checkable, потому что порог «не менее 5 мм» вынесен прямо в формулировку требования, а физический размер без эталона масштаба в кадре не измеряется — это же сказано в собственном not_checkable_summary файла. Фото надёжно даёт только факт наличия графического знака; правомерность его нанесения подтверждается действующей декларацией в реестре ЕАЭС, а не изображением. Локальный запасной ма$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"KTS711","clause":"п. 3.3 Положения о едином знаке обращения (утв. Решением КТС от 15.07.2011 № 711); обязанность нанесения — ТР ТС 022/2011, ст. 4, ч. 4.1, п. 11","quote_ru":"«Базовый размер единого знака обращения должен быть не менее 5 мм» (п. 3.3). Знак наносится на каждую единицу продукции, упаковку или сопроводительную документацию; размеры должны гарантировать чёткость элементов, знак должен быть контрастен фону."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
