insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.preparation.recommendations$txt$, null, $txt$dairy$txt$, $txt$Приведены рекомендации и (или) ограничения по использованию и приготовлению, если без них использование затруднено или может причинить вред$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Наличие текста рекомендаций на фото видно, но условие обязательности («без рекомендаций использование затруднено/вредно») определяется свойствами продукта, а не изображением$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4, ч. 4.1, п. 8","quote_ru":"Маркировка должна содержать «рекомендации и (или) ограничения по использованию, в том числе приготовлению пищевой продукции, в случае если её использование без данных рекомендаций… затруднено»."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.preparation.recommendations$txt$, $txt$dairy.prep.recommendation_present$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$warnings$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на упаковке рекомендации по употреблению/приготовлению (например, «перед употреблением взболтать», «рекомендуется кипячение»)?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["перед употреблением","взболтать","рекомендуется","кипятить","iste'mol qilishdan oldin","tavsiya etiladi"],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Снять весь текстовый блок оборотной панели$txt$, null)
