insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.min.font.height$txt$, null, $txt$dairy$txt$, $txt$Соблюдена минимальная высота шрифта маркировки: 2,0 мм по строчным буквам для части обязательных сведений и 0,8 мм для остальных (точный перечень «ключевых» сведений не установлен)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Абсолютная высота букв измеряется только при известном масштабе — нужен физический эталон в кадре или паспортные габариты упаковки$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4, ч. 4.12 (Изменение № 2 — Решение Совета ЕЭК от 14.09.2018 № 75); даты начала применения и переходного периода не установлены точно","quote_ru":"Требование к минимальной высоте шрифта маркировки введено в ТР ТС 022/2011 Изменением № 2 (Решение Совета ЕЭК от 14.09.2018 № 75), ч. 4.12 ст. 4: часть обязательных сведений наносится шрифтом высотой не менее 2,0 мм по строчным буквам, остальные — не менее 0,8 мм. ВНИМАНИЕ: сами пороги 2,0/0,8 мм подтверждены двумя источниками, но точный ПЕРЕЧЕНЬ сведений, к которым относится порог 2,0 мм, в источ"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
