insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.min.font.height$txt$, $txt$dairy.font.other_fields_08mm$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$geometry$txt$, $txt$handling_marks$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$secondary_marking_text$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"secondary_marking_text","min_mm":0.8,"min_area_fraction":null,"surface":"any_panel","reference_scale":"Тот же эталон; при 0,8 мм требуется разрешение не хуже ~600 ppi по поверхности упаковки"}$txt$::jsonb, $txt$Макро-режим, стабилизация, без цифрового зума$txt$, null)
