insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.packaging.material.marks$txt$, null, $txt$dairy$txt$, $txt$На упаковке нанесены код/аббревиатура материала, символ «рюмка-вилка» и петля Мёбиуса по ТР ТС 005/2011$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Символы мелкие и обычно размещены на дне, донной вклейке или боковом шве — часто вне кадра; кроме того, по примечанию к Приложению 3 цифровой код проставляется вместе с петлёй Мёбиуса, поэтому их отсутствие не всегда является нарушением$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS005","clause":"ст. 6, п. 2 «Требования к маркировке упаковки (укупорочных средств)»; Приложения 3 и 4","quote_ru":"Маркировка упаковки должна содержать цифровой код и (или) буквенное обозначение (аббревиатуру) материала в соответствии с Приложением 3 и символы в соответствии с Приложением 4 (рис. 1 — упаковка для пищевой продукции, «рюмка-вилка»; рис. 2 — петля Мёбиуса). По примечанию к Приложению 3 цифровой код и (или) буквенное обозначение размещаются внутри петли Мёбиуса."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
