insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.uz.state.language$txt$, null, $txt$dairy$txt$, $txt$Для рынка Узбекистана маркировка нанесена на государственном (узбекском) языке; дублирование на других языках допускается$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Понижено с checkable по двум причинам. (1) Норма требует, чтобы на государственном языке была ВСЯ обязательная маркировка — а это состав, срок годности, условия хранения и адрес, набранные кеглем от 0,8 мм на разных панелях; по одному кадру полнота не устанавливается, нужен полный обход всех панелей плюс стикер импортёра. (2) Само правовое основание требует пересверки: цитируемый акт утратил силу $txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"UZ490","clause":"не установлен точно: п. 6 Общего технического регламента (прил. к ПКМ РУз от 12.07.2017 № 490) УТРАТИЛ СИЛУ 02.09.2025 (ПКМ РУз № 553 от 02.09.2025); действующее основание не установлено","quote_ru":"Формулировка недействующей редакции (сверена дословно на lex.uz): «Маркировка пищевой продукции наносится в виде надписей на государственном языке, допускается дублирование сведений на других языках». Требование по существу, вероятно, сохранено в заменяющем акте, но какой это акт — НЕ УСТАНОВЛЕНО, поэтому ссылаться на п. 6 ПКМ № 490 как на действующую норму нельзя."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.uz.state.language$txt$, $txt$dairy.uz.language_present$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$language_state$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Присутствует ли обязательная маркировка на узбекском языке (латиница или кириллица), а не только на русском/английском?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["tarkibi","yaroqlilik muddati","saqlash sharoiti","ishlab chiqaruvchi","netto","sut","yog'lilik"],"expected_value":null,"language":["uz"]}$txt$::jsonb, $txt$Снять все панели: узбекский текст часто вынесен на отдельную наклейку-стикер импортёра$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.uz.state.language$txt$, $txt$dairy.uz.no_ru_only$txt$, 1, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$composition$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Является ли вся обязательная маркировка исключительно русскоязычной, без узбекского дубля?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"Информационная панель, где наименование, состав, срок годности и условия хранения приведены только на русском/английском языке"}$txt$::jsonb, $txt$Обязательно снять и стикер импортёра, если он наклеен поверх оригинальной этикетки$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.uz.asl.belgisi.status$txt$, null, $txt$dairy$txt$, $txt$Обязательная цифровая маркировка Data Matrix «Asl Belgisi» на молоко и молочную продукцию по состоянию на 02.08.2026 НЕ распространяется$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Проверять нечего: по подтверждённым источникам действующего требования для молока нет, а сам факт наличия или отсутствия правовой обязанности из изображения не выводится — отсутствие Data Matrix НЕ является нарушением. Отдельно: вывод «молока в перечне нет» — отрицательный факт, подтверждённый источниками по состоянию до января 2026 г.; приложения к ПКМ № 23 от 23.01.2026 не прочитаны, поэтому пер$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"UZASL","clause":"перечень товарных групп: ПКМ РУз № 322 от 20.05.2021 (подтверждён); ПКМ РУз № 23 от 23.01.2026 (существует, приложения с перечнем не прочитаны). Реквизиты ПКМ № 833 от 31.12.2020 и ПП-190 от 23.05.2025 не подтверждены — номер пункта перечня не установлен точно","quote_ru":"По подтверждённым источникам обязательной цифровой маркировке подлежат шесть групп: табачные изделия, алкогольная продукция, пиво и пивные напитки, лекарственные средства и медизделия, вода и безалкогольные напитки, бытовая техника. Молочной продукции в подтверждённом перечне нет. НЕ ПОДТВЕРЖДЕНО: расширение перечня на минеральные удобрения и СЗР с 01.05.2026 — эта дата и акт ПП-190 от 23.05.2025 "}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.consumer.ean13.barcode$txt$, null, $txt$dairy$txt$, $txt$Штриховой код EAN-13/GS1 наносится добровольно; для этого изготовитель должен быть зарегистрирован в GS1 Uzbekistan$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Наличие и структура EAN-13 детектируются и декодируются по фото, но легитимность префикса (регистрация владельца GTIN в GS1) по изображению не подтверждается; при этом отсутствие кода нарушением не является$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"UZ438","clause":"п. 8 Положения (прил. к ПКМ РУз от 21.09.1999 № 438, в ред. на 12.07.2024); ограничение — п. 5. Оба пункта сверены дословно на lex.uz 02.08.2026; акт действует (разделы III и IV Положения утратили силу в 2006 г.)","quote_ru":"«Маркировка продукции штриховыми кодами GS1 осуществляется добровольно»; субъекты, не зарегистрированные в ассоциации «GS1», не вправе наносить штриховые коды."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
