insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.consumer.ean13.barcode$txt$, $txt$dairy.barcode.ean13_structure$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_ean13$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Является ли считанный штрихкод корректным EAN-13 (13 цифр, верная контрольная цифра)?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["^[0-9]{13}$","478 (префикс GS1 Uzbekistan)"],"expected_value":"13-значный числовой GTIN с корректной контрольной цифрой"}$txt$::jsonb, $txt$Если код не декодируется — переснять ближе, без цифрового зума и под рассеянным светом$txt$, null)
