insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.trts022.name.and.manufacturer$txt$, null, $txt$dairy$txt$, $txt$На транспортной упаковке указаны наименование продукции и наименование/место нахождения изготовителя$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$и наименование, и реквизиты изготовителя — печатный текст на стенке короба, надёжно читается на фото при достаточном разрешении. ОГОВОРКА ПРИ ТРАКТОВКЕ РЕЗУЛЬТАТА: по ТР ТС 022/2011 ч.4.12 п.7 эта маркировка может наноситься не на короб, а на этикетку, на листок-вкладыш внутри короба либо содержаться в сопроводительных документах — поэтому положительная находка доказательна, а отсутствие надписи н$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4 ч. 4.2 п. 1 пп. 1 и 7","quote_ru":"Маркировка транспортной упаковки… должна содержать следующие сведения: 1) наименование пищевой продукции; … 7) наименование и место нахождения изготовителя пищевой продукции…"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
