insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.trts022.quantity.in.case$txt$, null, $txt$dairy$txt$, $txt$На транспортной упаковке указано количество продукции (число потребительских упаковок в коробе и/или масса нетто)$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$количество печатается словами/цифрами на этикетке короба («12 шт. × 0,9 л», «масса нетто 10,8 кг») и извлекается OCR как число с единицей. ОГОВОРКА ПРИ ТРАКТОВКЕ: сведения могут законно находиться на листке-вкладыше или в сопроводительных документах (ТР ТС 022/2011 ч.4.12 п.7); фактическое соответствие заявленного количества содержимому короба по фото не проверяется$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4 ч. 4.2 п. 1 пп. 2","quote_ru":"Маркировка транспортной упаковки, в которую помещена пищевая продукция, должна содержать следующие сведения: … 2) количество пищевой продукции;"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
