insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.trts022.storage.conditions$txt$, null, $txt$dairy$txt$, $txt$На транспортной упаковке указаны условия хранения (температурный режим)$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$условия хранения — текстовая надпись с числовым диапазоном температур, читается на фото стенки короба. ОГОВОРКА ПРИ ТРАКТОВКЕ: сведения могут законно находиться на листке-вкладыше или в сопроводительных документах (ТР ТС 022/2011 ч.4.12 п.7); соответствие указанного режима технологии продукта по фото не проверяется$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4 ч. 4.2 п. 1 пп. 5","quote_ru":"…5) условия хранения пищевой продукции;"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
