insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.trts022.batch.identification$txt$, null, $txt$dairy$txt$, $txt$На транспортной упаковке есть сведения, позволяющие идентифицировать партию (номер партии)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ДО partial: по фото подтверждается только наличие строки, ПОХОЖЕЙ на идентификатор партии; что этот номер действительно идентифицирует партию (сопоставим с производственным журналом и ТСД), из изображения не выводится — та же логика, по которой требование о дате изготовления помечено partial. Дополнительно: сведения о партии могут законно находиться на листке-вкладыше или в сопроводительн$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4 ч. 4.2 п. 1 пп. 6","quote_ru":"…6) сведения, позволяющие идентифицировать партию пищевой продукции (например, номер партии);"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.trts022.batch.identification$txt$, $txt$chk.tr022.batch_no$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$dates_batch$txt$, $txt$batch_number$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Нанесены ли на короб сведения, идентифицирующие партию (номер партии, «п.», LOT, «партия №»)?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["партия","№ партии","LOT","L:","партия №","partiya"],"expected_value":null,"language":["ru","uz","en"]}$txt$::jsonb, $txt$Номер партии часто совмещён с датой в одной строке кодировки — снять эту строку крупным планом целиком$txt$, null)
