insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.trts022.language.ru$txt$, null, $txt$dairy$txt$, $txt$Маркировка транспортной упаковки выполнена на русском языке (и на госязыке страны-члена, если это требуется её законодательством)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$язык надписей на фото определяется, но необходимость второго (государственного) языка зависит от законодательства страны назначения — из фото не выводится. Кроме того, ч.4.2 п.2 распространяется только на маркировку, нанесённую В ВИДЕ НАДПИСЕЙ, и содержит прямое изъятие по ч.4.8 п.3 (для продукции из третьих стран место нахождения изготовителя допускается латиницей при указании страны на русском) $txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4 ч. 4.2 п. 2 (с изъятием по ч. 4.8 п. 3)","quote_ru":"Предусмотренная пунктом 1 части 4.2 настоящей статьи и нанесенная в виде надписей маркировка пищевой продукции, помещенной в транспортную упаковку, должна быть нанесена на русском языке и на государственном(ых) языке(ах) государства-члена Таможенного союза при наличии соответствующих требований в законодательстве(ах) государства(в)-члена(ов) Таможенного союза, за исключением случаев, указанных в п"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.trts022.language.ru$txt$, $txt$chk.tr022.lang_ru_present$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Присутствует ли обязательная маркировка транспортной упаковки на русском языке?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["наименование","изготовитель","срок годности","условия хранения","масса нетто"],"expected_value":null,"language":["ru"]}$txt$::jsonb, $txt$Снять всю сторону с текстовым блоком; если этикетка только на узбекском/английском — зафиксировать все стороны короба, чтобы доказать отсутствие русского текста$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.trts022.transparent.pack.exemption$txt$, null, $txt$dairy$txt$, $txt$Маркировку допускается не наносить на транспортную упаковку, если маркировка потребительской упаковки доводится до потребителя без нарушения целостности транспортной упаковки$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$по фото видно, читается ли этикетка пакета сквозь прозрачную плёнку, но нельзя гарантировать, что ВСЕ обязательные сведения доступны без вскрытия (часть текста может быть на скрытых сторонах пачек)$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4 ч. 4.2 п. 3","quote_ru":"В случае, если маркировка… нанесенная на потребительскую упаковку… помещенную в транспортную упаковку, может быть доведена до сведения потребителей… без нарушения целостности транспортной упаковки, указанную маркировку допускается не наносить на транспортную упаковку."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.trts022.transparent.pack.exemption$txt$, $txt$chk.tr022.film_is_transparent$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$integrity$txt$, $txt$integrity$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$transparent_film_readable_consumer_label$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снять паллето-/термоусадочный блок фронтально с расстояния ~1 м так, чтобы этикетка хотя бы одного пакета была в кадре целиком$txt$, null)
