insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.trts022.transparent.pack.exemption$txt$, $txt$chk.tr022.label_legible_through_film$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Читаются ли сквозь прозрачную плёнку обязательные сведения потребительской упаковки (наименование, дата, срок годности, условия хранения, изготовитель)?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["наименование","годен до","условия хранения","изготовитель","масса нетто","жирности","%"],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Если блики плёнки мешают — снять под углом 20-30° и с рассеянным светом; отдельно снять каждую сторону блока$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.trts022.marking.placement.options$txt$, null, $txt$dairy$txt$, $txt$Маркировка продукции в транспортной упаковке может наноситься на саму упаковку, и (или) на этикетку, и (или) на листок-вкладыш, либо содержаться в сопроводительных документах$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$фото фиксирует только внешние поверхности грузового места; листок-вкладыш внутри короба и товаросопроводительные документы в кадр не попадают. Это сквозная оговорка ко ВСЕМ требованиям TRTS022 в этом файле: положительная находка надписи доказательна, отрицательная — нет. Требование внесено явно, чтобы модель фотоконтроля не выдавала fail там, где сведения законно доводятся иным способом$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4 ч. 4.12 п. 7","quote_ru":"Маркировка пищевой продукции, помещенной непосредственно в транспортную упаковку, предусмотренная частью 4.2 настоящей статьи, должна наноситься на транспортную упаковку, и (или) на этикетку, и (или) листок-вкладыш, помещаемый в каждую транспортную упаковку или прилагаемый к каждой транспортной упаковке, либо содержаться в документах, сопровождающих пищевую продукцию."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.trts033.group.pack.mass.batch.trademark$txt$, null, $txt$dairy$txt$, $txt$На каждой единице групповой, многооборотной или транспортной упаковки молочной продукции нанесены масса нетто, номер партии и товарный знак (при наличии)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ДО partial по трём причинам: (1) подпункт а) сформулирован как «товарный знак (при наличии)» — по фотографии нельзя установить, есть ли у изготовителя товарный знак, поэтому проверка отсутствия логотипа принципиально нефальсифицируема и остаётся информационной; (2) норма требует маркировку «на каждую единицу» групповой/транспортной упаковки — один кадр покрывает одну единицу и максимум дв$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS033","clause":"п. 67 пп. а)-в)","quote_ru":"На каждую единицу групповой, многооборотной или транспортной упаковки молока или молочной продукции наносится маркировка…: а) товарный знак (при наличии); б) масса нетто (масса брутто — на усмотрение изготовителя); в) номер партии…"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
