  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.trts033.group.pack.mass.batch.trademark$txt$, $txt$chk.tr033.batch_no_on_case$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$dates_batch$txt$, $txt$batch_number$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Нанесён ли на каждую единицу транспортной/групповой упаковки номер партии?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["партия","№ партии","LOT","партия №"],"expected_value":null,"language":["ru","uz","en"]}$txt$::jsonb, $txt$Проверить, что номер есть именно на коробе, а не только на паллетной этикетке$txt$, null)
