insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.trts033.group.pack.mass.batch.trademark$txt$, $txt$chk.tr033.trademark$txt$, 2, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$identity$txt$, $txt$trademark$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$trademark_logo$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Товарный знак требуется только «при наличии» — отсутствие логотипа на фото само по себе НЕ нарушение и не должно понижать оценку; чек оставлен как информационный (наличие/отсутствие логотипа фиксируется для отчёта, вывод о соответствии по нему не делается)$txt$, null)
