insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.trts033.handling.marks$txt$, null, $txt$dairy$txt$, $txt$На транспортной/групповой упаковке нанесены предупредительные надписи или манипуляционные знаки в соответствии с режимами хранения и транспортирования («ограничение температуры», «беречь от влаги», «беречь от солнечных лучей», «скоропортящийся груз»)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$наличие пиктограмм на фото распознаётся, но какие именно знаки ОБЯЗАТЕЛЬНЫ («избирательно… в соответствии с режимами») определяется технологией продукта, а не фотографией$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS033","clause":"п. 67 пп. г)","quote_ru":"г) предупредительные надписи или манипуляционные знаки (например: «беречь от солнечных лучей», «ограничение температуры», «беречь от влаги», «скоропортящийся груз») — наносятся избирательно в соответствии с режимами хранения и транспортирования…"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
