insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.trts033.handling.marks$txt$, $txt$chk.tr033.mark_perishable_or_sun$txt$, 2, $txt$presence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:perishable_or_keep_away_from_sunlight$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Знаки «Скоропортящийся груз» / «Беречь от солнечных лучей» — для охлаждённой молочной продукции ожидаемы, но наносятся избирательно$txt$, null)
