insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.trts033.shrinkwrap.exemption$txt$, null, $txt$dairy$txt$, $txt$При обёртывании групповой или транспортной упаковки прозрачными защитными полимерными материалами маркировку на них допускается не наносить — информацией служит маркировка потребительской тары$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$прозрачность плёнки и читаемость этикеток пачек оцениваются по фото, но «защитный полимерный материал» как категория упаковки и полнота доводимых сведений — нет$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"TRTS033","clause":"п. 68","quote_ru":"При обертывании групповой или транспортной упаковки молока или молочной продукции прозрачными защитными полимерными материалами допускается не наносить на них маркировку. В данном случае информацией для потребителей является маркировка потребительской тары."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.trts033.shrinkwrap.exemption$txt$, $txt$chk.tr033.wrap_transparent$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$other:check$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$transparent_shrink_wrap$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снять блок так, чтобы было видно: плёнка прозрачная (не молочная, не запечатанная сплошной печатью)$txt$, null)
