insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.trts033.shrinkwrap.exemption$txt$, $txt$chk.tr033.no_print_blocking_label$txt$, 1, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Перекрывает ли печать на плёнке (логотипы, рекламный слой) этикетку потребительской упаковки так, что маркировка нечитаема?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"сплошная запечатка/непрозрачный слой плёнки поверх этикеток пачек, делающий обязательные сведения нечитаемыми"}$txt$::jsonb, $txt$Снять кадр, на котором одновременно видно плёнку и текст этикетки под ней$txt$, null)
