insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.gost31450.temperature.limit.values$txt$, null, $txt$dairy$txt$, $txt$На групповой упаковке, транспортной таре и транспортном пакете нанесён знак «Ограничение температуры» с указанием минимального и максимального значений температуры$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ДО partial: пиктограмма и числовые пределы на фото читаются, но (1) корректность самих значений (соответствие минимума и максимума фактическому режиму хранения продукта) требует технологической документации; (2) требование «по ГОСТ 14192» включает размеры знака и ярлыка (разд. 6, приложение В), а без эталона масштаба в кадре они не измеряются; (3) п. 5.3.3 того же стандарта при обандероли$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"GOST31450","clause":"п. 5.3.2 (со ссылкой на ГОСТ 14192, знак № 5 табл. 1)","quote_ru":"Маркировка групповой упаковки, многооборотной и транспортной тары, транспортного пакета — … с нанесением манипуляционных знаков или предупредительных надписей: «Беречь от солнечных лучей» и «Ограничение температуры» с указанием минимального и максимального значений температуры по ГОСТ 14192…"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
