insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.gost31450.temperature.limit.values$txt$, $txt$chk.g31450.sun_sign_present$txt$, 2, $txt$presence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:keep_away_from_sunlight$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Знак «Беречь от солнечных лучей» (солнце с крестом) — по ГОСТ 31450 наносится совместно со знаком ограничения температуры$txt$, null)
