insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.gost31450.banderole.side.marking$txt$, null, $txt$dairy$txt$, $txt$При обандероливании прозрачными полимерными материалами маркировку на боковые поверхности допускается не наносить, но видимые надписи должны быть дополнены информацией о количестве мест и массе брутто, а непросматриваемые надписи (в том числе манипуляционные знаки) — вынесены на листы-вкладыши$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$факт обандероливания и наличие/отсутствие блока «количество мест + масса брутто» на фото различимы, но наличие листов-вкладышей с непросматриваемыми надписями внутри блока по внешнему кадру не устанавливается. ВАЖНО: это условное, а не безусловное освобождение — в отличие от ТР ТС 033/2013 п. 68, ГОСТ требует ДОПОЛНИТЬ видимые надписи количеством мест и массой брутто$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"GOST31450","clause":"п. 5.3.3","quote_ru":"При обандероливании прозрачными полимерными материалами маркировку на боковые поверхности групповой упаковки, транспортной тары и транспортного пакета допускается не наносить. Маркировкой в этом случае служат видимые надписи на потребительской таре или групповой упаковке, или транспортной таре, дополненные информацией о количестве мест и массе брутто. Непросматриваемые надписи, в том числе манипул"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.gost31450.banderole.side.marking$txt$, $txt$chk.g31450.places_and_gross_mass$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$transport_marking$txt$, $txt$transport_places$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Дополнены ли видимые сквозь плёнку надписи информацией о количестве мест и массе брутто?$txt$, null, $txt${"expect":"value_with_unit","unit":"шт|кг","pattern_hints":["количество мест","мест","масса брутто","брутто","кг","шт"],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Снять сторону обандероленного блока, где расположен ярлык или наклейка с количеством мест и массой брутто; если блок не найден — зафиксировать все стороны, иначе результат недостоверен$txt$, null)
