insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.gost31450.banderole.side.marking$txt$, $txt$chk.g31450.insert_sheet$txt$, 1, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$insert_sheet_with_handling_marks$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Лист-вкладыш виден, только если вложен под плёнку лицевой стороной наружу; отсутствие в кадре не означает отсутствия в упаковке — чек информационный$txt$, null)
