insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.gost31450.pallet.stacking.visibility$txt$, null, $txt$dairy$txt$, $txt$Транспортный пакет уложен так, чтобы с каждой боковой стороны была видна маркировка не менее одной единицы потребительской, групповой, транспортной или многооборотной тары$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$требование относится ко ВСЕМ боковым сторонам пакета, а один кадр покрывает максимум две; нужен согласованный набор из четырёх ракурсов одной и той же паллеты, иначе результат — «недостаточно кадров», а не «нарушение»$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"GOST31450","clause":"п. 5.4.4","quote_ru":"Укладку транспортного пакета осуществляют так, чтобы была видна маркировка не менее одной единицы потребительской тары и/или групповой упаковки, и/или транспортной тары, и/или многооборотной тары с каждой боковой стороны транспортного пакета."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.gost31450.pallet.stacking.visibility$txt$, $txt$chk.g31450.visible_label_per_side$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$transport_marking$txt$, $txt$other:check$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$readable_label_on_pallet_side$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снять паллету с четырёх сторон по кругу, каждый кадр — сторона целиком; на каждом кадре должна читаться хотя бы одна этикетка$txt$, null)
