insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.gost31450.pallet.stacking.visibility$txt$, $txt$chk.g31450.pallet_sides_coverage$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$geometry$txt$, $txt$other:check$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$pallet_side_faces$txt$, null, $txt$position$txt$, $txt${"target":"pallet_side_faces","min_mm":null,"min_area_fraction":null,"surface":"four_side_faces_of_transport_pallet","reference_scale":"масштабная привязка не требуется; требуется полнота ракурсов — 4 кадра одной паллеты по кругу"}$txt$::jsonb, $txt$Без всех четырёх ракурсов проверка даёт только частичный результат — помечать как «недостаточно кадров», а не как нарушение$txt$, null)
