insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.gost14192.inscriptions.and.export$txt$, null, $txt$dairy$txt$, $txt$Транспортная маркировка груза: информационные надписи (масса брутто и нетто) и — для экспорта — надписи «Экспорт», страна-изготовитель, номер грузового места дробью, на русском и иностранном языке$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$массу брутто/нетто и надписи «Экспорт»/страна на фото видно; номер контракта и заказа-наряда задаются внешнеторговым документом и по фото не верифицируются. Кроме того, п. 3.5 прямо допускает НЕ наносить массу брутто и нетто (или количество изделий), если они указаны в маркировке, характеризующей упакованную продукцию, а п. 7.1 ставит состав экспортных надписей в зависимость от заказа-наряда — поэ$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"GOST14192","clause":"п. 3.5, п. 7.2, п. 7.4, п. 7.10","quote_ru":"3.5 Информационные надписи должны содержать: массы брутто и нетто грузового места в килограммах… 7.4 …надписи «Экспорт», «Страна-изготовитель и (или) поставщик». 7.10 Транспортную маркировку наносят на русском языке и иностранном…"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$dairy.dairy.transport.gost14192.inscriptions.and.export$txt$, $txt$chk.g14192.gross_net_mass$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$identity$txt$, $txt$net_quantity$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Указаны ли на грузовом месте масса брутто и масса нетто в килограммах (либо количество изделий в штуках)?$txt$, null, $txt${"expect":"value_with_unit","unit":"кг|шт","pattern_hints":["брутто","нетто","кг","gross","net","шт"],"expected_value":null,"language":["ru","en"]}$txt$::jsonb, $txt$Информационные надписи ГОСТ 14192 располагают на одной из боковых сторон ящика — снять её целиком. Severity понижена с major до minor: п. 3.5 разрешает не наносить массы, если они указаны в маркировке, характеризующей упакованную продукцию$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
