insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.gs1.gtin.barcode.itf14$txt$, null, $txt$dairy$txt$, $txt$На гофрокороб нанесён штриховой код транспортной упаковки — ITF-14 (или GS1-128), кодирующий GTIN торговой единицы-короба$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$наличие и тип символики на фото определяются, но принадлежность GTIN компании, корректность контрольного разряда и качество печати по ISO/IEC 15416 по обычному фото не подтверждаются$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"GS1RU","clause":"не установлен точно (раздел «Штриховой код на транспортной упаковке»)","quote_ru":"Пересказ: на транспортную упаковку наносится 14-разрядный номер в виде штрихового кода ITF-14 (символика «2 из 5 чередующийся»); символ размером ~152,4 × 41,4 мм пригоден для прямой печати по гофрокартону. Это требование системы GS1, а не техрегламента."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
