insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$dairy.dairy.transport.gs1.gs1128.batch.date.and.sscc$txt$, null, $txt$dairy$txt$, $txt$Для передачи партии и дат применяется GS1-128 с идентификаторами применения (10) партия, (11) дата производства, (17) срок годности; логистическая единица идентифицируется SSCC в AI (00) на логистической этикетке GS1$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$наличие GS1-128 и человекочитаемых полей AI (00)/(10)/(17) на фото видно; уникальность SSCC, отсутствие повторного использования и совпадение закодированных данных с фактической партией по фото не проверяются$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$0401$txt$]::text[], $txt${"act_id":"GS1UK","clause":"не установлен точно (руководство GS1 «SSCC and logistics labels»; подтверждено GS1 US по GS1-128)","quote_ru":"Пересказ: SSCC — 18-значный код логистической единицы (extension digit + GS1 Company Prefix + серийный номер + контрольный разряд); наносится в GS1-128 с AI (00) в нижнем штрихкоде этикетки; повторное использование SSCC — не ранее 12 месяцев. AI (01) GTIN, (10) партия, (17) срок годности, (11) дата производства."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
