insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.month.year.manufacture$txt$, null, $txt$electronics$txt$, $txt$Указаны месяц и год изготовления либо информация о месте нанесения и способе определения года изготовления$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$дата часто печатается на коробке (D/C, MFG, 09/2025) и тогда читается, но норма адресована эксплуатационным документам — вывод об отсутствии по одной коробке делать нельзя$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"TRTS004","clause":"ст. 5 п. 4 (последний абзац перечня)","quote_ru":"Эксплуатационные документы должны содержать: «месяц и год изготовления низковольтного оборудования и (или) информацию о месте нанесения и способе определения года изготовления». Аналогично ТР ЕАЭС 037/2016 п. 12 подп. «ж»."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
