insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.eac.mark.present$txt$, null, $txt$electronics$txt$, $txt$На упаковке (или на изделии) нанесён единый знак обращения продукции на рынке ЕАЭС — знак EAC$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО при верификации. Положительный результат надёжен: знак EAC — устойчивый графический паттерн, детектируется на фото коробки. Отрицательный вывод по одному фото коробки недопустим: ТР ТС 004/2011 ст. 8 п. 3 требует нанесения знака на КАЖДУЮ ЕДИНИЦУ оборудования, а нанесение только на упаковку — лишь резервный вариант (п. 4); п. 5.1 Положения № 711 вообще допускает нанесение «на каждую едини$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"TRTS004","clause":"ст. 8 п. 3 и п. 4","quote_ru":"«Единый знак обращения... наносится на каждую единицу низковольтного оборудования любым способом, обеспечивающим четкое и ясное изображение в течение всего срока службы...»; п. 4: «Допускается нанесение... только на упаковку и в прилагаемых к нему эксплуатационных документах, если его невозможно нанести непосредственно на низковольтное оборудование»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
