insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.eac.mark.min.size$txt$, null, $txt$electronics$txt$, $txt$Базовый размер знака EAC не менее 5 мм; знак одноцветный и контрастирует с фоном$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$контраст оценивается прямо по пикселям, а миллиметры — только при наличии эталона масштаба в кадре$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"KTS711","clause":"п. 3.3 и п. 5.2 Положения","quote_ru":"п. 3.3: «Базовый размер должен быть не менее 5 мм. Размеры единого знака обращения должны гарантировать четкость его элементов и их различимость невооруженным глазом»; п. 5.2: «Изображение... должно быть одноцветным и контрастировать с цветом поверхности, на которую оно нанесено»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
