insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.emc.designation.on.pack$txt$, null, $txt$electronics$txt$, $txt$Для технического средства, подпадающего под ЭМС-регулирование (роутер, СВЧ, приборы с электроникой), обозначение ТС и изготовитель также нанесены на упаковку$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$требование текстуальное и совпадает по составу с ТР ТС 004; проверяется по тем же надписям на коробке$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"TRTS020","clause":"ст. 5 п. 1 абз. 2","quote_ru":"«наименование изготовителя и (или) его товарный знак, наименование и обозначение технического средства (тип, марка, модель - при наличии) должны быть также нанесены на упаковку»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
