insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.marking.language.ru$txt$, null, $txt$electronics$txt$, $txt$Маркировка выполнена на русском языке (для рынка ЕАЭС), единицы измерения и товарные знаки допускаются на других языках$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО при верификации. Факт наличия/отсутствия кириллического содержательного текста читается по фото (OCR + определение языка). Но нормативный вывод по коробке ограничен: на упаковку п. 9 ТР ЕАЭС 037/2016 выносит только наименование/обозначение изделия и наименование либо товарный знак изготовителя, а именно они по п. 13 прямо разрешены на других языках («буквенные товарные знаки, имена собств$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"TREAES037","clause":"раздел V п. 13 абз. 1","quote_ru":"«Нанесение маркировки и составление эксплуатационных документов осуществляются на русском языке и при наличии соответствующих требований в законодательстве государств-членов Союза — на государственном языке... Единицы измерения, буквенные товарные знаки, имена собственные... могут приводиться на других языках»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
