insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.rohs.substances.limits$txt$, null, $txt$electronics$txt$, $txt$Изделие соответствует ограничениям по содержанию опасных веществ (свинец, ртуть, кадмий, шестивалентный хром, ПББ, ПБДЭ) — ТР ЕАЭС 037/2016$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$фактическое содержание веществ определяется только лабораторным анализом (РФА/ГХ-МС), фото коробки об этом ничего не говорит$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"TREAES037","clause":"раздел IV п. 7-8; приложение № 2 (перечень опасных веществ и допустимые концентрации); маркировка знаком обращения — раздел VIII п. 33-36","quote_ru":"ИСПРАВЛЕНО при верификации (в первой версии были указаны «разделы III и VIII» — раздел III регламента посвящён правилам обращения, а не ограничению веществ). Проверено по извлечённому тексту PDF: п. 7 запрещает содержание опасного вещества в концентрации, превышающей допустимый уровень, указанный в перечне приложения № 2; приложение № 2 — свинец 0,1 %, ртуть 0,1 %, кадмий 0,01 %, шестивалентный хр"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.pack.material.identification$txt$, null, $txt$electronics$txt$, $txt$На упаковке нанесена идентификация материала: петля Мёбиуса с цифровым кодом и (или) буквенной аббревиатурой материала$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО при верификации. Петля Мёбиуса и код материала (для картонной коробки — PAP 20/21/22) печатаются на коробке и уверенно распознаются на фото — положительный результат надёжен. Но ст. 6 п. 1 допускает нанесение идентификационной маркировки «на упаковку и (или) сопроводительную документацию», поэтому её отсутствие на снятых панелях не доказывает нарушения; кроме того требование адресовано из$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"TRTS005","clause":"ст. 6 п. 1 и п. 2; Приложение 3 (примечания 1-2); Приложение 4 рис. 2","quote_ru":"п. 2: «Маркировка должна содержать цифровой код и (или) буквенное обозначение (аббревиатуру) материала... в соответствии с Приложением 3 и должна содержать символы в соответствии с Приложением 4: ...рисунок 2 (возможность утилизации использованной упаковки (укупорочных средств) - петля Мебиуса)». Примечания к Прил. 3: «Знаки идентификации проставляются следующим образом: внутри петли Мебиуса — циф"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
