insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.uz.state.language$txt$, null, $txt$electronics$txt$, $txt$Узбекистан: информация о товаре предоставляется потребителю на государственном (узбекском) языке$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО при верификации. Наличие содержательного текста на узбекском (латиница или кириллица) действительно распознаётся по фото коробки или стикера импортёра — положительный результат надёжен. Но закон допускает доведение информации «иным способом» (вкладыш, паспорт, гарантийный талон), поэтому отсутствие узбекского текста на упаковке само по себе не образует доказанного нарушения — это тот же с$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"UZZPP","clause":"ст. 6, часть третья","quote_ru":"«Информация о товаре (работе, услуге) предоставляется потребителю на государственном языке. Данная информация может быть дополнительно предоставлена и на других языках» (формулировка сверена по lex.uz 02.08.2026; норма — третья часть ст. 6, аналогичное правило о языке есть в ст. 5). При этом часть первая ст. 6 допускает доведение информации «на этикетках, маркировке или иным способом, принятым для"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
