insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.uz.warranty.service.life$txt$, null, $txt$electronics$txt$, $txt$Узбекистан: указаны гарантийные обязательства изготовителя и срок службы (годности) товара$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$надпись «Гарантия 12 месяцев / Kafolat 12 oy» на коробке читается, но закон допускает донесение этих сведений в технической документации (гарантийный талон), поэтому отсутствие на коробке не равно нарушению$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"UZZPP","clause":"ст. 6, часть вторая (перечень обязательных сведений)","quote_ru":"Информация о товаре должна содержать в том числе: «гарантийные обязательства изготовителя», «срок службы (годности) и сведения о необходимых действиях потребителя». Наличие обеих позиций в перечне части второй ст. 6 подтверждено по lex.uz 02.08.2026; дословная редакция подпунктов не выверялась посимвольно"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
