insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.uz.completeness.and.properties$txt$, null, $txt$electronics$txt$, $txt$Узбекистан: приведён перечень основных потребительских свойств товара (для электроники это в т.ч. состав комплекта поставки)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$блок «Комплектация / Комплект поставки / Ichidagilar» на коробке читается, но обязательность именно такого блока нормой прямо не установлена$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"UZZPP","clause":"ст. 6, часть вторая (перечень обязательных сведений)","quote_ru":"Информация о товаре должна содержать «перечень основных потребительских, в том числе специфических свойств». Прямое слово «комплектность» в приведённой норме отсутствует — комплект поставки трактуется как одно из основных потребительских свойств; норма о комплектности как отдельном реквизите упаковки не найдена."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
