insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.uz.mandatory.certification$txt$, null, $txt$electronics$txt$, $txt$Узбекистан: продукция, включённая в перечень обязательной сертификации, выпускается в обращение только при наличии сертификата соответствия (национальная система, знак соответствия O'z DSt)$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$наличие и подлинность сертификата — реестровый факт; изображение знака соответствия на коробке не доказывает действующего сертификата$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"UZPKM122","clause":"не установлен точно","quote_ru":"НОРМА НЕ ПОДТВЕРЖДЕНА. В первой версии утверждалось, что ПКМ РУз от 28.04.2011 № 122 утвердило действующий Перечень видов продукции, подлежащих обязательной сертификации. Перепроверка по lex.uz 02.08.2026: у постановления видны приложения № 1-9, из них Приложение № 1 утратило силу с 01.05.2021, № 2 — с 14.10.2015, № 4-6 — с 02.06.2017, Приложение № 3 утрачивает силу с 25.11.2024; действующими оста"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.safety.symbols.iec60417$txt$, null, $txt$electronics$txt$, $txt$Символы электробезопасности нанесены по IEC 60417: класс защиты II — двойной квадрат (5172); род тока — постоянный (5031) / переменный (5032)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$символы детектируются как графические паттерны, но нормативно они обязательны на самом изделии/табличке, а не на коробке — и только для оборудования соответствующего класса, что по фото коробки не определить$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"IEC60417","clause":"не установлен точно (IEC 60417-5172-1975; 5031; 5032)","quote_ru":"Пересказ базы IEC/ISO OBP: символ 5172 (двойной квадрат) идентифицирует оборудование, отвечающее требованиям для оборудования класса II по IEC 60536; символы 5031 и 5032 указывают на табличке номинальных данных, что оборудование пригодно только для постоянного или только для переменного тока. Обязательность нанесения устанавливается стандартами на конкретный вид оборудования (напр. ГОСТ IEC 60335-"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
