insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.ip.code$txt$, null, $txt$electronics$txt$, $txt$Степень защиты, обеспечиваемая оболочкой, обозначена IP-кодом установленного формата (IP + две характеристические цифры)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$формат кода на фото проверяется, а вот соответствие заявленного IP реальной конструкции требует испытаний по ГОСТ 14254$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"GOST14254","clause":"не установлен точно (структура кода — раздел «Обозначения» ГОСТ 14254-2015)","quote_ru":"Пересказ: код состоит из букв IP, первой характеристической цифры (защита от проникновения твёрдых предметов), второй характеристической цифры (защита от проникновения воды) и дополнительных букв; в редакции по IEC 60529:2013 введена степень IPX9. Обязательность указания IP для конкретного изделия определяется стандартом на этот вид оборудования — для ТР ТС 004/2011 это «характеристика, влияющая н"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
