insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.eu.marks.not.required$txt$, null, $txt$electronics$txt$, $txt$Знак CE и символ перечёркнутого мусорного бака — требования ЕС, а не ЕАЭС; их наличие допустимо, но знак EAC ими не заменяется$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$оба знака — устойчивые графические паттерны, детектируются на фото; вывод «CE вместо EAC» получается сопоставлением с результатом проверки знака EAC$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"WEEECE","clause":"Директива 2012/19/ЕС Приложение IX; EN 50419","quote_ru":"Пересказ: символ раздельного сбора EEE (перечёркнутый контейнер на колёсах) вводится Директивой 2012/19/ЕС (WEEE), Приложение IX — подтверждено по eur-lex 02.08.2026. Ст. 14(4) Директивы: государства-члены обеспечивают маркировку «preferably in accordance with the European standard EN 50419», числовых размеров сама Директива не устанавливает; цифра «минимальная высота 7 мм» взята из вторичных опис"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
