insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.ean13.barcode$txt$, null, $txt$electronics$txt$, $txt$Штриховой код EAN-13 (GTIN-13) на упаковке имеет корректную структуру: 13 цифр, префикс национальной организации GS1, контрольное число$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$символика EAN-13 декодируется прямо с фото, длина и контрольная цифра проверяются арифметически$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"GS1","clause":"не установлен точно (правила GS1, не нормативный акт)","quote_ru":"«Штриховой код EAN-13 представляет собой графическое изображение уникального международного номера товара EAN/UCC-13...»; структура: 3 цифры — префикс национальной организации GS1, 6 — регистрационный номер предприятия, 3 — порядковый номер продукции, 13-я — контрольное число (структура сверена по странице ГС1 РУС 02.08.2026). Обязательность штрихкодирования законом на источнике не подтверждена. П"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
