insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.elec.consumer.serial.number.imei$txt$, null, $txt$electronics$txt$, $txt$На упаковке нанесён серийный номер экземпляра (для мобильных устройств — IMEI, требуемый для регистрации в системе UZIMEI)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$серийный номер/IMEI на стикере читается и его формат проверяется (IMEI — 15 цифр, алгоритм Луна), но соответствие номера на коробке номеру внутри устройства и факт регистрации по фото не проверить$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"UZIMEI","clause":"не установлен точно","quote_ru":"Пересказ официального портала UZIMEI: регистрация IMEI обязательна для мобильных устройств, используемых в Республике Узбекистан; IMEI-код можно узнать на самом устройстве (*#06#), на коробке устройства и в гарантийном талоне. Точные реквизиты постановлений КМ РУз (упоминаются № 847 и № 778 2019 г.) по официальной странице не подтверждены. Серийный номер также назван в составе маркировки бытовой э"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
