insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.trts022.scope.not.applicable$txt$, null, $txt$electronics$txt$, $txt$ТР ТС 022/2011 (в т.ч. п. 4.2 о транспортной упаковке) к транспортной упаковке электроники НЕ применяется — маркировка мастер-картона этим регламентом не регулируется$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$это вывод о применимости правовой нормы к виду продукции, а не признак, наблюдаемый на изображении упаковки$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 1 ч. 1; п. 4.2 ст. 4","quote_ru":"ст. 1 ч. 1: «Настоящий технический регламент Таможенного союза распространяется на выпускаемую в обращение на единой таможенной территории Таможенного союза пищевую продукцию в части её маркировки». П. 4.2 озаглавлен «Общие требования к маркировке пищевой продукции, помещённой в транспортную упаковку» и перечисляет наименование, количество, дату изготовления, срок годности, условия хранения, сведе"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.gost14192.main.inscriptions.export$txt$, null, $txt$electronics$txt$, $txt$Основные надписи экспортной транспортной маркировки: номер контракта (заказа иностранного покупателя), наименование иностранного грузополучателя, пункт и страна назначения, номер грузового места дробью$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ ВЕРИФИКАЦИИ (было checkable). Сам текст читается OCR надёжно, но по фото нельзя установить две вещи, от которых зависит вердикт: (1) применимость требования — по п. 7.6 ГОСТ 14192-96 при автомобильной перевозке и в универсальных контейнерах основные надписи не наносят вовсе, а вид транспорта на кадре не виден; (2) отсутствие надписи на снятой стенке не равно её отсутствию на грузовом $txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"GOST14192","clause":"п. 7.2 (для экспорта); базовый состав — п. 3.3; изъятие по виду транспорта — п. 7.6 и п. 5.12","quote_ru":"п. 7.2: «Основные надписи: номер контракта и (или) номер заказа иностранного покупателя; номер заказа-наряда; номер грузового места — указывается дробью, в числителе — порядковый номер места в партии, в знаменателе — количество мест в партии; полное наименование или условное обозначение иностранного грузополучателя; наименование пункта назначения с указанием станции или порта перегрузки; страна на"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
