insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.gost14192.additional.inscriptions$txt$, null, $txt$electronics$txt$, $txt$Дополнительные надписи: наименование экспортирующей организации (грузоотправителя) и пункт отправления груза$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ ВЕРИФИКАЦИИ (было checkable). Текст блока «From/Грузоотправитель» читается OCR, но применимость требования снимается п. 7.6 при автомобильной и контейнерной отправке, а вид транспорта на кадре короба не виден; кроме того надпись может быть на не снятой стенке. Достоверен только положительный результат$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"GOST14192","clause":"п. 7.3 (для экспорта); базовый состав — п. 3.4; изъятие по виду транспорта — п. 7.6 и п. 5.12","quote_ru":"п. 7.3: «Дополнительные надписи: наименование экспортирующей организации — полное или условное; пункт отправления груза; станция и дорога отправления». П. 3.4 для внутренних перевозок дополнительно относит сюда «надписи транспортных организаций (содержание надписей и порядок нанесения устанавливаются правилами транспортных министерств)». ИЗЪЯТИЕ (добавлено при верификации) — п. 7.6: при автомобиль"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
