insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.gost14192.info.mass.gross.net$txt$, null, $txt$electronics$txt$, $txt$Информационные надписи: масса брутто и масса нетто грузового места в килограммах$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$наличие надписей «N.W.» и «G.W.» с числом и единицей «kg/кг» распознаётся на фото; достоверность самой цифры (соответствие фактической массе) фотоконтролем не проверяется$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"GOST14192","clause":"п. 7.4 (для экспорта); базовое правило и исключения — п. 3.5, п. 3.6, п. 7.7","quote_ru":"п. 7.4: «Информационные надписи: габаритные размеры грузового места в сантиметрах; массы нетто и брутто в килограммах; объём грузового места в кубических метрах». П. 3.5: «Допускается вместо массы нетто указывать количество изделий в штуках, а также не наносить массу брутто и нетто или количество изделий в штуках, если они указаны в маркировке, характеризующей упакованную продукцию». П. 3.6: масса"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
