insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.gost14192.info.dimensions.volume$txt$, null, $txt$electronics$txt$, $txt$Информационные надписи: габаритные размеры грузового места в сантиметрах и объём в кубических метрах (кроме случая, когда длина, ширина или диаметр не превышают 1 м)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$наличие строки габаритов и объёма читается на фото, но применимость освобождения (все размеры до 1 м) требует фактического замера короба, которого на кадре без референсного объекта нет$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"GOST14192","clause":"п. 7.4 (для экспорта); п. 3.5 (общее правило и пороги освобождения)","quote_ru":"п. 7.4: «габаритные размеры грузового места в сантиметрах; … объём грузового места в кубических метрах. … Не указывают габаритные размеры и объём грузового места при длине, ширине или диаметре до 1 м». П. 3.5: «Габаритные размеры не указывают, если ни один из габаритных размеров не превышает 1 м при транспортировании груза на открытом подвижном составе, 1,2 м — в крытом и 0,7 м при транспортирован"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gost14192.info.dimensions.volume$txt$, $txt$chk.transport.info.dimensions_text$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$transport_marking$txt$, $txt$transport_mass$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Указаны ли на упаковке габаритные размеры грузового места (длина × ширина × высота) с единицей измерения?$txt$, null, $txt${"expect":"value_with_unit","unit":"cm | mm","pattern_hints":["габарит","размеры","MEAS","MEASUREMENT","DIM","L×W×H","см","cm"],"expected_value":null,"language":["ru","en"]}$txt$::jsonb, $txt$Обычно печатается как «MEAS: 60×40×35 cm»; если строки нет — проверить, не подпадает ли короб под освобождение по п. 3.5/7.4$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
