insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gost14192.info.dimensions.volume$txt$, $txt$chk.transport.info.dimension_exemption_scale$txt$, 2, $txt$geometry$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$identity$txt$, $txt$net_quantity$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$master_carton_longest_side$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"master_carton_longest_side","min_mm":1000,"min_area_fraction":null,"surface":"side_panel","reference_scale":"нужен предмет известного размера в кадре (линейка, паллета 1200×800 мм, лист A4) либо снимок короба на паллете с известными габаритами; без масштаба вывод о применимости порога 1 м не делается"}$txt$::jsonb, $txt$Проверка вспомогательная: она нужна только чтобы решить, обязательны ли габариты и объём. Если масштаба в кадре нет — фиксировать статус «не определено», а не «нарушение»$txt$, null)
