insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.gost14192.export.country.marks$txt$, null, $txt$electronics$txt$, $txt$На экспортном грузовом месте нанесены надписи «Экспорт» и «Страна-изготовитель и (или) поставщик»$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$«MADE IN UZBEKISTAN» / «Страна-изготовитель» — это крупный печатный текст на стенке короба, надёжно распознаваемый OCR$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"GOST14192","clause":"п. 7.4","quote_ru":"п. 7.4 (информационные надписи для грузов, поставляемых на экспорт): «…надписи “Экспорт”, “Страна-изготовитель и (или) поставщик”»."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
