insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gost14192.export.country.marks$txt$, $txt$chk.transport.export.country_of_origin$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Указана ли на транспортной упаковке страна-изготовитель и (или) поставщик?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["страна-изготовитель","страна происхождения","MADE IN","COUNTRY OF ORIGIN","PRODUCT OF","O'zbekistonda ishlab chiqarilgan"],"expected_value":null,"language":["ru","en","uz"]}$txt$::jsonb, $txt$Чаще всего это строка «MADE IN UZBEKISTAN» на боковой стенке; засчитывается и русскоязычный вариант$txt$, null)
