insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gost14192.export.country.marks$txt$, $txt$chk.transport.export.export_word$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Присутствует ли на упаковке надпись «Экспорт» (Export)?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["Экспорт","EXPORT","FOR EXPORT","eksport"],"expected_value":null,"language":["ru","en","uz"]}$txt$::jsonb, $txt$На практике встречается реже, чем «MADE IN»; при отсутствии — фиксировать как несоответствие ГОСТ 14192-96 п. 7.4, но не как критичное$txt$, null)
