insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.gost14192.handling.marks.placement$txt$, null, $txt$electronics$txt$, $txt$Манипуляционные знаки нанесены в левом верхнем углу на двух соседних стенках тары; для экспортных грузов знаки № 1 «Хрупкое. Осторожно» и № 11 «Верх» — на четырёх сторонах, знак № 12 «Центр тяжести» — не менее чем на двух$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$наличие пиктограмм и их положение в левом верхнем углу видны на кадре, но требование «на четырёх/шести сторонах» проверяется только комплектом снимков всех стенок короба — по одному фото вывод сделать нельзя. Второе ограничение (добавлено при верификации): п. 5.11 отдаёт САМУ необходимость нанесения знаков стандартам и нормативным документам на продукцию, а п. 7.8/7.9 задают лишь размещение уже пр$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"GOST14192","clause":"п. 5.5, п. 7.8, п. 7.9; перечень знаков — п. 4.1 и таблица 1; необходимость нанесения — п. 5.11","quote_ru":"п. 5.5: «Манипуляционные знаки (предупредительные надписи) наносят на каждое грузовое место в левом верхнем углу на двух соседних стенках тары». П. 7.8: «Знаки № 1 и 11 наносят в левом верхнем углу с четырёх сторон». П. 7.9: «Знак № 12 наносят на шесть сторон упаковки на месте проекции фактического центра тяжести груза. Если форма и размеры упаковки не позволяют нанести знак № 12 на шесть сторон у"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gost14192.handling.marks.placement$txt$, $txt$chk.transport.handling.fragile_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:fragile$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Знак № 1 по ГОСТ 14192-96 — бокал/рюмка. Снять все четыре боковые стенки: для экспорта требуется на четырёх сторонах$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gost14192.handling.marks.placement$txt$, $txt$chk.transport.handling.this_way_up_present$txt$, 1, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:this_way_up$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Знак № 11 «Верх» — две вертикальные стрелки. Требуется на четырёх сторонах в левом верхнем углу (п. 7.8)$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gost14192.handling.marks.placement$txt$, $txt$chk.transport.handling.keep_dry_present$txt$, 2, $txt$presence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:keep_dry$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$ПОНИЖЕНО С major: ГОСТ 14192-96 знак № 3 не предписывает — по п. 5.11 необходимость устанавливает документ на продукцию или заказ-наряд. Знак № 3 «Беречь от влаги» — зонт (символ дождевых капель по п. 5.10 допускается не указывать). Для электроники в морских перевозках практически обязателен по контракту, но не по ГОСТ$txt$, null)
