insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gost14192.handling.marks.placement$txt$, $txt$chk.transport.handling.upper_left_corner_position$txt$, 3, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:any$txt$, null, $txt$position$txt$, $txt${"target":"handling_mark:any","min_mm":null,"min_area_fraction":null,"surface":"side_panel","reference_scale":"относительные координаты внутри рамки распознанной стенки короба: центр знака должен попадать в верхнюю левую четверть панели"}$txt$::jsonb, $txt$Требование п. 5.5 — левый верхний угол. Кадр должен захватывать стенку целиком, иначе положение определить нельзя$txt$, null)
