insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.iso780.symbol.colour.and.size$txt$, null, $txt$electronics$txt$, $txt$Графические символы обращения выполнены чёрным (или контрастным к фону) цветом без применения красного, оранжевого и жёлтого, высота символа 100, 150 или 200 мм$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$цвет символа и отсутствие красно-оранжево-жёлтой заливки определяются по кадру достоверно, а высота 100/150/200 мм требует масштаба в кадре$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"ISO780","clause":"п. 3.3 Colour of graphical symbols; п. 3.4 Size of graphical symbols; п. 3.2 Display; п. 1 Scope — нумерация подпунктов сверена только по бесплатному preview ISO и при верификации 02.08.2026 по первоисточнику НЕ перепроверена (iso.org отдаёт 403, стандарт платный)","quote_ru":"п. 3.3: «The colour used for graphical symbols shall be black. If the colour of the package is such that the black symbol would not show clearly, a panel of a suitable contrasting colour, preferably white, shall be provided as a background. Care shall be taken to avoid the use of colours such as red, orange or yellow, which could result in confusion with the labelling of dangerous goods.» П. 3.4: "}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.iso780.symbol.colour.and.size$txt$, $txt$chk.transport.iso780.no_warning_colours$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Выполнены ли манипуляционные символы красным, оранжевым или жёлтым цветом (что может быть спутано с маркировкой опасных грузов)?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"манипуляционные пиктограммы (зонт, бокал, стрелки «верх», центр тяжести), залитые красным, оранжевым или жёлтым цветом либо размещённые на панели этих цветов; исключение — знак опасности класса 9 и литиевая маркировка, которые к ISO 780 не относятся"}$txt$::jsonb, $txt$Снимать при равномерном освещении без цветного подсвета, иначе белый картон уходит в жёлтый и даёт ложное срабатывание. ВАЖНО: ГОСТ 14192-96 п. 5.10 прямо ПРЕДПИСЫВАЕТ знак № 13 «Тропическая упаковка» красным, знак № 6 — голубым и ДОПУСКАЕТ знак № 1 красным при железнодорожной перевозке; такие случаи не считать нарушением, а фиксировать как расхождение ГОСТ и ISO 780$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.iso780.symbol.colour.and.size$txt$, $txt$chk.transport.iso780.symbol_height$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$geometry$txt$, $txt$other:100_150_200$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:any$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"handling_mark:any","min_mm":100,"min_area_fraction":null,"surface":"side_panel","reference_scale":"линейка или объект известного размера в кадре; допустимо взять известную длину стенки мастер-картона из спецификации и пересчитать пиксели в мм"}$txt$::jsonb, $txt$ISO 780 п. 3.4 прямо разрешает меньший размер, если видимость сохраняется, — при недоборе высоты фиксировать замечание, а не нарушение$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.gs1.gtin.barcode.itf14$txt$, null, $txt$electronics$txt$, $txt$На мастер-картоне нанесён штриховой код с GTIN-14 (ITF-14 либо GS1-128) с сохранёнными несущими полосами и свободными зонами$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ ВЕРИФИКАЦИИ (было checkable). Наличие штрихкода, символика и 14 цифр в человекочитаемой строке распознаются надёжно — это остаётся checkable-частью. Но проверить нормируемые размеры (несущие полосы 4,65 мм, свободная зона 10,16 мм) в миллиметрах по фото нельзя: они заданы при увеличении 100 %, а фактическое увеличение символа допускается от 62,5-70 % до 100 % и на кадре неизвестно. Ед$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"GS1BC","clause":"разд. 3 и 3.4 (GTIN-14), разд. 5.1.1 (ITF-14), разд. 5.1.2 (GS1-128); первоисточник — GS1 General Specifications разд. 5.3 и 5.4","quote_ru":"разд. 3: «GS1 recommends treating such units as independent trade items, identified, and marked with their own GTIN.» Разд. 3.4: «GTIN-14 is always 14 digits in length. It never starts with a zero as the first digit and is NOT intended for point-of-sale/use.» Разд. 5.1.1: bearer bars «when printed on corrugate, the bearer bars are printed on all four sides of the barcode. When printed on labels, o"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gs1.gtin.barcode.itf14$txt$, $txt$chk.transport.gs1.barcode_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$barcode$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снять стенку с штрихкодом фронтально, без бликов и перспективных искажений; при печати прямо на гофрокартоне символ обрамлён толстой рамкой (bearer box)$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gs1.gtin.barcode.itf14$txt$, $txt$chk.transport.gs1.gtin14_digits$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_itf14$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Содержит ли человекочитаемая строка под штрихкодом 14-значный номер GTIN (GTIN-14)?$txt$, null, $txt${"expect":"value_with_unit","unit":"14 цифр","pattern_hints":["GTIN","ITF-14","EAN-14","(01)","DUN-14"],"expected_value":null}$txt$::jsonb, $txt$У ITF-14 под символом печатается ровно 14 цифр; у GS1-128 номер идёт с идентификатором применения «(01)» в скобках$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gs1.gtin.barcode.itf14$txt$, $txt$chk.transport.gs1.quiet_zone_clear$txt$, 2, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$barcode$txt$, null, $txt$quiet_zone_x_modules$txt$, $txt${"target":"barcode","min_mm":null,"min_x_modules":10,"min_area_fraction":null,"surface":"side_panel","reference_scale":"ИСПРАВЛЕНО ПРИ ВЕРИФИКАЦИИ: прежняя привязка к ширине символа 142,75 мм убрана — такого числа в процитированном источнике нет, а увеличение символа на коробе заранее неизвестно (допускается от 70 % на гофрокартоне и 62,5 % на этикетке до 100 %). Измерять в модулях X: ширина узкого штриха, измеренная в пикселях, принимается за 1 X, свободная зона слева и справа должна быть не менее 10 X (что и даёт 10,16 мм при 100 %). Абсолютный порог в мм проверять только при наличии линейки в кадре"}$txt$::jsonb, $txt$Свободные зоны слева и справа не должны быть перекрыты скотчем, текстом или другой этикеткой — это частая причина нечитаемости. Без масштаба выносить вердикт в миллиметрах нельзя — только в модулях X$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.gs1.sscc.logistic.label$txt$, null, $txt$electronics$txt$, $txt$Транспортный пакет (паллета) имеет GS1 Logistic Label с SSCC в GS1-128 под идентификатором применения (00); этикетки размещены на двух смежных сторонах, штрихкод на высоте 400-800 мм от основания и не ближе 50 мм от вертикального ребра$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$наличие этикетки, штрихкода и идентификатора «(00)» с 18-значным номером читается на кадре, но высота 400-800 мм от основания паллеты и наличие второй этикетки на смежной стороне требуют съёмки паллеты целиком с масштабом и как минимум двух ракурсов$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"GS1LL","clause":"GS1 Logistic Label Guideline (размещение этикетки на паллете); состав и обязательность SSCC — GS1BC разд. 8.1.2","quote_ru":"GS1BC разд. 8.1.2: «The SSCC is the single mandatory element for all GS1 Logistic Labels. Other information, when needed, shall comply with the specifications in this document and with the proper use of GS1 Application Identifiers»; «Only the bottom building block is mandatory»; «When adding or replacing a segment an SSCC already present must never be replaced or changed». GS1LL: «barcodes placed "}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gs1.sscc.logistic.label$txt$, $txt$chk.transport.gs1.sscc_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_gs1_128$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$barcode:gs1_128$txt$, null, null, $txt${"min_count":1,"required_sides":2,"sides_note":"GS1 требует две этикетки на смежных сторонах паллеты; min_count=1 — то, что подтверждается одним кадром, полное требование закрывается только двумя ракурсами (длинная и короткая смежные стороны)"}$txt$::jsonb, $txt$ИСПРАВЛЕНО ПРИ ВЕРИФИКАЦИИ: цель уточнена с общего «barcode» до «barcode:gs1_128» — с прежней целью эта проверка и проверка штрихкода мастер-картона получали один канонический предмет barcode_any и схлопывались компилятором в один пункт. Сюда же объединена бывшая отдельная проверка chk.transport.gs1.two_adjacent_sides: она имела тот же kind presence и тот же канонический предмет, то есть тоже схлопывалась и молча пропадала. Severity понижена с critical: GS1 — добровольный стандарт, государственной санкции нет. Снять нижнюю треть этикетки (SSCC всегда в самом нижнем штрихкоде) и обе смежные стороны паллеты$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gs1.sscc.logistic.label$txt$, $txt$chk.transport.gs1.sscc_ai00_18digits$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_sscc$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Присутствует ли под штрихкодом идентификатор применения «(00)» и следующий за ним 18-значный номер SSCC?$txt$, null, $txt${"expect":"value_with_unit","unit":"(00) + 18 цифр","pattern_hints":["(00)","SSCC","Serial Shipping Container Code","SSCC-18"],"expected_value":null}$txt$::jsonb, $txt$ПОНИЖЕНО С critical: стандарт GS1 добровольный, государственной санкции нет, критичность возникает только из договора с покупателем. Идентификатор применения в человекочитаемой строке всегда печатается в круглых скобках; блок «Serial Shipping Container Code» подписывает эту строку. Уникальность и корректность самого номера по фото не проверяется — только формат$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.gs1.sscc.logistic.label$txt$, $txt$chk.transport.gs1.label_height_on_pallet$txt$, 2, $txt$geometry$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$gs1_logistic_label$txt$, null, $txt$position$txt$, $txt${"target":"gs1_logistic_label","min_mm":400,"min_area_fraction":null,"surface":"pallet_side","reference_scale":"высота стандартной паллеты 1200×800 мм (настил ~144 мм) как референс либо линейка в кадре; штрихкод должен попадать в диапазон 400-800 мм от основания и быть не ближе 50 мм от вертикального ребра"}$txt$::jsonb, $txt$Снять паллету целиком с боку, включая пол под ней, иначе точку отсчёта высоты определить нельзя$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.ispm15.wood.packaging.mark$txt$, null, $txt$electronics$txt$, $txt$Деревянная тара, паллеты и подкладочный материал несут клеймо IPPC по ISPM 15: символ IPPC, двухбуквенный код страны, уникальный код производителя/оператора обработки и код обработки (HT, MB или DH), нанесённые несмываемо минимум на две противоположные стороны$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ ВЕРИФИКАЦИИ (было checkable). Наличие и структура клейма на одном кадре читаются надёжно — это checkable-часть. Но требование «минимум на две противоположные стороны» по одному ракурсу не подтверждается, а факт самой обработки (56 °C в толще древесины не менее 30 минут) и правомерность кода оператора устанавливаются актом обработки и реестром НОКЗР, а не фотографией. Кроме того, приме$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"ISPM15","clause":"Annex 2 «The mark and its application» (точная нумерация подпунктов по первоисточнику не подтверждена — см. note источника)","quote_ru":"Annex 2: клеймо состоит из символа IPPC слева, отделённого вертикальной линией от кодов справа, всё внутри прямоугольной или квадратной рамки; «The country code must be the International Organization for Standards (ISO) two-letter country code», далее уникальный код производителя/оператора обработки, присвоенный национальной организацией по карантину и защите растений, и код обработки по Annex 1 ("}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.ispm15.wood.packaging.mark$txt$, $txt$chk.transport.ispm15.mark_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$marks$txt$, $txt$ispm15$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$ispm15_ippc_mark$txt$, null, null, $txt${"min_count":1,"required_sides":2,"sides_note":"стандарт требует клеймо минимум на двух противоположных сторонах; min_count=1 — это то, что подтверждается одним кадром, полное требование закрывается только серией из двух противоположных ракурсов"}$txt$::jsonb, $txt$ОБЪЕДИНЕНО ПРИ ВЕРИФИКАЦИИ с бывшей отдельной проверкой chk.transport.ispm15.two_opposite_sides: обе имели один канонический предмет ispm15 и один kind presence, то есть схлопывались компилятором, и вторая молча пропадала из чек-листа. Снять боковые шашки (кубики) паллеты и торцевые доски ящика: клеймо чаще всего именно там, и нужны два противоположных ракурса. Если тара из фанеры/ДСП/OSB/шпона или древесина не толще 6 мм — клеймо не требуется, зафиксировать материал на фото$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.ispm15.wood.packaging.mark$txt$, $txt$chk.transport.ispm15.country_and_treatment_code$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Содержит ли клеймо двухбуквенный код страны с номером производителя (например «UZ-000») и код обработки HT, MB или DH?$txt$, null, $txt${"expect":"value_with_unit","unit":"XX-000 / YY","pattern_hints":["IPPC","HT","MB","DH","DB","UZ-","XX-000"],"expected_value":null,"language":["en"]}$txt$::jsonb, $txt$Код страны и номер оператора отделены дефисом, код обработки стоит отдельной строкой или после номера; MB (бромистый метил) во многих странах назначения уже не принимается — фиксировать в отчёте$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.ispm15.wood.packaging.mark$txt$, $txt$chk.transport.ispm15.no_extra_info_in_frame$txt$, 2, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Есть ли внутри рамки клейма посторонняя информация (логотипы, рекламные надписи, изменённый или перевёрнутый символ IPPC)?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"любые дополнительные надписи, логотипы или графика внутри рамки клейма помимо символа IPPC, кода страны, кода производителя и кода обработки; символ IPPC под углом или в зеркальном отражении"}$txt$::jsonb, $txt$Снять клеймо крупным планом фронтально; частая ошибка — фирменный логотип изготовителя паллеты, впечатанный внутрь рамки$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.lithium.un3481.battery.mark$txt$, null, $txt$electronics$txt$, $txt$Упаковка с литий-ионными аккумуляторами в оборудовании или в комплекте с оборудованием (UN 3481), отправляемая по Section II PI 966/967, несёт маркировку литиевых батарей: номер UN высотой не менее 12 мм, красная диагональная штриховка шириной не менее 5 мм, размер не менее 100 × 100 мм (уменьшение $txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$сам знак, красная штриховка и напечатанный на нём номер UN распознаются на кадре, но проверка минимального размера 100 × 100 мм и высоты цифр 12 мм требует масштаба. Главное ограничение (уточнено при верификации): по фото невозможно определить, требуется ли знак вообще, — это зависит от энергии элементов и батарей (порог 20/100 Вт·ч), числа элементов и упаковок в партии и выбранной секции упаковоч$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"IATADGR","clause":"IATA DGR 2026, Figure 7.1.C; Guidance Document разд. F.01 (вид знака и когда он требуется), F.02 (уменьшенный размер), F.04 (исключения), F.12 (когда знак наносить нельзя). Размеры знака для автомобильной перевозки по ДОПОГ — не установлен точно (см. quote_ru и note источника ADR529)","quote_ru":"F.01: «The battery mark is required as specified in the additional requirements of Section II of Packing Instructions 966, 967, 969, 970, 977 and 978. It is also required as specified in the additional requirements of Section IB of Packing Instructions 965, 968… The border of the mark must have red diagonal hatchings with a minimum width of 5 mm. The symbol (group of batteries, one damaged and emi"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.lithium.un3481.battery.mark$txt$, $txt$chk.transport.lithium.mark_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$un3481$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$lithium_battery_mark$txt$, null, null, $txt${"min_count":1,"applicability_unknown_from_photo":true}$txt$::jsonb, $txt$ПОНИЖЕНО С critical: отсутствие знака не является нарушением, пока по товаросопроводительным документам не установлено, что отправка идёт по Section II PI 966/967 (или Section IB PI 965/968); при Section I знак, наоборот, наносить нельзя (F.12), а по F.04 знак не нужен на упаковках только с кнопочными элементами в оборудовании и на партиях из не более двух упаковок с не более чем четырьмя элементами либо двумя батареями в оборудовании. Снять все стенки короба: знак может быть на любой грани и не обязан быть на одной грани со знаком класса 9 (F.09). Результат фиксировать как факт, вердикт выносить только вместе с документами$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.lithium.un3481.battery.mark$txt$, $txt$chk.transport.lithium.un_number_on_mark$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$un3481$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Указан ли на знаке номер UN 3481 (либо иной применимый: UN 3480, UN 3090, UN 3091, UN 3551, UN 3552)?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["UN 3481","UN3481","UN 3480","UN 3091","UN 3090","UN 3551","UN 3552"],"expected_value":null,"language":["en"]}$txt$::jsonb, $txt$ИСПРАВЛЕНО ПРИ ВЕРИФИКАЦИИ: раньше проверка требовала ровно «UN 3481». Так нельзя: правильный номер зависит от химии элемента, невидимой на фото (литий-металлический элемент в оборудовании — UN 3091, натрий-ионный — UN 3552), а по F.08 на одном знаке допускается сразу несколько номеров UN. Проверяется наличие хотя бы одного номера UN из перечня; вывод о соответствии номера содержимому делается по документам, а не по кадру$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.lithium.un3481.battery.mark$txt$, $txt$chk.transport.lithium.mark_min_size$txt$, 2, $txt$geometry$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$un3481$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$lithium_battery_mark$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"lithium_battery_mark","min_mm":100,"min_area_fraction":null,"surface":"side_panel","reference_scale":"линейка в кадре либо известные габариты мастер-картона из спецификации. ИСПРАВЛЕНО ПРИ ВЕРИФИКАЦИИ: упоминание порога 120 × 110 мм по ДОПОГ убрано из нормативной части — оно не подтверждено (см. note источника ADR529); если проверяется автомобильная отправка, порог берётся из действующей редакции ДОПОГ, а не отсюда"}$txt$::jsonb, $txt$Без масштаба в кадре размер не проверяется — фиксировать «не определено». Уменьшенный вариант 100 × 70 мм допустим только если ни одна грань упаковки не вмещает полноразмерный знак (F.02)$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.lithium.un3481.battery.mark$txt$, $txt$chk.transport.lithium.red_hatching$txt$, 3, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$warnings$txt$, $txt$warning_frame$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$lithium_battery_mark_hatching$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"lithium_battery_mark_hatching","min_mm":5,"min_area_fraction":null,"surface":"side_panel","reference_scale":"доля от известной высоты знака (100 мм или 110 мм): штриховка должна занимать не менее 5 % высоты знака по каждой стороне рамки"}$txt$::jsonb, $txt$Проверяется наличие именно красной диагональной штриховки по периметру и чёрного символа на белом/контрастном фоне$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.lithium.class9.label.and.psn$txt$, null, $txt$electronics$txt$, $txt$При отправке UN 3481 по Section I PI 966/967 (полностью регулируемый груз) на упаковке нанесены знак опасности класса 9 для литиевых батарей, номер UN с приставкой «UN», надлежащее отгрузочное наименование, наименования и адреса отправителя и получателя и нетто-масса$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$знак класса 9 и текстовые блоки (UN 3481, отгрузочное наименование, адреса, нетто-масса) распознаются на кадре, но сама применимость Section I определяется энергией элементов и батарей в Вт·ч и нетто-массой батарей в упаковке, которых на фото нет. Поэтому отсутствие знака класса 9 по фото не доказывает нарушения: подавляющая часть потребительской электроники идёт по Section II, где ни знак класса $txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"IATADGR","clause":"IATA DGR 2026 п. 7.1.4.1 (a), (b), (c) и 7.1.7 (пакеты-оболочки); блок-схема классификации литий-ионных батарей в Guidance Document. Разд. F.10 приведён как иллюстрация состава маркировки, но относится к Section IB PI 965/968/976, а не к UN 3481 — см. quote_ru","quote_ru":"F.10: «each package must be marked with: the UN Number preceded by “UN” and the Proper Shipping Name (DGR 7.1.4.1 (a)); the name and address of the shipper and consignee (DGR 7.1.4.1 (b)); in addition, the net weight as required by (DGR 7.1.4.1(c)) must be marked on the package; and the lithium battery mark… in addition to the Class 9 lithium battery hazard label and Cargo Aircraft Only label. Not"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.lithium.class9.label.and.psn$txt$, $txt$chk.transport.lithium.class9_label$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$un3481$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$hazard_label:class9_lithium$txt$, null, null, $txt${"min_count":1,"applicability_unknown_from_photo":true}$txt$::jsonb, $txt$ПОНИЖЕНО С critical: применимость Section I по фото не устанавливается, а при Section II знак класса 9 не требуется, поэтому его отсутствие нарушением само по себе не является. Ромб (квадрат на вершине) с семью вертикальными полосами в верхней половине и группой батарей внизу, цифра 9 в нижнем углу. Отличать от обычного знака класса 9 без изображения батарей$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.lithium.class9.label.and.psn$txt$, $txt$chk.transport.lithium.un_and_psn_text$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$un3481$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Нанесены ли на упаковку номер UN с приставкой «UN» и надлежащее отгрузочное наименование (например «UN 3481, Lithium ion batteries contained in equipment»)?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["UN 3481","Lithium ion batteries contained in equipment","Lithium ion batteries packed with equipment","proper shipping name","литий-ионные батареи"],"expected_value":null,"language":["en","ru"]}$txt$::jsonb, $txt$ПОНИЖЕНО С critical по той же причине, что и знак класса 9: при Section II эта надпись не требуется, а секция по фото не определяется. Текст печатается рядом со знаками опасности; применённую секцию фиксировать по сопроводительным документам. ЗАМЕЧАНИЕ К КОНВЕЙЕРУ: presence-проверка знака класса 9 и presence-проверка знака литиевых батарей из соседнего требования получают один канонический предмет un3481 и текущим компилятором схлопнутся в одну, хотя это два разных физических знака — нужна доработка словаря предметов$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.lithium.class9.label.and.psn$txt$, $txt$chk.transport.lithium.shipper_consignee_and_net_weight$txt$, 2, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer_address$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Указаны ли на упаковке наименования и адреса отправителя и получателя, а также нетто-масса опасного содержимого?$txt$, null, $txt${"expect":"value_with_unit","unit":"kg","pattern_hints":["shipper","consignee","net quantity","net weight","N.Q.","kg"],"expected_value":null,"language":["en","ru"]}$txt$::jsonb, $txt$Нетто-масса опасного груза отличается от нетто-массы товара — искать надпись рядом с блоком UN/PSN$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.lithium.class9.label.and.psn$txt$, $txt$chk.transport.lithium.no_conflicting_old_marks$txt$, 3, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$readability$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Присутствуют ли на упаковке устаревшие или противоречащие маркировки литиевых батарей (несколько разных знаков сразу, зачёркнутые или заклеенные предыдущие номера UN)?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"остатки старых знаков опасности, просвечивающие или выступающие рельефом из-под новой этикетки; частично заклеенные скотчем или зачёркнутые знаки и номера UN; нечитаемый из-за переклейки знак литиевых батарей"}$txt$::jsonb, $txt$ИСПРАВЛЕНО ПРИ ВЕРИФИКАЦИИ: из forbidden_terms убран пункт «UN 3480 и UN 3481 одновременно без соответствующего содержимого» — по F.08 знак прямо ДОПУСКАЕТСЯ нести несколько номеров UN сразу, а соответствие содержимому по фотографии закрытого короба не устанавливается, то есть проверка давала бы ложные срабатывания. Осталось то, что действительно видно: следы прежней маркировки. Повторно используемые короба — типовой источник ошибки; снимать при боковом освещении, чтобы был виден рельеф заклеенных знаков$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$electronics.transport.psi.integrity.strapping.stretch$txt$, null, $txt$electronics$txt$, $txt$Мастер-картон цел и заклеен по спецификации, транспортный пакет обвязан стреппинг-лентой и обмотан стретч-плёнкой, груз не выходит за габарит паллеты (практика предотгрузочной инспекции и требование контракта, а не государственная норма)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ ВЕРИФИКАЦИИ (было checkable). Повреждения короба, наличие заклейки, обвязки, стретч-плёнки и свес за габарит паллеты действительно фиксируются на кадре — но эталона в кадре нет. Тип ленты, минимальное число полос, число обвязок и предельная высота штабеля заданы утверждённой покупателем упаковочной спецификацией, которой система не располагает; без неё можно констатировать факт («две $txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"PSI","clause":"не установлен — норма отсутствует; критерий задаётся утверждённой упаковочной спецификацией покупателя и чек-листом PSI","quote_ru":"Пересказ практики (первоисточник — методики предотгрузочной инспекции): внешняя и внутренняя упаковка проверяется на соответствие утверждённой спецификации — маркировка короба, габариты и вес экспортного короба, влагозащита, штабельная прочность; короб должен быть заклеен указанным типом ленты и минимальным числом полос; паллетирование и стретч-плёнка применяются по спецификации покупателя, включа"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.psi.integrity.strapping.stretch$txt$, $txt$chk.transport.psi.carton_damage$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$integrity$txt$, $txt$integrity$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Есть ли на мастер-картоне повреждения — вмятины, разрывы, промокание, расслоение гофры, вскрытые и переклеенные швы?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"смятые рёбра и углы короба, разрывы и проколы картона, водяные разводы и следы намокания, расслоение гофрослоя, повторно заклеенные или вскрытые клапаны"}$txt$::jsonb, $txt$Снимать общий план короба со всех четырёх сторон плюс верх; для оценки промокания важно равномерное освещение без цветного подсвета$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.psi.integrity.strapping.stretch$txt$, $txt$chk.transport.psi.tape_seal$txt$, 1, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$integrity$txt$, $txt$integrity$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$carton_seal_tape$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снять верхний и нижний клапаны. Без загруженной упаковочной спецификации проверяется только сам факт заклейки; тип ленты и число полос (типовые схемы — H-tape, одна или три полосы) сверяются со спецификацией, поэтому при её отсутствии фиксировать наблюдение, а не вердикт$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.psi.integrity.strapping.stretch$txt$, $txt$chk.transport.psi.strapping$txt$, 2, $txt$presence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$integrity$txt$, $txt$integrity$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$strapping_band$txt$, null, null, $txt${"min_count":2}$txt$::jsonb, $txt$Обвязка транспортного пакета полимерной или стальной лентой; число обвязок берётся из спецификации покупателя, при её отсутствии — фиксировать фактическое количество без вердикта$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.psi.integrity.strapping.stretch$txt$, $txt$chk.transport.psi.stretch_wrap$txt$, 3, $txt$presence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$integrity$txt$, $txt$integrity$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$stretch_wrap$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Стретч-плёнка должна полностью укрывать штабель и захватывать настил паллеты; снимать паллету целиком с боку. ЗАМЕЧАНИЕ К КОНВЕЙЕРУ: три presence-проверки этого требования (заклейка, обвязка, стретч-плёнка) получают один канонический предмет integrity и текущим компилятором схлопнутся в одну — нужна доработка словаря предметов, данные здесь намеренно оставлены раздельными$txt$, null)
