insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$electronics.transport.psi.integrity.strapping.stretch$txt$, $txt$chk.transport.psi.no_overhang$txt$, 4, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$integrity$txt$, $txt$integrity$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Выступает ли груз за габарит паллеты (свес коробов за край настила)?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"коробы, выступающие за кромку настила паллеты; смещённый или заваленный штабель; коробы, продавленные нижним ярусом"}$txt$::jsonb, $txt$Снимать паллету с боку строго фронтально, чтобы кромка настила и кромка нижнего яруса коробов были в одной плоскости кадра$txt$, null)
