insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.consumer.ean.upc.required$txt$, null, $txt$gs1$txt$, $txt$Потребительская единица, проходящая через розничный POS, должна нести штрихкод семейства EAN/UPC (EAN-13, EAN-8, UPC-A, UPC-E) или GS1 DataBar Retail POS$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$наличие линейного штрихкода на потребительской упаковке видно на фото и однозначно детектируется$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 2.1.3 «Fixed measure trade items scanned at retail POS»","quote_ru":"«The trade item must be identified with a GTIN-8, GTIN-12, or GTIN-13. It must carry a barcode from the EAN/UPC symbology family or the GS1 DataBar Retail POS family»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.consumer.ean.upc.required$txt$, $txt$codes.consumer.barcode_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$barcode$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снять панель упаковки, где нанесён штрихкод (обычно задняя/нижняя/боковая). Если код не найден — сделать 4 снимка со всех сторон плюс дно.$txt$, null)
