insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.consumer.ean.upc.required$txt$, $txt$codes.consumer.symbology_is_ean_upc$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_ean13$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Является ли найденный линейный код символикой семейства EAN/UPC (EAN-13, EAN-8, UPC-A, UPC-E) или GS1 DataBar?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["EAN-13","EAN-8","UPC-A","UPC-E","GS1 DataBar"],"expected_value":"EAN13|EAN8|UPCA|UPCE|DATABAR"}$txt$::jsonb, $txt$Определяется декодером по типу символики. ITF-14 или Code 128 на потребительской единице для POS — нарушение выбора символики.$txt$, null)
