insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.ean13.structure.13.digits$txt$, null, $txt$gs1$txt$, $txt$EAN-13 — ровно 13 цифр: префикс GS1 + номер предприятия (GS1 Company Prefix) + номер продукции + контрольная цифра$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$после декодирования длина строки проверяется тривиально, а HRI под кодом читается OCR. ВАЖНО (ревизия 2026-08-02): проверяемой является ТОЛЬКО длина 13 цифр и контрольная цифра. Разбивка «478 + 6 цифр предприятия + 3 цифры продукции» — национальная конвенция GS1 Uzbekistan из GS1UZ, а НЕ правило GS1 GenSpecs: по § 1.4.4 (стр. 22 релиза 21.0.1) GS1 Company Prefix имеет переменную длину 4–12 цифр. П$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1UZ","clause":"Руководство по штриховому кодированию, раздел «Структура EAN-13»","quote_ru":"«Первые 3 цифры — префикс или код Национальной организации (для Узбекистана — 478); следующие 6 цифр — номер предприятия внутри Ассоциации; следующие 3 цифры — порядковый номер продукции; последняя, 13-я цифра — контрольная цифра»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.ean13.structure.13.digits$txt$, $txt$codes.ean13.length_13$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_ean13$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Содержит ли декодированное значение EAN-13 ровно 13 цифр (и только цифры)?$txt$, null, $txt${"expect":"specific_value","unit":"digits","pattern_hints":["^[0-9]{13}$"],"expected_value":"13"}$txt$::jsonb, $txt$Проверка на декодированной строке. EAN-8 → 8 цифр, UPC-A → 12 цифр, GTIN-14 в ITF-14 → 14 цифр.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.ean13.structure.13.digits$txt$, $txt$codes.ean13.hri_matches_bars$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_hri$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Совпадает ли человекочитаемая подпись (HRI) под штрихкодом с декодированным значением символа?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["HRI","цифры под штрихкодом"],"expected_value":"hri == decoded"}$txt$::jsonb, $txt$Классический дефект допечатной подготовки: макет обновили, штрихи перегенерировали, а подпись осталась старой (или наоборот). Требуется читаемое фото HRI.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.gs1.prefix.478.uzbekistan$txt$, null, $txt$gs1$txt$, $txt$Префикс 478 закреплён за GS1 Uzbekistan; при этом GS1-префикс НЕ указывает страну происхождения товара$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$первые 3 цифры проверяются арифметически после декодирования, но вывод о стране происхождения из них делать нельзя — это методологическая ошибка$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 2.1.3.1 (цитата про происхождение — стр. 35), § 1.4.2 «GS1 Prefix» + Figure 1.4.2-1 (диапазоны префиксов, стр. 21–22), § 1.4.4 «GS1 Company Prefix» (длина 4–12 цифр)","quote_ru":"«The GS1 Company Prefix is allocated by a GS1 Member Organisation to a system user. It makes the ID number unique worldwide but does not identify the origin of the item» — сверено дословно по стр. 35 релиза 21.0.1 (это § 2.1.3.1, а не § 1.4.4). Значение 478 = GS1 Uzbekistan — по GS1UZ/GS1ORG_UZ, в самом GS1GS соответствие «префикс → организация-член» не приводится."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.gs1.prefix.478.uzbekistan$txt$, $txt$codes.prefix.valid_range$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$gtin_consistency$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Попадает ли префикс декодированного GTIN в диапазон Restricted Circulation Number (02, 04, 20–29), то есть является ли код внутренним, а не глобально уникальным?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["RCN 02","RCN 04","RCN 20-29","478"],"expected_value":"prefix_not_in_rcn_ranges"}$txt$::jsonb, $txt$ИСПРАВЛЕНО при ревизии 2026-08-02. Раньше здесь стояло «валидный диапазон 300–950, 952–976» — это грубая ошибка: по Figure 1.4.2-1 GS1 GenSpecs 21.0.1 (стр. 21–22) GS1 Company Prefix выдаётся также из диапазонов 001–019, 03, 06–09 и 10–19. Проверка в прежней редакции забраковала бы КАЖДЫЙ американский/канадский GTIN-12 и любой EAN-13, начинающийся с 0 или 1. Полная таблица: 001–019, 03, 06–09, 10–19, 300–950, 952–976 — company prefixes (валидны); 02, 04, 20–29 — RCN (внутренние коды сети/предприятия, не должны выходить за пределы своей зоны обращения); 05 — резерв GS1 US; 951 — EPC GID; 977 — ISSN; 978–979 — ISBN/ISMN; 980 — чеки возврата; 981–989 и 99 — купоны. Правильная логика проверки: флаг ставится только на RCN-диапазоны, всё остальное считается валидным по умолчанию.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.gs1.prefix.478.uzbekistan$txt$, $txt$codes.prefix.no_country_of_origin_claim$txt$, 1, $txt$absence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Есть ли рядом со штрихкодом надпись, утверждающая страну происхождения на основании префикса (например «478 — сделано в Узбекистане», «страна по штрихкоду»)?$txt$, null, $txt${"forbidden_terms":["страна по штрих-коду","определите страну по штрихкоду","478 — сделано в Узбекистане"],"forbidden_imagery":"таблица соответствия «префикс → страна», размещённая как подтверждение происхождения товара"}$txt$::jsonb, $txt$Префикс — это код организации-члена GS1, выдавшей номер, а не страна производства. Страна происхождения подтверждается отдельной надписью и документами, а не префиксом.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.check.digit.mod10.algorithm$txt$, null, $txt$gs1$txt$, $txt$Контрольная цифра всех числовых ключей GS1 (GTIN-8/12/13/14, SSCC-18) считается по единому алгоритму mod-10 и обязана сходиться$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$чисто арифметическая проверка над декодированной строкой — самая дешёвая и самая надёжная проверка во всей системе$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 7.9.1 «Standard check digit calculations for GS1 data structures», Figure 7.9.1-1","quote_ru":"«This algorithm is identical for all fixed length numeric GS1 data structures … Multiply value of each position by x3/x1 … Accumulated results = sum … Subtract sum from nearest equal or higher multiple of ten = check digit»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.check.digit.mod10.algorithm$txt$, $txt$codes.check_digit.recompute$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_checkdigit$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Совпадает ли последняя цифра декодированного номера с контрольной цифрой, пересчитанной по mod-10?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["mod10","check digit","контрольная цифра"],"expected_value":"recomputed_check_digit == last_digit"}$txt$::jsonb, $txt$Алгоритм: отбросить последнюю цифру; нумеровать оставшиеся справа налево, начиная с 1; цифры на нечётных позициях (считая справа) умножить на 3, на чётных — на 1; сложить; контрольная цифра = (10 − сумма mod 10) mod 10. Работает одинаково для 8/12/13/14/18 цифр. Если не сходится — либо ошибка декодирования (переснять резче), либо код действительно битый.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.arithmetic.post.decode.system.checks$txt$, null, $txt$gs1$txt$, $txt$После декодирования обязателен набор логических проверок содержимого: диапазоны полей дат, длина полей переменной длины, отсутствие букв в числовых полях, валидность GS1-префикса$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$все перечисленные проверки выполняются над декодированной строкой без каких-либо измерений на изображении — это ядро дешёвого автоматического контроля$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 7.2.7 «Check digit calculation and other system checks»","quote_ru":"«Other logical tests checks are recommended for reasonable data content, such as verifying: Data field ranges (e.g., month < 13 and > 00). The maximum length of a variable length element string. No alphanumeric characters in numeric only fields. Correct GS1 Prefixes»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.arithmetic.post.decode.system.checks$txt$, $txt$codes.arith.field_ranges$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$other:01_12_00_31_00$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Все ли числовые поля декодированной строки лежат в допустимых диапазонах (месяц 01–12, день 00–31, где 00 = последний день месяца)?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["MM 01-12","DD 00-31","YYMMDD"],"expected_value":"all_ranges_valid"}$txt$::jsonb, $txt$Ловит перепутанные форматы даты (ДДММГГ вместо ГГММДД) — частая ошибка при настройке принтера.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.arithmetic.post.decode.system.checks$txt$, $txt$codes.arith.numeric_only_fields$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_sscc$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Отсутствуют ли буквы и служебные символы в полях, которые по спецификации только числовые (GTIN, SSCC, даты, количество)?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["N14","N18","N6","N..8"],"expected_value":"numeric_fields_are_numeric"}$txt$::jsonb, $txt$Буква в GTIN почти всегда означает ошибку декодирования из-за смазанного/бликующего фото — сначала переснять.$txt$, null)
