insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.arithmetic.post.decode.system.checks$txt$, $txt$codes.arith.variable_length_limit$txt$, 2, $txt$text_semantic$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$identity$txt$, $txt$serial_number$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Не превышает ли поле переменной длины свой лимит (AI (10) партия — до 20 символов, AI (21) серийный номер — до 20 символов)?$txt$, null, $txt${"expect":"specific_value","unit":"chars","pattern_hints":["X..20","AI (10)","AI (21)"],"expected_value":"len <= 20"}$txt$::jsonb, $txt$Формат по GS1GS § 3.2: AI (10) = N2+X..20, AI (21) = N2+X..20.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.grouping.itf14.or.gs1128$txt$, null, $txt$gs1$txt$, $txt$Для групповой/транспортной упаковки (короба) GS1 даёт ВЫБОР носителя: ITF-14, GS1-128/GS1 DataBar с AI (01) либо символ семейства EAN/UPC; ITF-14 при этом не может нести атрибутивные данные (только 14 цифр GTIN)$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$тип символики на коробе определяется декодером однозначно; но сам по себе выбор символики нарушением не является — GS1 формулирует его как carrier choices («may»), поэтому при ревизии 2026-08-02 deontic понижен с obligation до permission, а проверка символики — с major до minor$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 2.1.7.2 «Trade item groupings of identical trade items» — Carrier choices (стр. 53); § 5.3 «Linear barcodes - ITF-14 symbology specifications»","quote_ru":"«ITF-14 symbols may be used on trade item groupings where printing conditions require the application of a less demanding symbology. ITF-14 symbols can encode the GTIN-12, GTIN-13, or GTIN-14 of the item». ВАЖНО: в том же перечне Carrier choices (стр. 53) прямо сказано «Symbols from the EAN/UPC symbology family (UPC-A, UPC-E, and EAN-13) may be used to encode the GTIN-12 or GTIN-13 of the trade it"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.grouping.itf14.or.gs1128$txt$, $txt$codes.case.barcode_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$barcode$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снять ту боковую грань короба, где нанесён код. Рекомендуется фотографировать две смежные грани.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.grouping.itf14.or.gs1128$txt$, $txt$codes.case.symbology_allowed$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_ean13$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Какая символика использована на коробе — ITF-14, GS1-128, GS1 DataBar или EAN/UPC? (все они допустимы по § 2.1.7.2; фиксировать для последующего анализа, а не как нарушение)$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["ITF-14","GS1-128","Interleaved 2 of 5","EAN-13","GS1 DataBar"],"expected_value":"ITF14|GS1_128|DATABAR|EAN13|UPCA|UPCE|EAN8"}$txt$::jsonb, $txt$ИСПРАВЛЕНО при ревизии 2026-08-02: раньше проверка объявляла EAN-13 на коробе нарушением (severity major). Это противоречит § 2.1.7.2 GS1 GenSpecs, где EAN/UPC прямо перечислен среди допустимых носителей для trade item grouping. EAN-13, напечатанный напрямую по гофрокартону, — это риск качества печати (тонкие штрихи «плывут», для того и существует ITF-14 с бо́льшим X-dimension), а не нарушение выбора символики. Реальное нарушение ловится другими проверками: непрочтение кода и нарушенная quiet zone.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.grouping.itf14.or.gs1128$txt$, $txt$codes.case.itf14_has_no_attributes$txt$, 2, $txt$absence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_itf14$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Содержит ли декодированная строка ITF-14 / Interleaved 2 of 5 на коробе НЕ ровно 14 цифр (например 6 или 16 цифр — признак использования нестандартного ITF вместо ITF-14)?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"символ Interleaved 2 of 5, декодируемый в строку длиной, отличной от 14 цифр"}$txt$::jsonb, $txt$ПЕРЕПИСАНО при ревизии 2026-08-02. Прежняя формулировка искала в декодированном ITF-14 подстроки «(10)», «(17)» и т. п. — она была вакуумной: ITF-14 физически не кодирует идентификаторы применения, только 14 цифр, поэтому такие подстроки не могли появиться никогда, и проверка не срабатывала бы ни на одном фото. Наблюдаемый по фото дефект — это ITF другой длины (ITF-6/ITF-16). Тезис «нужны партия/дата — ставь отдельный GS1-128 или GS1 DataMatrix» остаётся верным, но проверить по фото «нужны ли атрибуты» невозможно: это свойство бизнес-процесса, а не изображения.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.grouping.gtin14.indicator.relation$txt$, null, $txt$gs1$txt$, $txt$GTIN-14 короба строится как: индикатор 1–8 + GTIN потребительской единицы без её контрольной цифры + новая контрольная цифра$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО при ревизии 2026-08-02 (было checkable). Арифметика тривиальна, но входные данные для неё по одному фото не добываются: нужны ДВА кадра — потребительской единицы и короба — и внешнее подтверждение, что это один и тот же SKU из одной партии. С одного фото короба проверяемо только то, что первая цифра GTIN-14 — индикатор 1–8; связь «тело GTIN-14 == GTIN-13 потребительской единицы» без второ$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 2.1.7.2, Figure 2.1.7.2-2 «Different groupings of the same trade item»","quote_ru":"«Indicator | GTIN of trade item contained in the grouping, less its check digit | New check digit». «The indicator is a digit with a value of 1 to 8 … Indicator digit 9 is reserved for variable measure trade items»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.grouping.gtin14.indicator.relation$txt$, $txt$codes.hierarchy.case_matches_consumer$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_checkdigit$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Совпадает ли «тело» GTIN-14 на коробе (цифры 2–13) с GTIN-13 потребительской единицы без её контрольной цифры?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["GTIN-14","indicator","GTIN-13"],"expected_value":"case_gtin[1:13] == consumer_gtin13[0:12]"}$txt$::jsonb, $txt$Нужны два кадра одной партии: потребительская единица и короб. Если второго кадра нет — статус «не проверено» (severity понижена с critical до major при ревизии 2026-08-02: критический вердикт по проверке, которая в большинстве съёмок физически не выполнима, порождает ложные тревоги). Если совпадения нет — либо короб от другого SKU, либо иерархия заведена неверно.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.grouping.gtin14.indicator.relation$txt$, $txt$codes.hierarchy.indicator_1_to_8$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$gtin_consistency$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Является ли первая цифра GTIN-14 на коробе индикатором в диапазоне 1–8 (9 зарезервирована для товаров переменной меры, 0 — для GTIN-13/12, дополненного нулём)?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["indicator 1-8","indicator 9 = variable measure"],"expected_value":"1-8"}$txt$::jsonb, $txt$Индикатор 9 без сопутствующего AI меры/количества (30 или 3nnn) — нарушение § 4.14.2.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.itf14.bearer.bars$txt$, null, $txt$gs1$txt$, $txt$У ITF-14 обязательна усиливающая рамка (bearer bar): при печати с печатных форм — сплошная толщиной 4,83 мм, полностью окружающая символ вместе с quiet zone; без печатных форм — минимум 2X сверху и снизу$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$наличие рамки видно на фото, но её нормированная толщина 4,83 мм требует известного масштаба кадра$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 5.3.2.4 «Bearer bars»","quote_ru":"«The bearer bar is mandatory unless it is not technically feasible to apply it … For printing methods requiring printing plates, the nominal bearer bar has a constant thickness of 4.83 millimetre (0.190 inch) and must completely surround the symbol, including its Quiet Zones … For printing methods that do not require printing plates, the bearer bar SHALL be a minimum of twice the width of a narrow"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.itf14.bearer.bars$txt$, $txt$codes.itf14.bearer_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_itf14$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$itf14_bearer_bar$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снять ITF-14 фронтально, без перспективных искажений. Рамка — жирные полосы сверху и снизу штрихов (и часто по бокам).$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.itf14.bearer.bars$txt$, $txt$codes.itf14.bearer_thickness$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_itf14$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$itf14_bearer_bar$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"itf14_bearer_bar","min_mm":4.83,"min_area_fraction":null,"surface":"case_side_panel","reference_scale":"нужен эталон масштаба в кадре (линейка / объект известного размера) либо известные габариты короба; альтернатива — оценка через X-dimension самого символа, но тогда результат наследует погрешность измерения X"}$txt$::jsonb, $txt$Проверять только когда масштаб достоверен. Без масштаба выдавать «не проверено», а не «нарушение».$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.itf14.quiet.zone.and.hri.gap$txt$, null, $txt$gs1$txt$, $txt$У ITF-14 обязательны светлые поля (quiet zone) слева и справа минимум 10X, и зазор минимум 1,02 мм между нижней линией bearer bar и верхом HRI$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$«грязная» quiet zone (текст/графика в светлом поле) видна на фото, но численное соблюдение 10X требует измерения X-dimension$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 5.3.2.2 «Dimensions and tolerances»","quote_ru":"«The Quiet Zones to the right and left of the symbol are compulsory. The minimum width of each Quiet Zone is 10X. A minimum space of 1.02 millimetre (0.040 inch) between the bottom line of the bearer bar and the top of the human readable characters is required»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.itf14.quiet.zone.and.hri.gap$txt$, $txt$codes.itf14.quiet_zone_clean$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_itf14$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Находятся ли в светлом поле слева/справа от ITF-14 посторонние элементы — текст, линии, рамки, логотипы, край наклейки?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"любой печатный элемент, линия обреза, шов коробки или край этикетки внутри светлого поля символа"}$txt$::jsonb, $txt$Самая частая причина непрочтения кода на складе. Снять весь символ с запасом поля не менее ширины двух символов.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.itf14.quiet.zone.and.hri.gap$txt$, $txt$codes.itf14.quiet_zone_width$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_itf14$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$quiet_zone_itf14$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"quiet_zone_itf14","unit":"X","min_mm":null,"min_x_multiple":10,"min_area_fraction":null,"surface":"case_side_panel","reference_scale":"X-dimension оценивается по ширине узкого штриха в пикселях; результат достоверен только при фронтальном ракурсе и разрешении не ниже ~4 px на узкий штрих"}$txt$::jsonb, $txt$Измерять в единицах X, а не в миллиметрах — тогда абсолютный масштаб кадра не нужен.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.itf14.dimensions.and.magnification$txt$, null, $txt$gs1$txt$, $txt$Габариты ITF-14: X-dimension 0,495–1,016 мм, минимальная высота штрихов 31,75 мм; номинальный символ при X = 1,016 мм, соотношении 2,5:1 и quiet zone 10,16 мм имеет полную ширину 142,75 мм$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$габариты в миллиметрах требуют эталона масштаба; без него определимы только пропорции символа$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 5.12.3.2 (symbol specification table 2) и § 5.3.2.2","quote_ru":"SST 2: ITF-14 — X min 0.495 mm, target 0.495 mm, max 1.016 mm; минимальная высота 31.75 mm; Quiet Zone 10X/10X; минимальный класс качества 1.5/10/660. § 5.3.2.2: «for an ITF-14 symbol that has seven character pairs, a target wide-to-narrow ratio of 2.5:1, a target X width of 1.016 millimetres … the total symbol width is 142.75 millimetres»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.itf14.dimensions.and.magnification$txt$, $txt$codes.itf14.symbol_height$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_itf14$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$itf14_bar_height$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"itf14_bar_height","min_mm":31.75,"min_area_fraction":null,"surface":"case_side_panel","reference_scale":"линейка или объект известного размера в кадре; либо паспортные габариты короба"}$txt$::jsonb, $txt$Без масштаба — статус «не проверено». Обрезанная по высоте (усечённая) ITF-14 — распространённое нарушение при печати на узкой этикетке.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.placement.case$txt$, null, $txt$gs1$txt$, $txt$Размещение штрихкода на коробе: низ символа — целевые 32 мм от естественного основания, символ вместе с quiet zone — не ближе 19 мм от любого вертикального ребра, ориентация «picket fence» (штрихи перпендикулярны основанию)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ориентация штрихов и грубая близость к ребру видны на фото; точные 32/19 мм требуют масштаба$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 6.7.1 «General rule», § 6.7.1.2 «Symbol placement on cartons and outer cases»","quote_ru":"«the target placement for the bottom of the barcode is 32 millimetres (1.25 inches) from the natural base of the item. The symbol, including its Quiet Zones, SHOULD be at least 19 millimetres (0.75 inch) from any vertical edge». «The barcodes … SHALL be upright (i.e. in picket fence orientation) and placed on the sides of the unit»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
