insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.logistic.sscc.gs1128.mandatory$txt$, null, $txt$gs1$txt$, $txt$Логистическая единица (паллета) идентифицируется SSCC — AI (00); обязательный носитель для индивидуальной логистической единицы — символика GS1-128$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$наличие GS1-128 и AI (00) в декодированной строке проверяется однозначно$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 2.2.1 «Individual logistic units» — Data carrier specification","quote_ru":"«The mandatory data carrier used to represent individual logistic units is the GS1-128 barcode symbology». «The SSCC element string AI (00) is used for the identification of logistic units»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
