insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.sscc.18.digits.structure$txt$, null, $txt$gs1$txt$, $txt$SSCC — ровно 18 цифр: расширяющая цифра + GS1 Company Prefix + серийный номер + контрольная цифра; номер не переиспользуется как минимум год$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$длина 18 цифр и контрольная цифра проверяются арифметически; уникальность и годичный запрет переиспользования по фото не проверяются вообще$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 3.2 (AI 00 = N2+N18), § 4.4.1.1 «General rule»","quote_ru":"«An individual Serial Shipping Container Code (SSCC) is a unique number, which remains the same for the life of the logistic unit to which it is assigned … an individual SSCC number must not be reallocated within one year of the shipment date». Структура из 4 компонентов подтверждена GS1AU_SSCC."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
