insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.sscc.18.digits.structure$txt$, $txt$codes.sscc.prefix_matches_company$txt$, 2, $txt$text_semantic$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_sscc$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Совпадает ли GS1 Company Prefix внутри SSCC с префиксом внутри GTIN того же производителя на упаковке?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["GS1 Company Prefix"],"expected_value":"sscc_prefix == gtin_prefix"}$txt$::jsonb, $txt$Не жёсткое правило (паллету может строить логистический оператор со своим префиксом), поэтому severity — minor; расхождение служит сигналом, а не приговором.$txt$, null)
