insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.logistic.label.placement.on.pallet$txt$, null, $txt$gs1$txt$, $txt$Логистическая этикетка на паллете: все штрихкоды — в зоне 400–800 мм от основания паллеты и не ближе 50 мм от любого вертикального ребра; GS1-128 со SSCC — в нижней части этикетки; рекомендуются две одинаковые этикетки на смежных сторонах$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$положение SSCC в нижней части этикетки и наличие второй этикетки видны на фото; высота 400–800 мм требует масштаба, который на паллете как раз получить реально (стандартная высота поддона 144–150 мм)$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 6.7.1.1 «Symbol placement on pallets», § 6.6.4.1.1, § 6.7.2","quote_ru":"«all GS1 barcodes SHALL be positioned in a space between 400 millimetres (16 inches) and 800 millimetres (32 inches) from the base of the pallet … The symbol(s) including Quiet Zones, SHALL be at least 50 millimetres (2.0 inches) from any vertical edge». «the GS1-128 barcode encoding the SSCC SHALL be placed in the lowest portion of the label»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.logistic.label.placement.on.pallet$txt$, $txt$codes.label.sscc_at_bottom$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_sscc$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$gs1_128_sscc$txt$, null, $txt$position$txt$, $txt${"target":"gs1_128_sscc","surface":"logistic_label","expected_position":"lowest_block_of_label","reference_scale":"не требуется — проверяется взаимное расположение блоков внутри этикетки"}$txt$::jsonb, $txt$Снять этикетку целиком, все три блока (поставщик / данные / штрихкоды).$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
