  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.logistic.label.placement.on.pallet$txt$, $txt$codes.label.two_adjacent_sides$txt$, 2, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_gs1_128$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$logistic_label$txt$, null, null, $txt${"min_count":2}$txt$::jsonb, $txt$Рекомендация, а не требование: две одинаковые этикетки на смежных сторонах. Проверяется только если сняты две смежные грани.$txt$, null)
