insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.logistic.label.dimensions$txt$, null, $txt$gs1$txt$, $txt$Типовые размеры логистической этикетки GS1: A6 (105×148 мм) или 4×6 дюймов — когда кодируется только SSCC; A5 (148×210 мм) или 6×8 дюймов — при большем объёме данных$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$размер этикетки в миллиметрах без эталона масштаба в кадре не определяется, а сам формат нормой не предписан$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 6.6.4.5 «Label dimensions»","quote_ru":"«The physical dimensions of the label are determined by the labeller … A6 (105 mm x 148 mm), which is particularly suitable when only the SSCC … is encoded … -or- A5 (148 mm x 210 mm)»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.ai.mandatory.associations$txt$, null, $txt$gs1$txt$, $txt$Обязательные связки идентификаторов применения: (10) партия и даты (11)/(13)/(15)/(16)/(17) обязаны сопровождаться (01) либо (02) либо (8006)/(8026); (02) обязан сопровождаться (00) И (37)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО при ревизии 2026-08-02 (было checkable). Проверка структурная и измерений не требует, НО § 4.14.2 прямо оговаривает: «This does not necessarily mean that the element strings need to appear in the same data carrier» — связанный элемент может находиться в другом символе на другой грани той же физической единицы. Поэтому вывод «обязательная связка нарушена» правомерен только при полном покры$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 4.14.2 «Mandatory association of element strings», Figure 4.14.2-1","quote_ru":"«02 GTIN of contained trade items → 00 AND 37: The GTIN of contained trade items SHALL occur in combination with an SSCC and the count of the trade items». «10 Batch/lot number → 01 XOR 02 XOR 8006 XOR 8026». «11, 13, 15, 16, 17 … → 01 XOR 02 XOR 8006 XOR 8026»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.ai.mandatory.associations$txt$, $txt$codes.ai.batch_has_gtin$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$dates_batch$txt$, $txt$batch_number$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Если в кодах на упаковке присутствует AI (10) (партия), присутствует ли на той же физической единице AI (01) или (02) (или ITIP 8006/8026)?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["(10)","(01)","(02)","(8006)","(8026)"],"expected_value":"has_10 -> has_01_or_02_or_8006_or_8026"}$txt$::jsonb, $txt$Учитывать ВСЕ коды на единице: GTIN может быть в EAN-13/ITF-14 (там AI (01) подразумевается), а партия — в отдельном GS1-128.$txt$, null)
