insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.ai.date.format.yymmdd$txt$, null, $txt$gs1$txt$, $txt$Даты в AI (11) и (17) — ровно 6 цифр в формате ГГММДД; день «00» означает последний день указанного месяца$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$формат и диапазоны полей проверяются арифметически по декодированной строке$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 3.4.2 (AI 11), § 3.4.7 (AI 17); формат N2+N6 по § 3.2","quote_ru":"«Year: the tens and units of the year (e.g., 2003 = 03), which is mandatory. Month: the number of the month … Day: … if it is not necessary to specify the day, the field must be filled with two zeroes». «the resultant data string SHALL be interpreted as the last day of the noted month including any adjustment for leap years»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
