insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.ai.date.format.yymmdd$txt$, $txt$codes.ai.date_6_digits$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$dates_batch$txt$, $txt$other:ai_17_11_6_01_12_00_31$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Содержит ли поле AI (17)/(11) ровно 6 цифр с корректным месяцем (01–12) и днём (00–31)?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["YYMMDD","^[0-9]{6}$"],"expected_value":"valid_yymmdd"}$txt$::jsonb, $txt$Проверяет и логику високосного года при дне «00».$txt$, null)
