insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.ai.no.global.mandate.for.food$txt$, null, $txt$gs1$txt$, $txt$GS1 General Specifications НЕ делает AI (10) партию и AI (17) срок годности обязательными сами по себе для пищевой продукции — обязательность возникает из отраслевых и национальных норм$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$это утверждение об области действия нормы, а не о свойстве упаковки — проверить по фото нечего$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$04$txt$, $txt$24$txt$]::text[], $txt${"act_id":"GS1GS","clause":"§ 4.14.2 (устанавливает только связки, а не обязательность самих AI); § 2.2.1 «Attributes — Required: Not applicable»","quote_ru":"В § 2.2.1 для логистической единицы: «Attributes / Required: Not applicable»; обязательным атрибутом является только SSCC. Правила § 4.14.2 срабатывают лишь тогда, когда AI (10)/(17) уже нанесены. Отдельная обязанность указывать партию/даты на транспортной упаковке пищевой продукции устанавливается ТР ТС 022/2011 (ст. 4) и национальными актами — НЕ проверено в этом исследовании (docs.cntd.ru был н"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.hri.required.and.format$txt$, null, $txt$gs1$txt$, $txt$Человекочитаемая подпись (HRI) обязательна: размещается под кодом (либо рядом с сохранением quiet zone), AI указываются в круглых скобках, шрифт разборчивый (например OCR-B), GTIN показывается всегда; на логистических этикетках высота символов HRI — не менее 3 мм$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$наличие HRI, круглые скобки у AI и совпадение с декодированным значением проверяются по фото; высота 3 мм — только при известном масштабе$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 4.15 «Human readable interpretation (HRI) rules», правила 1, 3, 4, 5, 8, 9; § 6.6.4.1.2","quote_ru":"«Rule 3. Parentheses SHALL surround AIs in HRI but are not encoded in the GS1 AIDC data carrier». «Rule 4. A clearly legible font SHALL be used (e.g., OCR-B as defined in ISO 1073-2)». «Rule 5. On GS1 Logistic Labels HRI characters SHALL be no less than 3 mm (0.1181 inch) high». «Rule 8. HRI SHALL appear except in rare circumstances … where there are extreme space constraints»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
