insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.hri.required.and.format$txt$, $txt$codes.hri.height$txt$, 2, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_sscc$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$hri_text$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"hri_text","min_mm":3,"min_area_fraction":null,"surface":"logistic_label","reference_scale":"габарит самой этикетки (A6 105×148 мм / A5 148×210 мм) как эталон, либо линейка в кадре"}$txt$::jsonb, $txt$Только для логистических этикеток. Без надёжного масштаба — статус «не проверено».$txt$, null)
