insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.consumer.magnification.80.200$txt$, null, $txt$gs1$txt$, $txt$Диапазон размеров EAN-13/EAN-8 для розничного POS: magnification 80–200%, то есть X-dimension от 0,264 мм до 0,660 мм (номинал 0,330 мм при 100%); при 80% EAN-13 имеет габарит 29,83 × 18,28 мм, при 200% — 74,58 × 45,70 мм$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$абсолютный размер в миллиметрах требует эталона масштаба; без него достоверно определяется только грубое «код явно уменьшен ниже нормы»$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 5.2.6.7 «Dimensions of modules and symbols at different levels of magnification»; § 5.12.3.1 (symbol specification table 1)","quote_ru":"SST 1: EAN-13 — X-dimension min 0.264 mm (0.0104\"), target 0.330 mm, max 0.660 mm; минимальная высота 18.28 / 22.85 / 45.70 mm. § 5.2.6.7: magnification 0.80 → модуль 0,264 мм, EAN-13 29,83 × 18,28 мм; таблица доходит до 2.00. «an X-dimension of 0.264 millimetre (magnification of 80%) is attainable and is the minimum allowable size»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.consumer.magnification.80.200$txt$, $txt$codes.ean.size_within_range$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_ean13$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$ean13_symbol_width$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"ean13_symbol_width","min_mm":29.83,"max_mm":74.58,"min_area_fraction":null,"surface":"consumer_panel","reference_scale":"линейка/монета известного размера в кадре либо паспортные габариты упаковки; ракурс — строго фронтальный, иначе перспектива даёт систематическую ошибку"}$txt$::jsonb, $txt$Без эталона масштаба выдавать «не проверено». Косвенный признак недопустимого уменьшения — визуально слипшиеся штрихи.$txt$, null)
