insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.consumer.magnification.80.200$txt$, $txt$codes.ean.not_truncated$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_ean13$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$ean13_symbol$txt$, null, $txt$position$txt$, $txt${"target":"ean13_symbol","surface":"consumer_panel","expected_aspect_ratio":"width/height ≈ 37.29/22.85 ≈ 1.63 для полноразмерного EAN-13","reference_scale":"не требуется — проверяется соотношение сторон самого символа"}$txt$::jsonb, $txt$Усечённый по высоте (truncated) EAN-13 допускается только при полной невозможности напечатать полноразмерный и теряет всенаправленное сканирование.$txt$, null)
