insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.consumer.quiet.zone$txt$, null, $txt$gs1$txt$, $txt$Светлые поля EAN-13 на POS: слева не менее 11X, справа не менее 7X (EAN-8 — 7X/7X, UPC-A — 9X/9X); поля обязательны и должны быть свободны от печати$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО при ревизии 2026-08-02 (было checkable) ради согласованности с codes.itf14.quiet_zone_and_hri_gap, где ровно такое же измерение (10X) честно помечено partial. «Загрязнение» поля посторонней печатью видно напрямую и проверяется надёжно, а численное 11X/7X — это измерение по изображению, достоверное лишь при фронтальном ракурсе и разрешении ≥3–4 px на модуль; при косом ракурсе перспектива д$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 5.12.3.1 (symbol specification table 1), колонки Quiet Zone Left/Right","quote_ru":"SST 1: EAN-13 — Quiet Zone Left 11X, Right 7X; EAN-8 — 7X / 7X; UPC-A — 9X / 9X; UPC-E — 9X / 7X; минимальный класс качества 1.5/06/660"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.consumer.quiet.zone$txt$, $txt$codes.ean.quiet_zone_clean$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_ean13$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Заходит ли в светлое поле слева/справа от EAN-13 посторонний элемент — текст, рамка, цветная плашка, шов, край этикетки, сгиб?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"любой печатный или конструктивный элемент (рамка, линия реза, шов пакета, отверстие еврослота, сгиб) внутри светлого поля символа"}$txt$::jsonb, $txt$Снять символ с полем не менее ширины самого символа с каждой стороны. Отдельно проверять коды на сгибе и на «шве» гибкой упаковки.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.consumer.quiet.zone$txt$, $txt$codes.ean.quiet_zone_width_x$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_ean13$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$quiet_zone_ean13$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"quiet_zone_ean13","unit":"X","min_mm":null,"min_x_multiple_left":11,"min_x_multiple_right":7,"min_area_fraction":null,"surface":"consumer_panel","reference_scale":"X-dimension берётся из самого символа (ширина узкого модуля в пикселях) — внешний эталон не нужен; требуется фронтальный ракурс и ≥3–4 px на модуль"}$txt$::jsonb, $txt$Метки-«усы» (guard bars) и символ «>» на макете помогают увидеть границу поля справа.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.consumer.ean8.size.constraints$txt$, null, $txt$gs1$txt$, $txt$EAN-8 (GTIN-8) разрешён только при жёстких ограничениях по площади: общая печатная площадь упаковки < 80 см², либо площадь наибольшей этикетки < 40 см², либо цилиндр диаметром < 30 мм$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$факт использования EAN-8 определяется по фото однозначно, но площадь упаковки в см² без масштаба и без всех граней не измеряется$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 4.3.7 «GTIN-8 guidelines and packaging size constraints»","quote_ru":"«The use of a GTIN-8 is authorised when: The total printable area of the product packaging is less than 80 cm², or the area of the largest label for the item is less than 40 cm², or the product is cylindrical with a diameter less than 30 mm»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.consumer.ean8.size.constraints$txt$, $txt$codes.ean8.detected$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$barcode$txt$, null, null, $txt${"min_count":1,"symbology":"EAN-8"}$txt$::jsonb, $txt$Само по себе не нарушение — это триггер для последующей проверки габаритов.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.consumer.ean8.size.constraints$txt$, $txt$codes.ean8.area_justified$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$gtin_consistency$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$package_printable_area$txt$, null, $txt$area_fraction$txt$, $txt${"target":"package_printable_area","max_cm2":80,"min_area_fraction":null,"surface":"all_panels","reference_scale":"нужны габариты упаковки из карточки товара либо эталон в кадре и снимки всех граней; по одному кадру достоверно НЕ определяется"}$txt$::jsonb, $txt$На практике честнее возвращать «не проверено» и передавать проверку на габаритные данные из мастер-данных.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.gtin.single.value.per.entity$txt$, null, $txt$gs1$txt$, $txt$Все вхождения GTIN на одной физической единице обязаны иметь одно и то же значение; размещать на ней GTIN других уровней упаковки запрещено$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО при ревизии 2026-08-02 (было checkable). Если в кадре видно два и более кода, их GTIN сравниваются напрямую — этот положительный сценарий действительно проверяем. Но обе проверки внутри сформулированы как absence, а отсутствие второго, конфликтующего GTIN по ограниченному набору ракурсов доказать нельзя: старый код может быть на непроснятой грани, под стикером или под плёнкой. Отрицательн$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 4.14.1 «Invalid pairs of element strings», строка 01/01","quote_ru":"«All occurrences of GTIN SHALL have one value. It is for example not allowed to include GTINs of other packaging levels»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.gtin.single.value.per.entity$txt$, $txt$codes.gtin.no_conflicting_second_code$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Есть ли на одной и той же физической единице второй штрихкод с ОТЛИЧАЮЩИМСЯ значением GTIN (например, старый код не заклеен, или на коробе виден GTIN потребительской единицы)?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"два линейных кода на одной грани с разными декодированными GTIN; просвечивающий или частично заклеенный старый штрихкод"}$txt$::jsonb, $txt$Снимать все грани. Особый случай — стикер поверх старого кода: если старый читается по краю, это нарушение.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.gtin.single.value.per.entity$txt$, $txt$codes.gtin.aggregation_lower_level_obscured$txt$, 1, $txt$absence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_sscc$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Читаются ли на собранной паллете штрихкоды вложенных (нижних) логистических единиц одновременно с этикеткой самой паллеты?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"видимые и сканируемые SSCC-этикетки коробов на боку собранной паллеты рядом с паллетной этикеткой"}$txt$::jsonb, $txt$По § 4.4.2: «Only the barcode of the higher logistic unit SHOULD be readable» — это SHOULD, поэтому severity minor.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.datamatrix.gs1.format$txt$, null, $txt$gs1$txt$, $txt$GS1 DataMatrix — это DataMatrix ECC 200 с символом FNC1 в первой позиции и данными в формате AI; светлое поле — 1X по всем четырём сторонам; X-dimension зависит от среды сканирования: 0,743–1,50 мм для логистических единиц (SST 5) и 0,375–0,990 мм для потребительских товаров, сканируемых на рознично$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$наличие 2D-кода и его тип определяются по фото; корректность FNC1/структуры AI — только после успешного декодирования; размеры модуля — только при масштабе$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 5.12.3.5 (symbol specification table 5, стр. 365) — логистические единицы; § 5.12.3.1 (symbol specification table 1, стр. 356) — розничный POS; § 5.12.5.1.2 (примечание о quiet zone, стр. 384); § 5.6.3 «GS1 DataMatrix symbology»","quote_ru":"SST 5 (логистические единицы): GS1 DataMatrix (ECC 200) — X min 0.743 mm, target 0.743 mm, max 1.50 mm, Quiet Zone «1X on all four sides», минимальный класс 1.5/20/660. SST 1 (розничный POS): GS1 DataMatrix — X min 0.375 mm, target 0.625 mm, max 0.990 mm, Quiet Zone 1X, минимальный класс 1.5/08/660 — ДОБАВЛЕНО при ревизии 2026-08-02, потому что requirement имеет packaging_level «both», а раньше пр"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.datamatrix.gs1.format$txt$, $txt$codes.dm.present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$datamatrix$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$datamatrix$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$DataMatrix отличается от QR отсутствием трёх квадратов-искателей: у него сплошной L-образный контур и «пунктирные» две стороны.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.datamatrix.gs1.format$txt$, $txt$codes.dm.gs1_ai_structure$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$datamatrix$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Начинается ли декодированное содержимое DataMatrix с идентификатора применения (первый символ FNC1, затем AI, например «01»), а не с произвольного текста/URL?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["FNC1","]d2","(01)","GS1 DataMatrix"],"expected_value":"starts_with_ai"}$txt$::jsonb, $txt$Признак GS1 DataMatrix в потоке декодера — идентификатор символики ]d2. Обычный DataMatrix с произвольным текстом GS1-кодом не является.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.datamatrix.gs1.format$txt$, $txt$codes.dm.quiet_zone_clean$txt$, 2, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_quiet_zone$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Заходит ли в светлое поле DataMatrix (1X со всех сторон) посторонняя печать, рамка или край этикетки?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"рамка вокруг кода, текст вплотную к L-контуру, край наклейки, обрезающий модульную сетку"}$txt$::jsonb, $txt$1X — очень маленькое поле, поэтому визуально его нарушают редко; чаще проблема — блик и низкий контраст на металлизированной плёнке.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.uz.marking.code.structure$txt$, null, $txt$gs1$txt$, $txt$Код маркировки «Asl Belgisi» (РУз): 4 группы данных — код идентификации (GTIN 14 цифр после AI (01) + серийный номер) и код проверки (криптоподпись); наносится в виде GS1 DataMatrix$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$по фото проверяется наличие DataMatrix и, после декодирования, структура (01)+14 цифр и наличие (21); подлинность криптоподписи и статус кода «в обороте» по изображению не проверяются В ПРИНЦИПЕ — нужен онлайн-запрос в ГИС «Asl Belgisi». При ревизии 2026-08-02 из checks[] УДАЛЕНА проверка codes.uz.crypto_tail_authenticity: она была объявлена kind=text_semantic с severity=critical, хотя её собствен$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"ASLBELGISI","clause":"не установлен точно — нормативный акт, задающий общую структуру кода маркировки в РУз, в этом исследовании НЕ найден","quote_ru":"Пересказ (НЕ цитата): код маркировки содержит 4 группы данных — первая и вторая образуют код идентификации, третья и четвёртая — код проверки; первая группа — 14 цифр GTIN, размещаемых после идентификатора (01); далее серийный номер, обеспечивающий уникальность DataMatrix, и код проверки («криптохвост»), формируемый оператором системы. ИСПРАВЛЕНО при ревизии 2026-08-02: ранее здесь стояла ссылка н"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.uz.marking.code.structure$txt$, $txt$codes.uz.dm_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$codes$txt$, $txt$datamatrix$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$datamatrix$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Для товарных групп, подлежащих обязательной цифровой маркировке. Снять панель с кодом крупно, без бликов, под углом к источнику света.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.uz.marking.code.structure$txt$, $txt$codes.uz.dm_has_gtin_and_serial$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$codes$txt$, $txt$gtin_consistency$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Содержит ли декодированный код маркировки AI (01) с 14 цифрами GTIN и AI (21) с серийным номером?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["01","21","GTIN 14","серийный номер"],"expected_value":"has_01_14digits AND has_21"}$txt$::jsonb, $txt$GTIN в коде маркировки — 14 цифр (GTIN-13 дополняется ведущим нулём). Контрольная цифра проверяется тем же mod-10.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.uz.marking.code.structure$txt$, $txt$codes.uz.gtin_matches_ean13$txt$, 2, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_ean13$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Совпадает ли GTIN внутри кода маркировки с GTIN из EAN-13 на той же упаковке (с точностью до ведущего нуля)?$txt$, null, $txt${"expect":"specific_value","unit":null,"pattern_hints":["GTIN-14","GTIN-13","leading zero"],"expected_value":"dm_gtin[1:] == ean13"}$txt$::jsonb, $txt$Кросс-проверка «код маркировки против EAN-13»: расхождение — сигнал, что код маркировки заказан на другой товар. Нужен кадр, где видны ОБА кода; при отсутствии такого кадра — «не проверено». Severity понижена с critical до major при ревизии 2026-08-02: у GTIN в коде маркировки и в EAN-13 бывают легитимные расхождения (например, разные GTIN у мультипака и его вложений в одном кадре), поэтому это сигнал, а не приговор.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.print.quality.iso15416.grade$txt$, null, $txt$gs1$txt$, $txt$Класс качества печати штрихкода по ISO/IEC 15416 (линейные) и ISO/IEC 15415 (2D) — например минимум 1.5/06/660 для розничного EAN-13 и 1.5/10/660 для ITF-14/GS1-128$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$класс по ISO/IEC 15416 строится из Scan Reflectance Profile, измеренного верификатором по ISO/IEC 15426 при нормированной апертуре, заданной длине волны (660 нм) и заданной геометрии освещения (45°/30°) — обычная фотокамера не даёт ни калиброванной отражательной способности, ни этих условий$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 5.12.3.1/§ 5.12.3.2/§ 5.12.3.5 (колонка Minimum quality specification), § 5.12.5 «Quality assessment» и § 5.12.5.1 «Verification» (заголовок уточнён при ревизии 2026-08-02: раздела с названием «Symbol verification» в релизе 21.0.1 нет)","quote_ru":"«2.8/05/660 would indicate that the average of the grades of the Scan Reflectance Profiles … was 2.8 when these were obtained with the use of a 0.125 millimetre aperture (ref. no. 05) and a 660 nanometre light source, incident at 45 degrees». «The ISO/IEC verifier reports its assessment … as one of a range of four passing grades (from 4 to 1 …) or one failing grade (0)»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.scannability.proxy.signals$txt$, null, $txt$gs1$txt$, $txt$Косвенные (НЕ нормативные) признаки проблем со считыванием, которые всё же видны на фото: код не декодируется, залит бликом, напечатан низкоконтрастной парой цветов, деформирован на сгибе, частично перекрыт$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$непрочтение кода на фото — сильный сигнал, но не доказательство несоответствия: причиной может быть сама съёмка, а не печать$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1GS","clause":"§ 5.12.5.2 «Measurement methodology» (стр. 384; символ верифицируется в финальной конфигурации, включая ламинат и материал упаковки) — используется как обоснование, а не как норма класса. deontic исправлен с obligation на permission при ревизии 2026-08-02: это набор эвристик самой системы, а не требование какого-либо акта","quote_ru":"«The symbol must be verified in its final configuration wherever possible (e.g., including over-laminate, package material, contents)». Отсюда: дефекты, вносимые упаковкой (блик ламината, сгиб, шов), — легитимный объект контроля, но их оценка по фото НЕ равна классу ISO/IEC 15416."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.scannability.proxy.signals$txt$, $txt$codes.scan.decodes_at_all$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$decodable_barcode$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Если код не декодировался — сначала ПЕРЕСНЯТЬ (фронтально, без вспышки в лоб, с боковым светом), и только при повторной неудаче поднимать флаг. Иначе система будет генерировать ложные тревоги на плохих фото.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.scannability.proxy.signals$txt$, $txt$codes.scan.not_obstructed$txt$, 1, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_hri$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Перекрыт ли код посторонним элементом — ценником, акцизной/учётной маркой, стикером, скотчем, сгибом или заломом упаковки?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"ценник, стикер, лента, марка или залом, накрывающие штрихи, светлое поле или HRI"}$txt$::jsonb, $txt$Частый кейс в рознице: ценник наклеен поверх EAN-13.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.scannability.proxy.signals$txt$, $txt$codes.scan.contrast_pair$txt$, 2, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$barcode$txt$, null, $txt$contrast_ratio$txt$, $txt${"target":"barcode","min_contrast_note":"нормативного порога по фото не существует; здесь ловятся только заведомо недопустимые сочетания — красные/оранжевые/жёлтые штрихи, светлые штрихи на тёмном фоне, металлизированный фон без белой подложки","surface":"any","reference_scale":"не требуется; результат носит характер сигнала, а не измерения ISO"}$txt$::jsonb, $txt$Красные штрихи «невидимы» для сканера с источником 660 нм. Инверсия (светлые штрихи на тёмном фоне) для EAN/UPC недопустима.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.uz.barcoding.legal.status$txt$, null, $txt$gs1$txt$, $txt$В Республике Узбекистан штриховое кодирование введено ПКМ №438 от 21.09.1999; по тексту постановления нанесение штрихкода осуществляется добровольно, а для получения кода организации и товара субъект проходит регистрацию в Ассоциации «GS1 Uzbekistan» (формулировки «единственный уполномоченный постав$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$это правовой статус требования, а не свойство упаковки; принадлежность GTIN конкретному предприятию проверяется по реестру GS1, а не по изображению$txt$, array[$txt$UZ$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"LEXUZ438","clause":"не установлен точно — Положение к ПКМ №438 от 21.09.1999, номера пунктов не сверены (п. 2 изменён ПКМ №371 от 01.07.2024)","quote_ru":"Пересказ: постановление рекомендует маркировать экспортируемую продукцию и новые товары штрихкодом; «Маркировка продукции (товара) штриховыми кодами GS1 осуществляется добровольно»; субъекты проходят регистрацию в Ассоциации «GS1 Uzbekistan» для получения кода организации и товара, незарегистрированные наносить маркировку не вправе; «Субъекты предпринимательской деятельности несут ответственность "}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$gs1.codes.pos.2d.dual.marking.transition$txt$, null, $txt$gs1$txt$, $txt$Переходный период GS1 Sunrise 2027: наличие на потребительской упаковке 2D-кода (GS1 DataMatrix / QR с GS1 Digital Link) РЯДОМ с EAN-13 не является ошибкой; 2D-код при этом должен соблюдать X-dimension, quiet zone и класс качества по POS-таблицам GS1$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$наличие двух символов на упаковке и их взаимное расположение видны на фото; это правило нужно системе, чтобы не помечать 2D-код как «лишний»$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GS1_SUNRISE","clause":"инициатива GS1 Sunrise 2027 (не НПА); соответствующие требования к 2D — GS1GS § 5.12.3.1 и § 4.16 (управление несколькими символами)","quote_ru":"Пересказ: 2027 г. — заявленная GS1 веха перехода розничных POS на приём 2D-кодов наряду с EAN/UPC; в переходный период применяется двойная маркировка EAN/UPC + 2D. СКОРРЕКТИРОВАНО при ревизии 2026-08-02: страница gs1us.org прямо оговаривает «Sunrise 2027 is a milestone in the transition to 2D barcodes, it is not necessary to implement all the capabilities of 2D by that date», поэтому прежняя форму"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.pos.2d.dual.marking.transition$txt$, $txt$codes.pos.second_symbol_allowed$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$codes$txt$, $txt$datamatrix$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$datamatrix$txt$, null, null, $txt${"min_count":0}$txt$::jsonb, $txt$Информационная проверка: фиксировать факт двойной маркировки, НЕ выдавать нарушение.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$gs1.codes.pos.2d.dual.marking.transition$txt$, $txt$codes.pos.symbols_do_not_overlap$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_quiet_zone$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$all_barcodes$txt$, null, $txt$position$txt$, $txt${"target":"all_barcodes","surface":"consumer_panel","expected_position":"светлые поля соседних символов не пересекаются","reference_scale":"не требуется — проверяется взаимное расположение символов в кадре"}$txt$::jsonb, $txt$По § 6.7.3: дополнительный символ размещается так, чтобы не перекрывать основной, светлые поля сохраняются для обоих.$txt$, null)
