insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.eac.presence$txt$, null, $txt$horizontal$txt$, $txt$Единый знак обращения EAC наносится на каждую единицу продукции, упаковку ИЛИ сопроводительную документацию$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$норма допускает нанесение EAC только в сопроводительной документации, поэтому отсутствие знака на фото упаковки само по себе не доказывает нарушение$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"KTS711","clause":"Положение, п. 5.1","quote_ru":"Единый знак обращения наносится на каждую единицу продукции, упаковку или сопроводительную документацию."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.marks.eac.presence$txt$, $txt$eac.present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$eac_mark$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$eac_mark$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снять все панели упаковки, включая дно и торцы. Знак EAC часто соседствует с составом/штрихкодом мелким кеглем. Если на упаковке знака нет — это ещё не нарушение, нужен запрос сопроводительной документации$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.eac.base.size.min.5mm$txt$, null, $txt$horizontal$txt$, $txt$Базовый размер знака EAC — не менее 5 мм$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$измерение в миллиметрах невозможно без калибровки масштаба по опорному объекту известного размера в том же фокальном плане$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"KTS711","clause":"Положение, п. 3.3","quote_ru":"Размеры единого знака обращения определяет изготовитель (поставщик), получивший право на его применение. Базовый размер должен быть не менее 5 мм."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.marks.eac.base.size.min.5mm$txt$, $txt$eac.min_size_mm$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$eac_mark$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$eac_mark$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"eac_mark","min_mm":5,"measured_dimension":"сторона описанного квадрата (высота = ширина); термин «базовый размер» в Положении не расшифрован — трактуем как высоту знака, что является наиболее консервативным прочтением","surface":"any","reference_scale":"обязательна калибровка: px/mm вычисляется по опорному объекту в кадре, см. требование scale.calibration_method. Без опорного объекта проверка возвращает 'нет масштаба', а не 'нарушение'","tolerance_mm":0.5}$txt$::jsonb, $txt$Переснять знак EAC вместе с опорным объектом в одной плоскости: банковская карта (85,60 x 53,98 мм) рядом с упаковкой, кадр перпендикулярно поверхности, без наклона$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.eac.square.proportions$txt$, null, $txt$horizontal$txt$, $txt$Знак EAC — три стилизованные буквы E, A, C с прямыми углами, одинаковой высоты и ширины, точные пропорции квадрата$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$соотношение сторон знака измеримо по пикселям без абсолютного масштаба, но соответствие начертания эталонной сетке 9x9 требует макро-кадра: при базовом размере 5 мм на обзорном кадре пачки знак занимает десятки пикселей, где прямые углы и толщины штрихов неразличимы. Кроме того, любой наклон камеры превращает квадрат в трапецию, поэтому на обычном фото проверяются лишь присутствие знака и грубая п$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"KTS711","clause":"Положение, п. 3.1-3.2 (изображение на масштабной сетке — рис. 3 и рис. 4)","quote_ru":"Изображение единого знака обращения продукции ЕАС представляет собой сочетание трех стилизованных букв «Е», «А» и «С», графически исполненных с применением прямых углов, имеет одинаковую высоту и ширину, составляет точные пропорции квадрата на светлом или на контрастном фоне."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.marks.eac.square.proportions$txt$, $txt$eac.glyph_correct$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$eac_mark$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$eac_mark$txt$, null, null, $txt${"min_count":1,"glyph_spec":"три стилизованные буквы E, A, C, построенные только прямыми углами; эталон — масштабная сетка 9x9 клеток из рис. 3 и 4 Положения"}$txt$::jsonb, $txt$Приблизить кадр к знаку; отличать настоящий EAC от похожих знаков ЕАС/EAC с округлыми элементами или иными пропорциями$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.marks.eac.square.proportions$txt$, $txt$eac.square_ratio$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$eac_mark$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$eac_mark$txt$, null, $txt$position$txt$, $txt${"target":"eac_mark","aspect_ratio_expected":1,"aspect_tolerance":0.08,"note":"проверяется отношение ширины к высоте описанного прямоугольника; абсолютный размер здесь не нужен, поэтому мера НЕ min_size_mm — миллиметровый порог тут отсутствует","min_resolution_px":60,"reference_scale":"не требуется (безразмерная проверка), но требуется фронтальный ракурс — перспективное искажение даёт ложные срабатывания; при высоте знака менее ~60 px вердикт не выносить"}$txt$::jsonb, $txt$Снять знак строго перпендикулярно поверхности; на скошенном кадре квадрат превращается в трапецию$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.eac.monochrome.contrast$txt$, null, $txt$horizontal$txt$, $txt$Изображение EAC должно быть одноцветным и контрастировать с цветом поверхности нанесения$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$числового порога контраста норма не задаёт, а цветопередача фото зависит от освещения и баланса белого; тиснение/лак без красителя фотографически почти не читаются$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"KTS711","clause":"Положение, п. 5.2 (в связке с п. 3.3 — четкость элементов и их различимость невооруженным глазом на общем цветном фоне объекта)","quote_ru":"Изображение единого знака обращения продукции на рынке Сторон должно быть одноцветным и контрастировать с цветом поверхности, на которую оно нанесено."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.marks.eac.monochrome.contrast$txt$, $txt$eac.monochrome$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$eac_mark$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$eac_mark$txt$, null, $txt$contrast_ratio$txt$, $txt${"target":"eac_mark","min_contrast_ratio":null,"norm_has_no_numeric_threshold":true,"suggested_operational_threshold":3,"single_colour_required":true,"surface":"any","reference_scale":"не требуется; нужен кадр без бликов и пересвета, желательно с диффузным освещением"}$txt$::jsonb, $txt$Переснять без вспышки в лоб и без бликов. Если знак выполнен тиснением/лаком — вынести вердикт 'не читается на фото', а не 'нарушение'$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.eac.no.misleading.similar.marks$txt$, null, $txt$horizontal$txt$, $txt$Запрещена маркировка, вводящая в заблуждение относительно знака EAC; прочие знаки не должны ухудшать его видимость и читаемость$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$перекрытие и близость посторонних знаков видны на фото, но «способность ввести в заблуждение» — оценочная категория$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"KTS711RED","clause":"Положение, п. 5.4 (введён Решением Совета ЕЭК от 17.03.2016 № 22)","quote_ru":"Не допускается нанесение маркировки, знаков и надписей, способных ввести в заблуждение относительно единого знака обращения; иные знаки соответствия не должны ухудшать видимость, четкость и читаемость единого знака обращения."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.marks.eac.no.misleading.similar.marks$txt$, $txt$eac.no_lookalike$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$eac_mark$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Есть ли на упаковке знаки, имитирующие EAC (латинское «EAC» иного начертания, знак ЕАС с округлыми элементами, псевдознаки соответствия), или знаки, физически перекрывающие знак EAC?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"квази-знаки, повторяющие композицию трёх букв EAC, но с иными пропорциями/скруглениями; наклейки, штампы или иные знаки, налегающие на поле знака EAC"}$txt$::jsonb, $txt$Снять окрестность знака EAC радиусом не менее двух его высот, чтобы было видно соседние знаки$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.eac.packaging.product.docs.only$txt$, null, $txt$horizontal$txt$, $txt$Для самой упаковки (укупорочных средств) как продукции знак EAC проставляется в сопроводительной документации, а не на изделии$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$норма прямо переносит знак EAC в документы, поэтому фотография упаковки в принципе не может подтвердить или опровергнуть её исполнение$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"TRTS005","clause":"ст. 8 п. 1 (в редакции, введённой в действие с 5 марта 2025 года решением Совета ЕЭК от 06.09.2024 № 61)","quote_ru":"Упаковка (укупорочные средства)... должна иметь маркировку единым знаком обращения продукции на рынке Союза, который проставляется в сопроводительной документации."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.material.code.and.mobius$txt$, null, $txt$horizontal$txt$, $txt$Маркировка упаковки содержит цифровой код и (или) буквенное обозначение материала по Приложению 3 и символ петли Мёбиуса$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$петля Мёбиуса и код материала распознаются на фото только при макро-разрешении (кегль обычно 1,5-3 мм, часто на дне или под клапаном), а по примечанию 4 Приложения 3 символы законно выполняются рельефом, который без бокового света не читается. Главное: по ст. 6 п. 1 идентификационная маркировка допускается «на упаковку и (или) сопроводительную документацию», поэтому её отсутствие в кадре НЕ доказы$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"TRTS005","clause":"ст. 6 п. 2 (ред. с 21.05.2017 по решению Совета ЕЭК от 18.10.2016 № 96); Приложение 3; Приложение 4 рис. 2","quote_ru":"Маркировка должна содержать цифровой код и (или) буквенное обозначение (аббревиатуру) материала... в соответствии с Приложением 3 и должна содержать символы в соответствии с Приложением 4: рисунок 1... рисунок 2 (возможность утилизации использованной упаковки (укупорочных средств) - петля Мебиуса)."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.marks.material.code.and.mobius$txt$, $txt$material.mobius_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$mobius_loop$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$mobius_loop$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Петля Мёбиуса часто печатается на дне, боковом шве или под клапаном — снять все панели$txt$, null)
