insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.material.code.position.relative.to.mobius$txt$, null, $txt$horizontal$txt$, $txt$Взаимное расположение знаков идентификации: код внутри петли Мёбиуса, аббревиатура — под петлёй$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$взаимное положение элементов видно на макро-кадре, но формулировка примечания 1 в официальном тексте противоречива (рис. 2 — это и есть сама петля Мёбиуса), поэтому строгий автоматический вердикт давать нельзя$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"TRTS005","clause":"Приложение 3, примечание 1","quote_ru":"Знаки идентификации проставляются следующим образом: внутри петли Мебиуса - цифровой код и (или) буквенное обозначение, под петлей Мебиуса - рисунок 2 в соответствии с Приложением 4..."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
