insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.material.code.conditional.on.mobius$txt$, null, $txt$horizontal$txt$, $txt$Цифровой код или буквенное обозначение НЕ проставляется при отсутствии петли Мёбиуса$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$правило снимает ложную тревогу: если петли Мёбиуса нет, отсутствие кода не является нарушением$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"TRTS005","clause":"Приложение 3, примечание 2 (и примечание 3)","quote_ru":"Цифровой код или буквенное обозначение не проставляется при отсутствии петли Мебиуса. ... Цифровой код и буквенное обозначение могут использоваться в любом из предложенных вариантов."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
