insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.food.contact.glass.fork$txt$, null, $txt$horizontal$txt$, $txt$Упаковка, предназначенная для контакта с пищевой продукцией, маркируется символом «рюмка-вилка»$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$сам символ узнаваем визуально, но требование адресовано упаковке как продукции: на потребительской упаковке готового пищевого товара знака законно может не быть, а на стекле и пластике он часто выполнен рельефом (примечание 4 Приложения 3) и на фото не читается. Отсутствие символа в кадре — не нарушение$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$04$txt$, $txt$24$txt$]::text[], $txt${"act_id":"TRTS005","clause":"ст. 6 п. 2; Приложение 4, рис. 1","quote_ru":"Рис. 1. Упаковка (укупорочные средства), предназначенная для контакта с пищевой продукцией. Символ... допускается наносить как без рамки, так и в рамке (круглой, квадратной и др.)."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.marks.food.contact.glass.fork$txt$, $txt$food_contact.glass_fork_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$food_contact_mark$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$glass_fork$txt$, null, null, $txt${"min_count":1,"frame_variants_allowed":["без рамки","круглая рамка","квадратная рамка","иная рамка"]}$txt$::jsonb, $txt$Символ чаще всего на дне или обороте; на потребительской упаковке готовой пищевой продукции он может отсутствовать законно — требование адресовано упаковке как товару$txt$, null)
