insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.material.symbol.size.not.regulated$txt$, null, $txt$horizontal$txt$, $txt$Размеры символов маркировки материала устанавливает изготовитель; допускается рельефное исполнение$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$нормативного минимального размера нет, а рельефные (тиснёные, формованные) символы на стекле и пластике при обычном освещении на фото не читаются$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"TRTS005","clause":"Приложение 3, примечание 4","quote_ru":"Размеры символов устанавливаются изготовителем упаковки в зависимости от технических возможностей. Символы могут быть выполнены любым контрастным по отношению к цвету упаковки цветом или рельефно."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.material.composite.c.slash$txt$, null, $txt$horizontal$txt$, $txt$Комбинированные материалы маркируются как «C/» + обозначение основного по массе материала$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$формат обозначения читается как текст на макро-кадре, но комбинированность материала (коды 80-99) по фотографии не устанавливается: если обозначения на упаковке нет, отличить комбинированную упаковку от однослойной по изображению невозможно, поэтому проверка работает только «сверху вниз» — от уже найденного кода к его формату$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"TRTS005","clause":"Приложение 3, сноска ** к таблице","quote_ru":"Маркируются следующим образом: латинская буква С и через косую черту обозначение основного материала по массе в композиции. Например, бумага и картон/пластмасса/алюминий - С/РАР."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.marks.material.composite.c.slash$txt$, $txt$material.composite_format$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$identity$txt$, $txt$other:80_99_c_pap_c_pet_c_alu$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Если упаковка комбинированная (код 80-99), нанесено ли обозначение вида «C/PAP», «C/PET», «C/ALU»?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["C/PAP","C/PET","C/ALU","С/PAP","84","81","90"],"expected_value":null,"language":["ru","uz","en"]}$txt$::jsonb, $txt$Макро-кадр зоны петли Мёбиуса; латинская C, не кириллическая — но на практике встречаются оба начертания$txt$, null)
