insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.material.durability$txt$, null, $txt$horizontal$txt$, $txt$Маркировка упаковки должна быть прочной, стойкой к истиранию и долговечной$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$стойкость к истиранию и долговечность определяются испытанием (трение, растворители, ускоренное старение), а не изображением$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"TRTS005","clause":"ст. 6 п. 1","quote_ru":"Маркировка должна быть прочной, стойкой к истиранию и долговечной."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
