insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.material.on.pack.or.docs$txt$, null, $txt$horizontal$txt$, $txt$Маркировка материала наносится непосредственно на упаковку и (или) в сопроводительную документацию$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$конструкция «и (или)» допускает наличие сведений только в документации, поэтому отсутствие кода на фото не равно нарушению$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"TRTS005","clause":"ст. 6 п. 1 (ред. с 21.05.2017)","quote_ru":"Маркировка, необходимая для идентификации материала... должна быть нанесена непосредственно на упаковку и (или) сопроводительную документацию. В случае отсутствия на упаковке соответствующей маркировки изготовитель продукции... должен нанести на ярлык (этикетку) маркировку..."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
