insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.uz.material.identification.mark$txt$, null, $txt$horizontal$txt$, $txt$РУз: идентификационный знак материала упаковки — петля Мёбиуса с буквенным обозначением и (или) цифровым кодом$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$визуально проверяемо теми же чеками, что и по ТР ТС 005/2011, но сам текст требования РУз не сверен по первоисточнику — возможны расхождения и в перечне кодов, и в том, допускается ли перенос маркировки в сопроводительную документацию. Пока норма не сверена, отрицательный результат — повод запросить документы, а не выносить нарушение$txt$, array[$txt$UZ$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"UZPKM109","clause":"не установлен точно","quote_ru":"Пересказ, НЕ ЦИТАТА: Технический регламент о безопасности упаковки и укупорочных средств (утв. ПКМ РУз от 24.02.2025 № 109; само постановление вступило в силу 26.02.2025 — по карточке lex.uz) предположительно устанавливает идентификационный знак материала, состоящий из петли Мёбиуса, буквенного обозначения и (или) цифрового кода материалов или их сочетаний. Полный текст на публичной странице lex.u"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.uz.material.identification.mark$txt$, $txt$uz.mobius_with_code$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$mobius_loop$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$mobius_loop$txt$, null, null, $txt${"min_count":1,"expect_accompanying_code":true,"semantics":"результат предварительный: норма-первоисточник не сверена, поэтому отсутствие знака фиксируется как «требуется сверка», а не как нарушение"}$txt$::jsonb, $txt$До сверки текста ПКМ № 109 использовать перечень кодов ТР ТС 005/2011 как рабочую гипотезу и помечать вердикт как предварительный$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.transport.handling.marks.necessity.from.product.norm$txt$, null, $txt$horizontal$txt$, $txt$Необходимость нанесения манипуляционных знаков устанавливается в стандартах или иных НД на конкретную продукцию$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$отсутствие манипуляционного знака на коробе не является нарушением само по себе — нужен НД на конкретную продукцию, а он вне кадра$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GOST14192","clause":"п. 5.11 (Измененная редакция, Изм. № 1)","quote_ru":"Необходимость нанесения манипуляционных знаков должна быть установлена в стандартах или других нормативных документах на продукцию."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.transport.handling.marks.necessity.from.product.norm$txt$, $txt$transport.handling_marks_any$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:any$txt$, null, null, $txt${"min_count":0,"semantics":"информационный инвентарь найденных знаков, а не пороговая проверка"}$txt$::jsonb, $txt$Снять две смежные боковые стенки короба целиком$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.transport.handling.marks.image.conformity$txt$, null, $txt$horizontal$txt$, $txt$Изображение, наименование и назначение манипуляционных знаков должны соответствовать таблице 1 ГОСТ 14192-96 (знаки № 1-23)$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$пиктограммы стандартизованы и надёжно КЛАССИФИЦИРУЮТСЯ на фото при фронтальном ракурсе; строгое соответствие начертания рисункам приложения В по фото не проверяется — это уже обмер, требующий масштаба$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GOST14192","clause":"п. 4.1, таблица 1 (наименования знаков № 5, 18, 19 — в редакции Изм. № 3); п. 4.3 (обозначение знака: номер или наименование + обозначение стандарта)","quote_ru":"Изображение, наименование и назначение манипуляционных знаков должны соответствовать указанным в таблице 1. ... В рекомендуемое обозначение манипуляционного знака входит номер (номера) знака или наименование знака по таблице 1 и обозначение настоящего стандарта. Пример: 2 ГОСТ 14192."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.transport.handling.marks.image.conformity$txt$, $txt$transport.handling_marks_classify$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:by_number$txt$, null, null, $txt${"min_count":0,"catalog":{"1":"Хрупкое. Осторожно","2":"Беречь от солнечных лучей","3":"Беречь от влаги","4":"Беречь от излучения","5":"Пределы температуры (до Изм. № 3 — «Ограничение температуры»)","6":"Скоропортящийся груз","7":"Герметичная упаковка","8":"Крюками не брать","9":"Место строповки","10":"Здесь поднимать тележкой запрещается","11":"Верх","12":"Центр тяжести","13":"Тропическая упаковка","14":"Штабелировать запрещается","15":"Поднимать непосредственно за груз","16":"Открывать здесь","17":"Защищать от радиоактивных источников","18":"Не кантовать (до Изм. № 3 — «Не катить»)","19":"Предел штабелирования по массе (до Изм. № 3 — «Штабелирование ограничено»)","20":"Зажимать здесь","21":"Не зажимать","22":"Предел по количеству ярусов в штабеле","23":"Вилочные погрузчики не использовать"},"allowed_variations":"знак № 3 допускается без символа дождевых капель (п. 5.10); допускается наносить знаки с просветами (п. 5.10); вместо знака допускается предупредительная надпись, если способ обращения знаком не выразить (п. 4.2)"}$txt$::jsonb, $txt$Кадр должен захватывать знак целиком с полями; при печати с просветами (трафарет) классификатор должен допускать разрывы линий$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.transport.handling.marks.position$txt$, null, $txt$horizontal$txt$, $txt$Манипуляционные знаки наносят на каждое грузовое место в левом верхнем углу на двух соседних стенках тары$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$положение знака на одной стенке проверяется по кадру, но требование «на двух соседних стенках» и «на каждом грузовом месте» требует нескольких ракурсов и всей партии$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GOST14192","clause":"п. 5.5, 5.5.1, 5.5.2","quote_ru":"Манипуляционные знаки (предупредительные надписи) наносят на каждое грузовое место в левом верхнем углу на двух соседних стенках тары... Знак № 9 наносят непосредственно на тару с двух противоположных сторон... Знак № 12 наносят на соседние боковую и торцовую поверхности упаковки на месте проекции фактического центра тяжести груза."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.transport.handling.marks.position$txt$, $txt$transport.mark_top_left$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:any$txt$, null, $txt$position$txt$, $txt${"target":"handling_mark:any","surface":"side_wall","expected_position":"top_left_quadrant","exceptions":{"9":"две противоположные стороны тары","12":"смежные боковая и торцовая поверхности в месте проекции центра тяжести; при перевозке на открытом подвижном составе дополнительно сверху и снизу","бочки_барабаны":"на одном из днищ или на корпусе","мешки":"на одной из сторон"},"reference_scale":"не требуется (относительное положение в пределах грани)"}$txt$::jsonb, $txt$Нужны два кадра — по одному на каждую из двух смежных стенок; угловой ракурс, захватывающий обе грани, тоже подходит$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.transport.handling.marks.colour$txt$, null, $txt$horizontal$txt$, $txt$Манипуляционные знаки — тёмного цвета на светлых поверхностях и светлого на тёмных; для знаков № 1, 6, 13 установлены особые цвета$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$цвет знака определим по фото, но зависит от освещения и баланса белого; числового порога контраста стандарт не задаёт$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GOST14192","clause":"п. 5.10","quote_ru":"Манипуляционные знаки и надписи должны быть темного цвета на светлых поверхностях и светлого на темных. Знак № 1 допускается выполнять красного цвета на светлом фоне при транспортировании груза по железной дороге. Знак № 6 выполняют голубым цветом на светлом фоне. Знак № 13 выполняют красным цветом."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.transport.handling.marks.colour$txt$, $txt$transport.mark_contrast$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:any$txt$, null, $txt$contrast_ratio$txt$, $txt${"target":"handling_mark:any","min_contrast_ratio":null,"norm_has_no_numeric_threshold":true,"suggested_operational_threshold":3,"colour_rules":{"1":"чёрный либо красный на светлом фоне (для ж/д)","6":"голубой на светлом фоне","13":"красный"},"reference_scale":"не требуется; нужен кадр с корректным балансом белого, желательно с серой картой"}$txt$::jsonb, $txt$Снять с нейтральным освещением; при сомнении в цвете вложить в кадр эталон серого$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.transport.label.geometry$txt$, null, $txt$horizontal$txt$, $txt$Геометрия ярлыков: ярлык для основных/дополнительных/информационных надписей — площадь не менее 60 см2 при рекомендуемом соотношении сторон 2:3; на типографском ярлыке знак не ближе 5 мм от края$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$размеры в мм и см2 требуют калибровки масштаба; кроме того, в стандарте ДВА разных ярлыка: п. 6.1 (площадь ≥ 60 см2, 2:3) — про ярлык с надписями, а таблица В.0 — про ярлыки для манипуляционных знаков, и её типовой ярлык 52x74 мм = 38,5 см2 под порог 60 см2 не подпадает. Смешивать их в один вердикт нельзя$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GOST14192","clause":"п. 6.1, 6.3, 6.4; приложение В, таблица В.0 (п. 6.2 с таблицей 2 ИСКЛЮЧЁН Изменением № 3, размеры ярлыков перенесены в приложение В)","quote_ru":"6.1: «Площадь маркировочного ярлыка для нанесения основных, дополнительных и информационных надписей должна быть не менее 60 см2. Рекомендуемое соотношение сторон 2:3.» 6.4: «На ярлыках, изготовленных типографским способом, знак должен быть на расстоянии не менее 5 мм от края ярлыка.»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.transport.label.geometry$txt$, $txt$transport.label_area$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$shipping_label$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"shipping_label","min_mm":null,"min_area_cm2":60,"min_area_cm2_applies_to":"только ярлык для основных, дополнительных и информационных надписей (п. 6.1); к ярлыкам для манипуляционных знаков этот порог не относится","recommended_aspect_ratio":0.667,"label_sizes_mm_appendix_B0":{"52 x 74":"грузовое место длиной/шириной до 1000 мм включ., высотой до 200 мм включ.","74 x 105":"длина/ширина св. 1000 до 1500 мм включ., высота св. 200 мм","105 x 148":"длина/ширина св. 1500 мм","148 x 210":"габарит грузового места в таблице В.0 не ограничен","уменьшенные":"37 x 52 и 26 x 37 — если размеры грузового места не позволяют применить размеры таблицы В.0; при этом размеры знаков выбирают произвольно при соблюдении изображения знака","предельное_отклонение":"+10 мм","источник":"приложение В, таблица В.0 (в редакции Изм. № 3). Прежняя таблица 2 п. 6.2 с диапазонами «до 190 мм» и «1500 мм» БОЛЬШЕ НЕ ДЕЙСТВУЕТ"},"reference_scale":"нужна калибровка, см. scale.calibration_method"}$txt$::jsonb, $txt$Сфотографировать ярлык фронтально вместе с опорным объектом известного размера$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
