insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.transport.handling.marks.size$txt$, null, $txt$horizontal$txt$, $txt$Рекомендуемые размеры манипуляционных знаков и их деталей — по приложению В ГОСТ 14192-96, увязаны с размером ярлыка$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$приложение В рекомендуемое, поэтому отклонение не является нарушением; проверять можно лишь соответствие ряду типовых размеров при наличии масштаба$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GOST14192","clause":"п. 6.5 (в ред. Изм. № 3 — «Рекомендуемые размеры ярлыков, манипуляционных знаков и их деталей»); приложение В (рекомендуемое), таблицы В.0 и В.1-В.23","quote_ru":"Рекомендуемые размеры ярлыков, манипуляционных знаков и их деталей, наносимых на ярлыки, непосредственно на тару или изделие, приведены в приложении В. «Размеры знаков и их деталей, приведенные в таблицах В.1-В.23 и на рисунках В.1-В.23, установлены с учетом размеров ярлыков, указанных в таблице В.0» (абзац в ред. Изм. № 3; прежняя отсылка была к таблице 2, которая исключена)."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.transport.handling.marks.size$txt$, $txt$transport.mark_size_series$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:fragile$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"handling_mark:fragile","recommended_series_mm":{"знак_1_Хрупкое_Осторожно":[{"B":24,"b":10,"H":64,"h":38,"r":12,"S":3},{"B":36,"b":15,"H":95,"h":54,"r":18,"S":5},{"B":52,"b":20,"H":138,"h":80,"r":26,"S":7},{"B":76,"b":25,"H":200,"h":115,"r":38,"S":10}],"знак_2_Беречь_от_солнечных_лучей_H":[56,80,115,165],"знак_3_Беречь_от_влаги_H":[64,95,138,200],"примечание":"полные таблицы В.1-В.23 приведены в приложении В; в JSON вынесены только сверенные по официальному тексту ряды для знаков № 1-3 (таблицы В.1, В.2, В.3)"},"min_mm":0,"min_mm_semantics":"обязательного минимума размера знака стандарт не устанавливает (приложение В — рекомендуемое), поэтому порог = 0: движок должен ЗАФИКСИРОВАТЬ измеренную высоту, а не сравнивать её с нормой. Значение null здесь недопустимо: цель handling_mark:fragile сопоставлена реальному классу детектора, и сравнение с null уронило бы geometry-движок","reference_scale":"нужна калибровка, см. scale.calibration_method"}$txt$::jsonb, $txt$Проверка справочная; фиксировать фактическую высоту знака H, а не выносить вердикт о нарушении$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.transport.font.height$txt$, null, $txt$horizontal$txt$, $txt$Высота шрифта транспортной маркировки: ряд 3, 6, 8, 10, 15, 30, 50, 100 мм РЕКОМЕНДУЕМЫЙ, но шрифты 3 и 6 мм прямо не допускаются при нанесении надписей непосредственно на тару$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$высота шрифта в мм измерима только по калиброванному кадру; часть требований (6.7, 6.8) зависит от габарита грузового места, который в кадр может не попасть$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GOST14192","clause":"п. 6.6, 6.7, 6.8, 6.9","quote_ru":"Рекомендуемые высоты шрифта для нанесения маркировочных надписей: 3, 6, 8, 10, 15, 30, 50 и 100 мм. Шрифты высотой 3 и 6 мм не допускается применять при нанесении надписей непосредственно на тару."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.transport.font.height$txt$, $txt$transport.font_min_height$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$geometry$txt$, $txt$other:3_6_8_10_15_30_50_100_3_6$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$transport_marking_text$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"transport_marking_text","min_mm":8,"measured_dimension":"высота прописной буквы при нанесении непосредственно на тару (3 и 6 мм запрещены, следующая градация ряда — 8 мм)","main_inscriptions_mm":{"до 0,5 м":30,"св. 0,5 до 1,5 м":50,"св. 1,5 м":100},"additional_inscriptions_mm":{"до 0,5 м":10,"св. 0,5 до 1,5 м":15,"св. 1,5 м":30},"relaxation":"п. 6.9 — при невозможности размещения допускается уменьшать высоту надписей и размер знака на 1-2 градации","surface":"transport_pack","reference_scale":"нужна калибровка, см. scale.calibration_method"}$txt$::jsonb, $txt$Кадр должен захватывать грузовое место целиком (чтобы оценить его габарит) плюс макро-кадр надписи с опорным объектом$txt$, null)
