insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.transport.marking.every.package$txt$, null, $txt$horizontal$txt$, $txt$Транспортная маркировка, включая манипуляционные знаки, должна быть нанесена на каждое грузовое место$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$требование относится ко всей партии; одна фотография одного короба не может подтвердить «на каждое грузовое место»$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GOST14192","clause":"п. 5.12 (Измененная редакция, Изм. № 1)","quote_ru":"Транспортная маркировка (основные, дополнительные и информационные надписи и манипуляционные знаки) должна быть нанесена на каждое грузовое место."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
