insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.transport.mobius.national.doc$txt$, null, $txt$horizontal$txt$, $txt$Знак «лента Мёбиуса» на транспортной таре наносится в соответствии с международными или национальными нормативными документами; при использовании вторичного сырья внутри или под знаком указывают его процентное содержание$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$сам знак и экологические знаки приложения Ж распознаются визуально, но соответствие знака требованиям международного/национального НД и достоверность указанного процента вторичного сырья по фотографии не проверяются$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"GOST14192","clause":"п. 8.7, 8.8 (введены Изм. № 2, изложены в новой редакции Изм. № 3); приложения Е, Ж и И","quote_ru":"8.7 (ред. Изм. № 3): «На тару и упаковку, которые после использования могут быть подвергнуты вторичной переработке, наносят маркировку с применением знака — «лента Мебиуса» в соответствии с требованиями международных или национальных нормативных документов. Если тара изготовлена из упаковочных материалов с применением вторичного сырья, то внутри знака или под знаком указывают процентное содержание"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.transport.mobius.national.doc$txt$, $txt$transport.mobius_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$marks$txt$, $txt$mobius_loop$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$mobius_loop$txt$, null, null, $txt${"min_count":0,"eco_marks_appendix_zh":["Подлежит утилизации (подлежит вторичной переработке)","То же (второй вариант изображения)","Беречь от загрязнений окружающую среду"],"appendix_I_code_ranges":"приложение И (введено Изм. № 3): полимеры 1-19; бумага и картон 20-39; металл 40-49; древесина и древесные материалы 50-59; текстильные материалы 60-69; стекло 70-79; комбинированные материалы 80-98","semantics":"инвентаризация знака и сопутствующего кода; вердикт о соответствии знака национальному/международному НД по фото не выносится"}$txt$::jsonb, $txt$Знак печатают у шва или на клапане гофрокороба; снять всю боковую грань$txt$, null)
