insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.iso780.symbol.conformity$txt$, null, $txt$horizontal$txt$, $txt$Соответствие пиктограмм ISO 780:2015: 17 графических символов, цвет чёрный, высота 100/150/200 мм, минимально необходимое число типов знаков$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$цвет и наличие контрастной подложки проверяются по кадру, а высота 100/150/200 мм требует масштаба; полный перечень наименований 17 знаков доступен только в платном тексте стандарта$txt$, array[$txt$ANY$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"ISO780","clause":"п. 3.2, 3.3, 3.4, 3.5, 3.6; разд. 4 (таблицы 1-6)","quote_ru":"3.3: «The colour used for graphical symbols shall be black. If the colour of the package is such that the black symbol would not show clearly, a panel of a suitable contrasting colour, preferably white, shall be provided as a background.» 3.4: «For normal purposes the overall height of the graphical symbols shall be 100mm, 150mm or 200mm.»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.iso780.symbol.conformity$txt$, $txt$iso780.colour_black$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$un3481$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:any$txt$, null, $txt$contrast_ratio$txt$, $txt${"target":"handling_mark:any","required_colour":"black","fallback":"контрастная подложка, предпочтительно белая, если чёрный знак на цвете упаковки не читается","forbidden_colours_context":"избегать красного, оранжевого, жёлтого — риск смешения с маркировкой опасных грузов (п. 3.3)","min_contrast_ratio":null,"reference_scale":"не требуется"}$txt$::jsonb, $txt$Кадр с корректным балансом белого; при печати знака красным/оранжевым/жёлтым отметить риск смешения с ADR/IMDG-маркировкой$txt$, null)
