insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.iso780.symbol.conformity$txt$, $txt$iso780.frame_not_required$txt$, 2, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:any$txt$, null, null, $txt${"min_count":0,"framing_required":false,"note_ru":"п. 3.2: знаки не обязаны быть обрамлены рамкой; допускается трафаретное нанесение с изменением графики ради формирования трафарета","verified_symbol_names":{"No.1":"CENTRE OF GRAVITY (ISO 7000, No.0627)","No.2":"SLING HERE (ISO 7000, No.0625)"},"total_symbols":17,"grouping":"Таблица 1 — крупногабаритная упаковка; Таблицы 2-4 — средняя и малая упаковка (все виды обработки / ручная / механизированная); Таблица 5 — транспортировка и хранение; Таблица 6 — хранение","honesty_note":"наименования знаков № 3-17 в открытой части стандарта отсутствуют и в этом файле НЕ приводятся, чтобы не выдумывать формулировки"}$txt$::jsonb, $txt$Не считать нарушением отсутствие рамки вокруг пиктограммы$txt$, null)
