insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.marks.crossed.bin.not.mandated.in.eaeu.uz$txt$, null, $txt$horizontal$txt$, $txt$Знак «перечёркнутый мусорный бак» НЕ является обязательным по ТР ТС 005/2011, ГОСТ 14192-96 и (по результатам проверки) ТР ЕАЭС 037/2016$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$наличие знака детектируется визуально; важно не выдавать его отсутствие за нарушение норм ЕАЭС/РУз$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"TREAEU037","clause":"разд. V «Требования к маркировке и эксплуатационным документам» — требование не обнаружено","quote_ru":"Пересказ и честный отрицательный вывод: в ТР ТС 005/2011 приложение 4 содержит только два символа — знак пищевого контакта (рис. 1) и петлю Мёбиуса (рис. 2); знака перечёркнутого бака в регламенте нет. В ГОСТ 14192-96 приложение Ж содержит три экологических знака, перечёркнутого бака среди них нет. В доступных изложениях разд. V ТР ЕАЭС 037/2016 требование о перечёркнутом баке не обнаружено; утвер"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.marks.crossed.bin.not.mandated.in.eaeu.uz$txt$, $txt$crossed_bin.inventory_only$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$marks$txt$, $txt$waste_bin_mark$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$crossed_out_wheelie_bin$txt$, null, null, $txt${"min_count":0,"semantics":"инвентаризация, не пороговая проверка; отсутствие знака НЕ является нарушением требований ЕАЭС/РУз","eu_reference":{"act":"Directive 2012/19/EU (WEEE), EN 50419","source_id":"WEEE50419","min_symbol_height_mm":7,"min_height_applies_to":"высота самого знака бака, не «сочетания знака»","black_bar_meaning":"один из двух допустимых способов показать размещение на рынке после 13.08.2005 (альтернатива — указание даты размещения); отсутствие полосы само по себе ничего не доказывает"}}$txt$::jsonb, $txt$Фиксировать факт наличия; при экспорте в ЕС высота знака >= 7 мм проверяется только по калиброванному кадру (см. scale.calibration_method)$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$horizontal.scale.calibration.method$txt$, null, $txt$horizontal$txt$, $txt$МЕТОДИКА: как получить масштаб (px/mm) по фотографии, без которого проверки «не менее 5 мм» невыполнимы$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$точность масштаба определяется опорным объектом: карта ID-1 даёт погрешность <0,2 %, лист A4 — около 0,5 %, EAN-13 — только вилку в 2,5 раза, пачка сигарет — грубую оценку с ошибкой до +/-10 %$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"GS1EANUPC","clause":"таблица «UPC-A/EAN-13 Barcode Symbol Dimensions» (сверено также с ISO7810, ISO216, GOST3935)","quote_ru":"Пересказ: EAN-13/UPC-A при 100 % увеличении (X = 0,330 мм) — 31,35 мм между крайними штрихами, 37,29 мм с зонами молчания, минимальная высота штрихов 22,86 мм; допустимый диапазон увеличений 80-200 % (X = 0,26-0,66 мм), для термопечати по требованию — от 75 %."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$horizontal.scale.calibration.method$txt$, $txt$scale.anchor_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$marks$txt$, $txt$eac_mark$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$scale_reference_object$txt$, null, null, $txt${"min_count":1,"note":"это проверка НАЛИЧИЯ опорного объекта, а не измерение: миллиметрового порога здесь нет, поэтому kind=presence, а не geometry/min_size_mm","surface":"same_focal_plane_as_measured_mark","reference_scale":"px_per_mm = длина опорного объекта в пикселях / его нормативная длина в мм; опорный объект обязан лежать в той же плоскости, что и измеряемый знак, кадр — фронтальный","anchors_ranked":[{"rank":1,"object":"Карта формата ID-1 (банковская, ID, транспортная)","nominal_mm":{"width":85.6,"height":53.98,"thickness":0.76,"corner_radius":"2,88-3,48"},"tolerance_mm":"ширина 85,47-85,72; высота 53,92-54,03 (для новой карты)","relative_error":"< 0,2 %","source_id":"ISO7810","note":"лучший опорный объект: жёсткий, плоский, всегда под рукой, тугой допуск"},{"rank":2,"object":"Лист бумаги A4","nominal_mm":{"width":210,"height":297},"tolerance_mm":"+/-2 мм по ISO 216 для размеров > 150 мм","relative_error":"около 0,5-1 %","source_id":"ISO216","note":"хорош для крупных объектов (транспортный короб); длинная база снижает влияние ошибки локализации края"},{"rank":3,"object":"Символ EAN-13 на той же упаковке","nominal_mm":{"bar_to_bar_100pct":31.35,"with_quiet_zones_100pct":37.29,"min_bar_height_100pct":22.86,"X_dimension_100pct":0.33},"module_structure":"95 модулей между крайними штрихами; 113 модулей с зонами молчания (левая 11X, правая 7X)","magnification_range":"80-200 % (X = 0,26-0,66 мм); ширина с зонами молчания 29,83-74,58 мм; для термопечати по требованию допускается 75 %","relative_error":"НЕ определён по одному кадру — увеличение символа неизвестно, разброс масштаба до 2,5 раз","source_id":"GS1EANUPC","note":"ЧЕСТНОЕ ОГРАНИЧЕНИЕ: EAN-13 в кадре даёт не масштаб, а ВИЛКУ масштаба. Использовать только как sanity-check: если знак EAC меньше 5 мм даже при допущении максимального увеличения штрихкода (200 %), нарушение доказано; в обратную сторону вывод не работает"},{"rank":4,"object":"Пачка сигарет king size","assumed_mm":{"height":"85-88","width":"55","depth":"22-23"},"relative_error":"до +/-10 %","source_id":"GOST3935","note":"ЧЕСТНОЕ ОГРАНИЧЕНИЕ: единого нормативного габарита пачки НЕ существует. ГОСТ 3935-2000 нормирует только длину сигареты (45-160 мм, предельное отклонение +/-1,0 мм) и длину фильтра (12-45 мм, +/-0,5 мм), а не размеры пачки. Значение 85x55x22 мм — отраслевая практика для формата king size, а не норма. Применять только как грубую прикидку и всегда помечать результат как ориентировочный"},{"rank":5,"object":"Собственная масштабная сетка знака EAC","nominal":"знак построен на сетке 9x9 клеток (рис. 3 и 4 Положения к Решению № 711)","use":"не даёт абсолютного масштаба, но позволяет проверить пропорции знака и корректность его построения","source_id":"KTS711"}],"procedure":["1. Кадр строго перпендикулярно поверхности (иначе перспектива искажает размеры на 5-20 %).","2. Опорный объект в той же плоскости, что и измеряемый знак; при съёмке цилиндрической/выпуклой упаковки измерять только у центра кадра.","3. Вычислить px_per_mm по длинной стороне опорного объекта.","4. Измерить сторону описанного квадрата знака EAC в пикселях, разделить на px_per_mm.","5. Учесть допуск на локализацию границ знака: +/-1-2 px на каждой стороне; при px_per_mm < 20 проверку «>= 5 мм» не выносить — разрешения недостаточно.","6. Порог применимости: чтобы измерить 5 мм с погрешностью 10 %, нужно не менее 20 px на миллиметр в зоне знака (знак 5 мм = не менее 100 px)."]}$txt$::jsonb, $txt$Если в кадре нет ни одного опорного объекта — вернуть вердикт «нет масштаба» и запросить пересъёмку с банковской картой рядом со знаком$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

