insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.manufacturer.country$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: указаны наименование изготовителя (уполномоченного лица, импортёра), страна и адрес, а также лицо, уполномоченное на приём претензий от потребителей$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$изготовитель и страна читаются на гранях пачки, но сведения о лице для претензий норма разрешает размещать на ВНУТРЕННЕЙ стороне упаковки$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"п. 19 подпункты «в», «г» раздела VII","quote_ru":"в) наименование юридического лица... уполномоченного изготовителем на принятие претензий от потребителей, его местонахождение (страна и адрес)... может быть размещена на внешней или внутренней стороне потребительской упаковки; г) наименование изготовителя, уполномоченного изготовителем лица или импортера, его местонахождение (страна и адрес)"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
