insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.manufacturer.country$txt$, $txt$eaeu.claims.acceptor_text$txt$, 2, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer_address$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на упаковке наименование и адрес лица, принимающего претензии от потребителей?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["претензии","принимает претензии","ООО","АО","MChJ","адрес"],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Если не видно — снять внутреннюю сторону вскрытой пачки и боковые клапаны, иначе результат недостоверен$txt$, null)
