insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.filter.info$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: для курительных изделий с фильтром указаны сведения о наличии фильтра$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО с checkable. Надпись «с фильтром» действительно читается на фото, но норма применяется ТОЛЬКО к курительным изделиям С ФИЛЬТРОМ, а наличие фильтра у закрытой пачки по фотографии не устанавливается. Отсутствие надписи по одному фото нельзя квалифицировать как нарушение: это либо нарушение, либо изделие без фильтра. Применимость требования задаётся вручную или из карточки товара.$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"п. 19 подпункт «д» раздела VII","quote_ru":"сведения о наличии фильтра (для курительных табачных изделий с фильтром)"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.filter.info$txt$, $txt$eaeu.filter.mention$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$identity$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на пачке указание на наличие фильтра?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["с фильтром","фильтр","filtrli"],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Проверять только если из карточки товара известно, что изделие с фильтром. Наличие фильтра по фото закрытой пачки не определяется — при отсутствии надписи ставить review, а не fail.$txt$, null)
