insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.piece.count$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: указано количество штук (для штучных изделий) или масса нетто в граммах (для весовых)$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$число сигарет («20 шт.») печатается на лицевой или боковой стороне пачки$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"п. 19 подпункт «е» раздела VII","quote_ru":"сведения о количестве штук (для штучных табачных изделий) или массе нетто (г) (для весовых табачных изделий)"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
