insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.piece.count$txt$, $txt$eaeu.count.value$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$quantity_units$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Указано ли количество сигарет в пачке (число со словом «штук»/«шт.») или масса нетто в граммах?$txt$, null, $txt${"expect":"value_with_unit","unit":"шт|г","pattern_hints":["шт","штук","сигарет","dona","г","g"],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Снять лицевую и обе боковые стороны; число может быть частью надписи «20 сигарет с фильтром»$txt$, null)
