insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.warning.present$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: на каждую потребительскую упаковку нанесено предупреждение о вреде потребления табачных изделий по утверждённому ЕЭК эскизу (изображение + текст)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$наличие предупреждения и наличие пиктограммы видно на фото, но совпадение с конкретным утверждённым эскизом требует сверки с эталонной библиотекой изображений$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"пп. 19 «ж», 27, 28 раздела VII","quote_ru":"На каждую потребительскую упаковку табачной продукции (лист-вкладыш) наносится предупреждение о вреде потребления табачных изделий. Эскизы... утверждаются Евразийской экономической комиссией."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
