insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.warning.present$txt$, $txt$eaeu.warning.pictogram_present$txt$, 1, $txt$presence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$warnings$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$health_warning_pictogram$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Утверждённые эскизы ЕЭК включают цветной рисунок или фотоизображение (п. 4 Параметров нанесения), поэтому чисто текстовое предупреждение — признак нарушения. ВНИМАНИЕ: формулировка «формат двух слоев» относится к п. 2 Решения ЕЭК № 18 — к публикации графических файлов на сайте ЕАЭС, а не к требованию к пачке; ссылаться на неё как на норму нанесения нельзя.$txt$, null)
