insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.warning.present$txt$, $txt$eaeu.warning.text_present$txt$, 2, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$warnings$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли внутри блока предупреждения текст о вреде потребления табака/курения для здоровья?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["курение","вред","убивает","здоровь","табак"],"expected_value":null,"language":["ru","uz","kk","hy","ky"]}$txt$::jsonb, $txt$Текст должен читаться; при бликах переснять без вспышки в лоб$txt$, null)
