insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.warning.area.50$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: предупреждение занимает не менее 50% площади лицевой и не менее 50% площади обратной основной стороны пачки$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Доля площади считается без абсолютного масштаба, но нужен фронтальный кадр КАЖДОЙ из двух основных сторон. Границы «основной стороны» на фото размыты (фаски, шов крышки). По п. 4 Параметров (Решение ЕЭК № 18) при соотношении сторон более 1,92 в зачёт 50% идёт сумма площади эскиза и площади заливки Pantone 448С — мерить надо весь блок. Расхождение до ±5 п.п. — на ручной разбор.$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"п. 29 абз. 2 раздела VII","quote_ru":"Предупреждение о вреде потребления табачных изделий должно занимать не менее 50 процентов площади этих сторон."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.warning.area.50$txt$, $txt$eaeu.warning.area_front$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$geometry$txt$, $txt$other:50_50$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$health_warning_block$txt$, null, $txt$area_fraction$txt$, $txt${"target":"health_warning_block","min_mm":null,"min_area_fraction":0.5,"surface":"front_panel","reference_scale":"масштаб не нужен — доля от площади панели; требуется перспективная коррекция по четырём углам панели. Измеряемый объект — весь блок предупреждения (эскиз + залитая Pantone 448С площадь, если она есть), а не только пиктограмма. Без полностью видимой панели проверку не выполнять."}$txt$::jsonb, $txt$Снять лицевую сторону фронтально, вся панель в кадре, без наклона и обрезки краёв$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.warning.area.50$txt$, $txt$eaeu.warning.area_back$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$geometry$txt$, $txt$other:50_50$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$health_warning_block$txt$, null, $txt$area_fraction$txt$, $txt${"target":"health_warning_block","min_mm":null,"min_area_fraction":0.5,"surface":"back_panel","reference_scale":"масштаб не нужен — доля от площади панели; требуется перспективная коррекция по четырём углам панели. Измеряемый объект — весь блок предупреждения (эскиз + залитая Pantone 448С площадь, если она есть), а не только пиктограмма. Без полностью видимой панели проверку не выполнять."}$txt$::jsonb, $txt$Отдельный фронтальный кадр обратной стороны — по фото только лицевой стороны требование не проверяется$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.warning.position.language$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: предупреждение расположено в верхних частях лицевой и обратной сторон; текст на лицевой — на госязыке страны реализации, на обратной — на русском языке$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Положение блока (верх/низ) определяется на фото. По тексту п. 29 исключение «перекрывается маркой или разрушается при открывании — располагается на нижней части» относится ТОЛЬКО к обратной основной стороне; для лицевой верхнее положение безусловно. Применимость исключения сзади по фото не устанавливается — нижний блок на обороте сам по себе нарушением не считать.$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"п. 29 абз. 1 и 3 раздела VII","quote_ru":"должно располагаться на верхних частях лицевой и обратной основных сторон... если перекрывается маркой или разрушается при обычном открывании — располагается на нижней части"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.warning.position.language$txt$, $txt$eaeu.warning.pos_front_top$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$health_warning_block$txt$, null, $txt$position$txt$, $txt${"target":"health_warning_block","min_mm":null,"min_area_fraction":null,"surface":"front_panel","reference_scale":"относительные координаты центра блока внутри рамки панели; ожидается верхняя половина"}$txt$::jsonb, $txt$Кадр всей лицевой панели целиком, чтобы были видны её верхняя и нижняя границы$txt$, null)
