insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.warning.render.params$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: параметры воспроизведения эскиза — разрешение не менее 300 dpi; при соотношении высоты к ширине более 1,92 отведённая свободная площадь заливается цветом Pantone 448С, перенесённый на неё текст — прописными белыми буквами жирным шрифтом; изменение пропорций эскиза — не более 20%$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$300 dpi — параметр допечатного файла эскиза, а не изображения на пачке; точный Pantone 448С на снимке без калибровочной мишени и цветового профиля камеры не определяется; соблюдение допуска пропорций 20% требует эталонного эскиза для сравнения.$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"EEC18","clause":"Приложение к Решению Совета ЕЭК № 18, раздел II «Параметры нанесения эскизов предупреждений», пп. 1-4 (300 dpi — п. 1; допуск 20% — пп. 2-4; Pantone 448С и белые прописные полужирные буквы — только п. 4, случай соотношения сторон более 1,92). Формат «двух слоев» — это п. 2 самого Решения № 18 (поручение о публикации графических файлов на сайте ЕАЭС), к нанесению на пачку не относится","quote_ru":"1. Разрешение эскизов предупреждений... составляет не менее 300 dpi. ...4. ...площадь, не занятая предупреждением, но отведенная под предупреждение... заливается... цветом, соответствующим цвету Pantone 448С... наносится прописными буквами белого цвета, жирным... шрифтом... допускается изменение пропорций не более чем на 20 процентов"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.toxic.side.notice$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: на боковой поверхности пачки — надпись «Содержит системные яды, канцерогенные и мутагенные вещества», шрифт Helvetica, контрастный цвет, не менее 17% площади боковой стороны$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$текст и доля площади боковой грани проверяемы при фронтальном кадре боковины, но гарнитура Helvetica по фотографии надёжно не идентифицируется$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"пп. 19 «к», 30 раздела VII","quote_ru":"шрифтом Helvetica в виде надписи: «Содержит системные яды, канцерогенные и мутагенные вещества», которая должна занимать не менее 17 процентов поверхности площади боковой стороны упаковки"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
