insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.prohibited.misleading.terms$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: ЗАПРЕЩЕНЫ слова «с низким содержанием смол», «легкие», «очень легкие», «мягкие», «экстра», «ультра», их однокоренные слова, иностранные аналоги (light, mild, superlight) и транслитерации$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО с checkable. Перечисленные в п. 21 слова ловятся OCR и стоп-листом, но норма запрещает «любые термины, описания, знаки, символы или иные обозначения», косвенно создающие впечатление меньшей вредности, плюс однокоренные слова, иностранные аналоги и транслитерации — открытый класс. Чистый результат означает лишь «явных маркеров не найдено».$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"п. 21 абз. 1 раздела VII","quote_ru":"не должна содержать... такие слова, как «с низким содержанием смол», «легкие», «очень легкие», «мягкие», «экстра», «ультра»... а также аналоги таких слов на иностранных языках"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.prohibited.misleading.terms$txt$, $txt$eaeu.prohibited.terms$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$composition$txt$, $txt$tar_nicotine_co$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на пачке слова «лёгкие», «light», «mild», «с низким содержанием смол», «мягкие», «экстра», «ультра» или их аналоги/транслитерации?$txt$, null, $txt${"forbidden_terms":["лёгкие","легкие","очень легкие","мягкие","с низким содержанием смол","экстра","ультра","light","lights","ultra light","superlight","super light","mild","milds","low tar","extra","ultra","yengil","juda yengil","yumshoq","qatron miqdori kam","лайт","майлд"],"forbidden_imagery":null}$txt$::jsonb, $txt$Снять все шесть граней. Сопоставлять по границам слов, а не подстрокой: «extra»/«ultra»/«mild» внутри других слов и в составе зарегистрированного товарного знака дают ложные срабатывания. Стоп-лист неполон по построению — при чистом результате ставить pass только по явным маркерам, класс «косвенных обозначений меньшей вредности» остаётся за ручным разбором.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.prohibited.food.medicine.imagery$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: ЗАПРЕЩЕНЫ изображения пищевых продуктов, лекарственных средств и лекарственных растений и слова, создающие ассоциации табачного изделия с ними (кроме указания на ментол и характер аромата для сигар, сигарилл, кальянного, тонкорезаного и трубочного табака)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$явные изображения фруктов/ягод/трав детектируются, но граница «косвенной ассоциации» — оценочная и требует эксперта$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"п. 21 абз. 2-3 раздела VII","quote_ru":"не должна содержать изображений пищевых продуктов, лекарственных средств, лекарственных растений, а также слов, которые прямо или косвенно создают ассоциации табачного изделия с ними"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.prohibited.food.medicine.imagery$txt$, $txt$eaeu.prohibited.food_imagery$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$prohibitions$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на пачке изображения пищевых продуктов, лекарств или лекарственных растений (ягоды, фрукты, капсулы, травы)?$txt$, null, $txt${"forbidden_terms":["вкус","аромат ягод","berry","cherry","vanilla","mango","ta'm"],"forbidden_imagery":"фрукты, ягоды, конфеты, напитки, таблетки/капсулы, аптечные символы, пучки лекарственных трав"}$txt$::jsonb, $txt$Снять лицевую сторону и все грани; для спорных изображений передать кадр эксперту$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.prohibited.tar.figures.and.claims$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: ЗАПРЕЩЕНО наносить количественные показатели содержания смолы, никотина и монооксида углерода, а также утверждения о снижении риска заболеваний, меньшей опасности изделия или пользе$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО с checkable. Числа «смола 10 мг / никотин 0,8 мг» читаются OCR, но вторая половина п. 22 — утверждения о снижении риска заболеваний и о меньшей опасности изделия — задана содержательно, а не списком слов; выявление изображений, «намекающих на пользу», оценочно. По этой части результат — сигнал на ручной разбор, а не вердикт.$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"п. 22 раздела VII","quote_ru":"Не допускается нанесение... количественных показателей содержания смолы, никотина и монооксида углерода в дыме табачных изделий, а также утверждений о снижении риска заболеваний"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.prohibited.tar.figures.and.claims$txt$, $txt$eaeu.prohibited.tar_figures$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$composition$txt$, $txt$tar_nicotine_co$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на пачке числовые показатели содержания смолы, никотина или CO (например «Смола 10 мг, Никотин 0,8 мг»)?$txt$, null, $txt${"forbidden_terms":["смола","смолы","никотин","монооксид углерода","угарный газ","мг/сиг","мг/сиг.","tar","nicotine","carbon monoxide","qatron"],"forbidden_imagery":null}$txt$::jsonb, $txt$ВНИМАНИЕ: для рынка Узбекистана эти сведения, наоборот, ОБЯЗАТЕЛЬНЫ (ПКМ № 290 п. 35 пп. 9) — проверять требование только для пачек рынка ЕАЭС. Из стоп-листа удалён токен «CO»: как подстрока он срабатывает на «CO.», «Company» и любой латинице в адресе изготовителя. Ловить только пары «число + мг» рядом со словом-маркером.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.prohibited.tar.figures.and.claims$txt$, $txt$eaeu.prohibited.health_claims$txt$, 1, $txt$absence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$composition$txt$, $txt$tar_nicotine_co$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли утверждения о снижении риска заболеваний, о меньшей опасности данного изделия или о его положительном/лечебном эффекте?$txt$, null, $txt${"forbidden_terms":["менее опасн","снижает риск","безопасн","полезн","less harmful","reduced risk"],"forbidden_imagery":"медицинские символы (крест, кардиограмма, «здоровое лёгкое»), намекающие на пользу"}$txt$::jsonb, $txt$Проверять и лист-вкладыш, если он есть$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.placement.and.overprint$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: информация нанесена чёткими несмываемыми буквами, размещена так, чтобы не нарушалась целостность надписей при открывании, не печатается на прозрачной плёнке и не перекрывается другой печатной информацией; марки не перекрывают лицевую сторону$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$перекрытие маркой лицевой стороны видно на фото; «целостность при открывании» проверяется только физически$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"пп. 23, 24, 25 раздела VII","quote_ru":"Информация... должна быть нанесена четкими, разборчивыми, несмываемыми... буквами; не должна печататься на прозрачной оберточной пленке, перекрываться другой печатной информацией и может частично пере"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.placement.and.overprint$txt$, $txt$eaeu.placement.stamp_not_on_front$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$integrity$txt$, $txt$integrity$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Перекрывает ли акцизная (учётно-контрольная) марка лицевую сторону пачки?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"акцизная/учётно-контрольная марка, заходящая на лицевую основную сторону упаковки"}$txt$::jsonb, $txt$Фронтальный кадр лицевой стороны + кадр верхнего торца$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.placement.and.overprint$txt$, $txt$eaeu.placement.not_on_film$txt$, 1, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Нанесена ли обязательная информация на прозрачную оберточную плёнку вместо самой пачки?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"печать обязательных сведений на целлофановой обёртке (кроме акцизной марки поверх плёнки)"}$txt$::jsonb, $txt$Сделать кадр со снятой плёнкой и с плёнкой — сравнить$txt$, null)
