insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.placement.and.overprint$txt$, $txt$eaeu.durability.legible$txt$, 2, $txt$text_semantic$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$integrity$txt$, $txt$integrity$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Читаются ли обязательные надписи на упаковке без размытия, затирания и разрывов печати?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":[],"expected_value":null,"language":["ru","uz"]}$txt$::jsonb, $txt$Оценивать только при резком кадре; смазанное фото — переснять, а не браковать пачку$txt$, null)
