insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.language.ru.plus.state$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: информация по п. 19 наносится на русском языке и на государственном языке государства-члена, где реализуется продукция (при наличии такого требования в его законодательстве)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО с checkable. Наличие русского текста определяется OCR и проверяется. Но вторая часть п. 26 — нанесение на государственный язык государства-члена «при наличии соответствующих требований в законодательстве государства-члена, в котором осуществляется реализация» — зависит от страны реализации, которая из фотографии пачки не следует. Полнота требования по фото не устанавливается.$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"п. 26 раздела VII","quote_ru":"информация о табачной продукции наносится на русском языке и на государственном (государственных) языке (языках) государства-члена при наличии соответствующих требований в его законодательстве"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.language.ru.plus.state$txt$, $txt$eaeu.language.ru_present$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Присутствуют ли обязательные сведения (изготовитель, количество, предупреждение) на русском языке?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["изготовитель","сигарет","штук","курение"],"expected_value":null,"language":["ru"]}$txt$::jsonb, $txt$Снять все грани; товарный знак на латинице нарушением не является$txt$, null)
