insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.eaeu.no.external.leaflet$txt$, null, $txt$tobacco$txt$, $txt$ЕАЭС: запрещено использование листов-вкладышей, размещённых ВНУТРИ потребительской упаковки, прикреплённых снаружи или приложенных к упаковке (кроме упаковок, на которые невозможно нанести информацию для потребителя, и поштучной реализации сигар и сигарилл)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО с checkable. Внешний вкладыш, буклет или купон видны на общем плане. Но п. 15 запрещает также листы-вкладыши, РАЗМЕЩЁННЫЕ ВНУТРИ потребительской упаковки, — по фото закрытой пачки они не видны. Чистый результат означает только отсутствие внешнего вкладыша.$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"п. 15 раздела V","quote_ru":"Не допускается использование при реализации табачной продукции листов-вкладышей, размещенных внутри потребительской упаковки табачной продукции, прикрепленных снаружи или приложенных к такой упаковке, за исключением потребительской упаковки, на которую невозможно нанести информацию для потребителя, а также при реализации сигар и сигарилл (сигарит) поштучно"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.eaeu.no.external.leaflet$txt$, $txt$eaeu.leaflet.external$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Прикреплён ли снаружи пачки лист-вкладыш, буклет, купон или рекламная наклейка?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"буклет, купон, промо-вкладыш, наклейка под плёнкой или поверх пачки"}$txt$::jsonb, $txt$Общий план пачки со всех сторон до вскрытия плёнки$txt$, null)
