insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.rf.datamatrix.chestny.znak$txt$, null, $txt$tobacco$txt$, $txt$РФ (ЕАЭС): на потребительскую упаковку нанесено средство идентификации — двумерный штриховой код DataMatrix («Честный знак»)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$наличие и декодирование DataMatrix по фото возможны, но валидность кода в ГИС МТ проверяется только запросом в систему$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"RF224","clause":"Правила маркировки табачной продукции средствами идентификации (утв. ПП РФ № 224), п. 37 и п. 40 подпункты «а», «в», «г» — проверено построчно 02.08.2026","quote_ru":"п. 37: «Средство идентификации потребительской упаковки предоставляется в виде двумерного штрихового кода в формате DataMatrix». п. 40: «а) ...применяется модуль размером не менее 0,254 миллиметра; в) ...коррекции ошибок... эквивалентна или выше, чем у DataMatrix ECC200; г) ...соответствует ГОСТ Р ИСО/МЭК 16022-2008»"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
