insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.packaging.material.and.mobius$txt$, null, $txt$tobacco$txt$, $txt$Упаковка (ТР ТС 005/2011): нанесены цифровой код и (или) буквенное обозначение материала упаковки (Приложение 3) и символ петли Мёбиуса (Приложение 4, рис. 2)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$код материала и петля Мёбиуса видны на фото, но ст. 6 п. 1 допускает их размещение в сопроводительной документации, а не на самой упаковке$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS005","clause":"ст. 6 п. 2 (Приложения 3 и 4)","quote_ru":"Маркировка должна содержать цифровой код и (или) буквенное обозначение (аббревиатуру) материала... в соответствии с Приложением 3 и должна содержать символы в соответствии с Приложением 4: ...рис. 2 —"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
