insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.uz.warning.area.65$txt$, null, $txt$tobacco$txt$, $txt$Узбекистан: медицинское предупреждение занимает не менее 65% основной площади в ВЕРХНЕЙ части передней стороны и не менее 65% основной площади задней стороны пачки$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Доля площади считается без абсолютного масштаба, но требуются фронтальные неискажённые кадры обеих основных сторон. По п. 47 ПКМ № 290 в зачёт 65% идёт СУММА площади изображения и площади, залитой Pantone 448C, — измерять надо весь блок предупреждения. Границы «основной площади» на фото размыты (фаски, шов крышки), поэтому расхождение в пределах ±5 п.п. — повод для ручного разбора, а не браковки.$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"UZ_ZRU844","clause":"ст. 36 ч. 3 (введена в действие с 26.05.2024 — ст. 45 Закона: девять месяцев со дня вступления Закона в силу 26.08.2023)","quote_ru":"медицинское предупреждение... занимающее не менее шестидесяти пяти процентов основной площади на передней стороне в верхней части и не менее шестидесяти пяти процентов на тыльной стороне"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
