insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.uz.warning.area.65$txt$, $txt$uz.warning.area_back$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$health_warning_block$txt$, null, $txt$area_fraction$txt$, $txt${"target":"health_warning_block","min_mm":null,"min_area_fraction":0.65,"surface":"back_panel","reference_scale":"доля от площади задней панели; нужна перспективная коррекция"}$txt$::jsonb, $txt$Отдельный фронтальный кадр задней стороны. ПОДТВЕРЖДЕНО по тексту ПКМ № 290 п. 45: спереди блок в ВЕРХНЕЙ части, сзади — в НИЖНЕЙ части основной площади.$txt$, null)
