insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.uz.warning.image.and.text$txt$, null, $txt$tobacco$txt$, $txt$Узбекистан: медицинское предупреждение выполнено в виде изображения, иллюстрирующего последствия заболевания от употребления табака, И текста соответствующего содержания, по утверждённым образцам (приложения к ТР)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$Наличие пиктограммы и текста детектируется. Соответствие конкретному образцу требует эталонного набора: по п. 47 ПКМ № 290 наборы образцов приведены в приложениях 5-8 к самому техрегламенту, по п. 54 состав обновляется не чаще раза в три года по образцам Минздрава РУз. Эталонной библиотеки изображений в системе нет.$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"UZ_PKM290","clause":"пп. 44, 45, 47 главы 5 §3","quote_ru":"(перевод с узб.) печатается медицинское предупреждение в виде изображения, показывающего последствия заболевания от употребления табака, и текста соответствующего содержания, по утверждённым образцам"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
