insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.uz.shelf.life$txt$, null, $txt$tobacco$txt$, $txt$Узбекистан: гарантийный срок хранения указывается для транспортной упаковки; для потребительской упаковки табачной продукции срок годности обязателен только для никотиновых и безникотиновых жидкостей (не более 3 лет)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$на пачке сигарет срок годности НЕ требуется — на фото проверяется лишь отсутствие ложного повода к браковке; для жидкостей проверяется наличие надписи$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"UZ_PKM290","clause":"п. 35 подпункт 12 и п. 36 главы 5 §2","quote_ru":"(перевод с узб.) гарантийный срок годности (для никотиновых и безникотиновых жидкостей), устанавливается изготовителем, но не более трёх лет; на транспортной упаковке — гарантийный срок хранения"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
