insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.uz.datamatrix.asl.belgisi$txt$, null, $txt$tobacco$txt$, $txt$Узбекистан: на потребительскую упаковку нанесено обязательное средство цифровой идентификации «Asl Belgisi» — двумерный код, читаемый терминалами, мобильными приложениями и сканерами НИС (формат GS1 DataMatrix задан не самим ТР, а правилами цифровой маркировки/оператором)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$присутствие и декодирование кода по фото возможны, но валидность/регистрация кода в НИС «Asl Belgisi» проверяется только запросом в систему$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"UZ_PKM290","clause":"п. 35 подпункт 13 главы 5 §2","quote_ru":"(перевод с узб.) для табачной продукции — обязательное средство цифровой идентификации (код маркировки) в виде двумерного кода, считываемого сканерами и приложениями национальной системы маркировки"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
