insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.uz.excise.stamp$txt$, null, $txt$tobacco$txt$, $txt$Узбекистан: производимая в РУз и ввозимая на её территорию табачная продукция подлежит обязательной маркировке акцизными марками установленного образца$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$наличие марки видно, подлинность и защитные признаки по обычному фото не проверяются$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"UZ_ZRU844","clause":"ст. 36 ч. 9 (последняя часть статьи)","quote_ru":"Производимая в Республике Узбекистан и ввозимая на ее территорию табачная продукция подлежит обязательной маркировке акцизными марками установленного образца."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
