insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.uz.language.state$txt$, null, $txt$tobacco$txt$, $txt$Узбекистан: информация на потребительской упаковке печатается на государственном языке и может быть повторена на других языках; словесное обозначение зарегистрированного товарного знака — на языке регистрации$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$язык обязательных надписей определяется OCR по кадрам всех граней пачки$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"UZ_PKM290","clause":"п. 43 главы 5 §2 (в связке со ст. 6 Закона «О защите прав потребителей»)","quote_ru":"(перевод с узб.) Сведения на потребительской упаковке печатаются на государственном языке и могут быть повторены на других языках; товарный знак применяется на языке его регистрации"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.uz.language.state$txt$, $txt$uz.language.state_present$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли обязательные сведения (вид продукции, изготовитель, количество) на государственном (узбекском) языке?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["sigareta","dona","ishlab chiqaruvchi","сигарета","ишлаб чиқарувчи"],"expected_value":null,"language":["uz"]}$txt$::jsonb, $txt$Учитывать латиницу и кириллицу узбекского; бренд на латинице нарушением не является$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.uz.prohibited.terms$txt$, null, $txt$tobacco$txt$, $txt$Узбекистан: ЗАПРЕЩЕНЫ слова «с низким содержанием смол», «лёгкие», «очень лёгкие», «мягкие», «экстра», «ультра», «тонкие», их однокоренные слова и иностранные аналоги, а также любые обозначения меньшего вреда$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО с checkable. Перечисленные слова читаются OCR, перечень в РУз шире, чем в ЕАЭС (добавлено «ингичка»/«тонкие»). Но норма запрещает также однокоренные слова, аналоги на иностранных языках и переводимые аналоги — открытый класс, конечным стоп-листом не покрываемый. Чистый результат означает «явных маркеров не найдено», а не соответствие требованию.$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"UZ_ZRU844","clause":"ст. 36 ч. 8 (абзацы первый и шестой) — ИСПРАВЛЕНО с «ч. 9»: по тексту Закона запреты составляют часть восьмую (ч. 9 — акцизные марки), что подтверждается ст. 45 («части третья — восьмая статьи 36»); дублируется п. 40 ПКМ № 290","quote_ru":"информации, вводящей потребителя в заблуждение относительно вредности табачной продукции, в том числе такие слова, как «с низким содержанием смол», «легкие», «очень легкие», «мягкие», «экстра», «ультр"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.consumer.uz.prohibited.terms$txt$, $txt$uz.prohibited.terms$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$composition$txt$, $txt$tar_nicotine_co$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на пачке слова «лёгкие», «light», «mild», «с низким содержанием смол», «мягкие», «тонкие», «slim» или их аналоги?$txt$, null, $txt${"forbidden_terms":["лёгкие","легкие","очень легкие","мягкие","с низким содержанием смол","экстра","ультра","тонкие","light","lights","mild","superlight","ultra","extra","slim","slims","low tar","yengil","juda yengil","yumshoq","qatron miqdori kam","ingichka","енгил","юмшоқ","ингичка"],"forbidden_imagery":null}$txt$::jsonb, $txt$Снять все грани; «slim/тонкие/ингичка» в РУз запрещены, в ЕАЭС в перечне п. 21 ТР ТС 035 их нет. Сопоставлять по границам слов, а не подстрокой: «extra»/«ultra»/«slim» внутри других слов и в составе товарного знака дают ложные срабатывания.$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.consumer.uz.prohibited.flavour.and.benefit$txt$, null, $txt$tobacco$txt$, $txt$Узбекистан: ЗАПРЕЩЕНЫ обозначения вкуса/запаха/ароматизаторов (или их отсутствия), изображения пищевых продуктов, лекарств и лекарственных растений, утверждения об экологичности и о стимулирующем, бодрящем, лечебном, омолаживающем или ином положительном эффекте$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$явные вкусовые слова и изображения детектируются, но «косвенное указание» на вкус или пользу — оценочное суждение$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"UZ_ZRU844","clause":"ст. 36 ч. 8 (абзацы второй-пятый) — ИСПРАВЛЕНО с «ч. 9»: запреты составляют часть восьмую ст. 36 (подтверждено ст. 45 Закона); дублируется п. 40 ПКМ № 290","quote_ru":"любых терминов... указывающих на вкус, запах, ароматизатор...; изображений пищевых продуктов, лекарственных средств, растений; информации о стимулирующем, лечебном, омолаживающем эффекте"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
