insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.trts022.marking.content$txt$, null, $txt$tobacco$txt$, $txt$Маркировка транспортной упаковки содержит наименование продукции, количество, дату изготовления, срок годности, условия хранения, идентификатор партии и данные изготовителя$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$все семь сведений п. 4.2 — печатные надписи на стенке короба. ИСПРАВЛЕНО ПРИ ВЕРИФИКАЦИИ: раньше здесь было сказано «читаемые с одного кадра», хотя проверок было только пять из семи; добавлены недостающие (срок годности, условия хранения), и оговорено, что нужен не один кадр, а серия: обзорный кадр стенки плюс макрокадры на мелкий шрифт адреса и на дату, которую наносят отдельным принтером мимо пе$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4, ч. 4.2, п. 1 (подп. 1–7); язык — ч. 4.2 п. 2. ОГОВОРКА: ТР ТС 022/2011 распространяется на ПИЩЕВУЮ продукцию (ст. 1 ч. 1); на табачную продукцию сам по себе не распространяется — приведён как эталонная модель требований к транспортной упаковке.","quote_ru":"«Маркировка транспортной упаковки… должна содержать сведения: 1) наименование; 2) количество; 3) дату изготовления; 4) срок годности; 5) условия хранения; 6) сведения о партии; 7) изготовителя»."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
