insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.trts022.exemption.visible.through.film$txt$, null, $txt$tobacco$txt$, $txt$Маркировку допускается не наносить на транспортную упаковку, если потребительская маркировка доводится до потребителя без нарушения целостности транспортной упаковки$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$по кадру видно, прозрачна ли плёнка и различима ли потребительская маркировка, но «доведение до сведения потребителя» — оценочная категория, которую фото не закрывает целиком$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS022","clause":"ст. 4, ч. 4.2, п. 3. ОГОВОРКА: область применения ТР ТС 022/2011 — пищевая продукция; на табак напрямую не распространяется.","quote_ru":"«…может быть доведена до сведения потребителей такой продукции без нарушения целостности транспортной упаковки, указанную маркировку допускается не наносить на транспортную упаковку»."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
