insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.trts035.scope.export.excluded$txt$, null, $txt$tobacco$txt$, $txt$ТР ТС 035/2014 не распространяется на табачную продукцию, поставляемую на экспорт за пределы таможенной территории Таможенного союза$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$статус партии как экспортной определяется внешнеторговым договором и таможенными документами, а не внешним видом короба$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"разд. I, п. 2, подп. «в»; сверено при верификации 02.08.2026","quote_ru":"«Действие настоящего технического регламента не распространяется на следующую табачную продукцию: … в) табачная продукция, которая поставляется на экспорт по внешнеторговым договорам за пределы таможенной территории Таможенного союза». УТОЧНЕНО: в норме есть квалификатор «по внешнеторговым договорам», ранее пропущенный многоточием."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.trts035.no.health.warning.on.transport.pack$txt$, null, $txt$tobacco$txt$, $txt$Предупреждение о вреде потребления табака требуется на потребительской упаковке (листе-вкладыше); нанесение его на транспортный короб регламентом не предписано$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ ВЕРИФИКАЦИИ с checkable. По кадру фиксируется только факт наличия предупредительного блока, причём для этого короб надо вскрыть и разложить пачки лицевой стороной. Соблюдение самой нормы этим не доказывается: п. 29 задаёт долю площади (не менее 50 % лицевой и обратной сторон) и язык каждой стороны, п. 30 — дополнительное предупреждение на боковой поверхности; доля площади требует полн$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"разд. VII, п. 27; область применения — разд. I п. 3 («требования к … информации (маркировке), наносимой на потребительскую упаковку»). ФАКТ ПО ТЕКСТУ: терминов «групповая упаковка» и «блок» в регламенте НЕТ, «транспорт» — только в п. 23. Требований к транспортному коробу регламент не устанавливает. ДОБАВЛЕНО ПРИ ВЕРИФИКАЦИИ: само предупреждение нормируется не только по факту наличия — п. 29 требует основное предупреждение на верхних частях лицевой и обратной сторон потребительской упаковки площадью не менее 50 % каждой из этих сторон, п. 30 — дополнительное предупреждение на боковой поверхности. Доля площади по фотографии не проверяется (нужны полная развёртка пачки и масштаб), поэтому проверка наличия предупреждения НЕ равна проверке соблюдения п.п. 27, 29, 30.","quote_ru":"«На каждую потребительскую упаковку табачной продукции (лист-вкладыш) наносится предупреждение о вреде потребления табачных изделий»."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.trts035.no.health.warning.on.transport.pack$txt$, $txt$trts035.warning_on_consumer_pack$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$warnings$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$health_warning_block$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снять вскрытый короб так, чтобы была видна лицевая сторона пачек/блоков внутри. Проверяется ТОЛЬКО наличие блока: доля площади (п. 29) и соответствие эскизу (п. 28) по этому кадру не оцениваются$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.tobacco.trts035.block.as.consumer.pack$txt$, null, $txt$tobacco$txt$, $txt$Блок сигарет, реализуемый конечному потребителю, подпадает под определение потребительской упаковки — на него распространяются требования к информации и предупреждению о вреде$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$по фото видно, есть ли на блоке предупреждение и знак EAC, но нельзя установить, продаётся ли блок конечному потребителю или служит только групповой тарой$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"TRTS035","clause":"разд. II п. 4 (определение) во взаимосвязи с разд. VII п. 19 и п. 27. Прямой квалификации блока в тексте нет — «не установлен точно»; вывод сделан из определения потребительской упаковки. ДОБАВЛЕНО ПРИ ВЕРИФИКАЦИИ: знак EAC — разд. XI п. 46 («наносится на потребительскую упаковку (лист-вкладыш) любым способом, обеспечивающим его четкое и ясное изображение»); минимальный размер знака ТР ТС 035/2014 не устанавливает, и в этом файле он намеренно не заявлен. Запрет обозначений, создающих впечатление меньшей вредности, — п.п. 20–21. Если партия чисто экспортная за пределы таможенной территории, регламент к ней не применяется вовсе (п. 2 подп. «в»), и отсутствие EAC на блоке дефектом не является.","quote_ru":"«„потребительская упаковка“ — упаковка, предназначенная для продажи или первичной упаковки продукции, реализуемой конечному потребителю». Слово «блок» в регламенте отсутствует."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
