insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.tobacco.trts035.block.as.consumer.pack$txt$, $txt$trts035.block_no_misleading_terms$txt$, 2, $txt$absence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$composition$txt$, $txt$tar_nicotine_co$txt$, $txt$both$txt$::public.photo_packaging_level, null, $txt$Есть ли на блоке слова или обозначения, создающие впечатление меньшей вредности («лёгкие», «light», «mild», «с низким содержанием смол»)?$txt$, null, $txt${"forbidden_terms":["лёгкие","легкие","light","lights","mild","superlight","ultra light","с низким содержанием смол","yengil"],"forbidden_imagery":"образы, внушающие меньший риск заболеваний или меньшую опасность по сравнению с другими табачными изделиями"}$txt$::jsonb, $txt$Проверять все грани блока, включая торцы и клапаны$txt$, null)
