insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.gost14192.handling.marks.two.adjacent.walls$txt$, null, $txt$tobacco$txt$, $txt$Манипуляционные знаки наносят на каждое грузовое место в левом верхнем углу на двух соседних стенках тары$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$на одном кадре видна лишь одна стенка; для проверки «двух соседних стенок» и «каждого грузового места» нужны кадр под углом 45° и съёмка всей партии$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"GOST14192","clause":"п. 5.5 (место нанесения), п. 5.12 (на каждое грузовое место)","quote_ru":"«Манипуляционные знаки (предупредительные надписи) наносят на каждое грузовое место в левом верхнем углу на двух соседних стенках тары» (5.5)."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
