insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.gost14192.inscriptions.placement.on.box$txt$, null, $txt$tobacco$txt$, $txt$На ящиках основные, дополнительные и информационные надписи располагают на одной из боковых сторон$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ ВЕРИФИКАЦИИ с checkable по двум причинам. Первая: чтобы сказать «надписи на БОКОВОЙ стенке», надо отличить боковую грань от торцовой, а по одному кадру грани неразличимы без габаритов короба или кадра всего короба с известной ориентацией. Вторая: для экспортных грузов норма другая (п. 7.11 — торцовая И боковая стенки), и её соблюдение проверяется только серией кадров разных граней$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"GOST14192","clause":"п. 5.3. ВАЖНО ПРИ ЭКСПОРТЕ: для грузов, поставляемых на экспорт, действует п. 7.11 — «На ящиках или другой таре, имеющей форму параллелепипеда, маркировку наносят на торцовую и боковую стенки», а при нехватке места — на торцовую, боковую и крышку. То есть для экспортной партии одной боковой стенки уже недостаточно.","quote_ru":"«Основные, дополнительные и информационные надписи располагают: на ящиках — на одной из боковых сторон» (5.3). Для экспорта: «маркировку наносят на торцовую и боковую стенки» (7.11)."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.transport.gost14192.inscriptions.placement.on.box$txt$, $txt$gost.inscriptions_on_side_wall$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$geometry$txt$, $txt$other:check$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$text_block_main_inscriptions$txt$, null, $txt$position$txt$, $txt${"target":"text_block_main_inscriptions","min_mm":null,"min_area_fraction":null,"surface":"side_wall","reference_scale":"габарит короба из спецификации — без него боковая и торцовая грани по кадру не различаются","expected_position":"боковая стенка (п. 5.3); для экспортных грузов — торцовая и боковая (п. 7.11), допустимо добавление крышки при нехватке места"}$txt$::jsonb, $txt$Обзорный кадр короба целиком с одной из боковых сторон; для экспортной партии дополнительно кадр торцовой стенки$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.gost14192.sizes.and.contrast$txt$, null, $txt$tobacco$txt$, $txt$Размеры ярлыков, знаков и высота шрифта соответствуют ГОСТ; знаки и надписи тёмного цвета на светлых поверхностях и светлого — на тёмных$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$контраст определяется по кадру напрямую, но абсолютные размеры в мм требуют масштабной привязки — без линейки или известного габарита короба высота шрифта не измеряется. ИСПРАВЛЕНО ПРИ ВЕРИФИКАЦИИ: раньше проверка размера ярлыка требовала «не менее 52 мм» — это подмена нормы. 52 мм — короткая сторона ярлыка № 1 из табл. 2, а табл. 2 нормирует ярлыки для манипуляционных знаков, названа рекомендуемо$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"GOST14192","clause":"п. 6.1 (площадь ярлыка), п. 6.2 и табл. 2 (рекомендуемые размеры ярлыков ДЛЯ МАНИПУЛЯЦИОННЫХ ЗНАКОВ), п. 6.4, п. 6.7 (высота шрифта основных надписей — рекомендуемая), п. 6.8 (дополнительные и информационные — рекомендуемая); контраст — п. 5.10","quote_ru":"«Площадь маркировочного ярлыка для нанесения основных, дополнительных и информационных надписей должна быть не менее 60 см2. Рекомендуемое соотношение сторон 2 : 3» (6.1). «На ярлыках, изготовленных типографским способом, знак должен быть на расстоянии не менее 5 мм от края ярлыка» (6.4). «Манипуляционные знаки и надписи должны быть темного цвета на светлых поверхностях и светлого на темных» (5.10"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.transport.gost14192.sizes.and.contrast$txt$, $txt$gost.contrast_dark_on_light$txt$, 0, $txt$geometry$txt$::public.photo_check_kind, $txt$minor$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$handling_mark:any$txt$, null, $txt$contrast_ratio$txt$, $txt${"target":"handling_mark:any","min_mm":null,"min_area_fraction":null,"surface":"side_wall","reference_scale":"не требуется — контраст оценивается по яркости пикселей знака и фона","min_contrast_ratio":3}$txt$::jsonb, $txt$Снимать при равномерном освещении без бликов и цветных источников$txt$, null)
