insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.transport.gost14192.sizes.and.contrast$txt$, $txt$gost.label_min_size$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, $txt$marking_label$txt$, null, $txt$min_size_mm$txt$, $txt${"target":"marking_label","min_mm":null,"min_area_fraction":null,"surface":"side_wall","reference_scale":"ОБЯЗАТЕЛЬНО линейка в кадре или указанный габарит короба. Норма п. 6.1 задана ПЛОЩАДЬЮ (не менее 60 см² при соотношении сторон 2:3), а не длиной стороны, поэтому порогового значения в мм здесь нет: min_mm снят при верификации как подменённая величина"}$txt$::jsonb, $txt$Без масштабной привязки результат не засчитывать: помечать как «нет масштаба». Ярлык меньше 60 см² — повод показать человеку, а не автоматический дефект: ГОСТ добровольного применения$txt$, null)
