insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.gost14192.export.additional.inscriptions$txt$, null, $txt$tobacco$txt$, $txt$Для грузов, поставляемых на экспорт, наносят дополнительные надписи (номер контракта, иностранный грузополучатель, страна назначения, «Экспорт», страна-изготовитель), а знаки № 1 и № 11 — в левом верхнем углу с четырёх сторон$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$надписи и знаки читаются с кадра, но требование «с четырёх сторон» и «на каждое грузовое место» проверяется только серией кадров всех граней$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"GOST14192","clause":"разд. 7: п. 7.2 (основные), 7.4 (информационные), 7.6, 7.8","quote_ru":"Основные надписи — номер контракта, иностранный грузополучатель, страна назначения (7.2); надписи «Экспорт», «Страна-изготовитель» (7.4); «Знаки № 1 и 11 наносят… с четырех сторон» (7.8)."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
