insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.gs1.case.barcode.gtin14.ai.hri$txt$, null, $txt$tobacco$txt$, $txt$На уровне короба нанесён штрихкод ITF-14 или GS1-128, кодирующий GTIN-14, с человекочитаемой подписью (HRI); в GS1-128 идентификаторы применения выделяются скобками только в HRI$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ ВЕРИФИКАЦИИ с checkable. Наличие символа, его тип и наличие HRI-подписи действительно видны на кадре, и контрольная цифра GTIN считается по цифрам HRI. Но две проверки из четырёх требуют УСПЕШНОГО ДЕКОДИРОВАНИЯ самого символа — сверка HRI с закодированной строкой невозможна без него, — а прямая печать по гофре при допустимом уменьшении до 70 % часто не декодируется по фотографии. Если$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"GS1_BARCODE_BASICS","clause":"разд. 5.1.1 (ITF-14) и 5.1.2 (GS1-128); значения AI — GS1_AI и GS1_ITF14","quote_ru":"ITF-14 «generally used on higher packaging levels… such as cases or cartons», кодирует GTIN в 14-значном формате. GS1-128 несёт AI: (01) GTIN, (10) lot/batch, (17) срок годности."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
