insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.gs1.sscc.logistic.label$txt$, null, $txt$tobacco$txt$, $txt$Каждая логистическая единица идентифицируется 18-значным SSCC с AI (00) на логистической этикетке GS1-128; две одинаковые этикетки на смежных сторонах паллеты — рекомендация, а не обязательное правило$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$наличие этикетки, AI (00), 18 цифр и ориентация штрихов проверяются по кадру; уникальность SSCC и запрет переиспользования в течение года — свойства базы данных, а не изображения$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"GS1_SSCC","clause":"GS1 Logistic Label Fact Sheet: Assigning SSCC; Barcode Symbol Specifications; Height of Bars; Recommendation to Include a Barcode on Two Sides; Label Location — Cartons and Outer Cases. РАЗГРАНИЧЕНИЕ ПРИ ВЕРИФИКАЦИИ: обязательным источник называет ровно одно — «The one mandatory requirement is that each logistic unit must be identified with a unique serial number, the SSCC». Две этикетки на смежных сторонах паллеты — «it is recommended», рекомендация. Размещение на коробах задано как «exactly 32mm from the base», то есть точное значение, а не минимум.","quote_ru":"«The one mandatory requirement is that each logistic unit must be identified with a unique serial number, the Serial Shipping Container Code (SSCC)». «The minimum bar height for the GS1-128 barcode symbols on a logistic label is 32mm». «For pallets, it is recommended that two identical logistic labels are placed on adjacent sides»."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
