insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.markuz.group.pack.digital.id$txt$, null, $txt$tobacco$txt$, $txt$Цифровая идентификация обязательна для табачной продукции РУз (ПКМ № 737, система «Asl belgisi»); формат кода (GS1 DataMatrix) и требование неотделяемости носителя взяты из отраслевой практики и порядком РУз в рамках этого исследования НЕ подтверждены$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ ВЕРИФИКАЦИИ с checkable. По кадру определяется наличие двумерного кода и его контраст — этого достаточно, чтобы поймать «кода нет» и «код нечитаем». Дальше фото не идёт: (а) неотделяемость носителя доказывается попыткой снять стикер, а на снимке виден только уже отошедший край — отсутствие видимого задира ничего не доказывает; (б) сам факт считываемости — это результат декодирования, $txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"UZ_PKM737","clause":"не установлен точно. Сверено при верификации 02.08.2026: ПКМ КМ РУз от 20.11.2020 № 737 «О введении системы обязательной цифровой маркировки отдельных видов товаров» подтверждён — п. 5 устанавливает обязанности производителей, импортёров и торговых предприятий, включая подключение к национальной системе «Asl belgisi»; п. 4 поручает ГНК внести на утверждение отдельные порядки маркировки табачной и алкогольной продукции. Ни формата кода (GS1 DataMatrix), ни требования «способом, не допускающим отделения от упаковки», ни правил агрегации сам текст ПКМ № 737 не содержит — эти положения могут быть только в отдельном порядке, который здесь не читался.","quote_ru":"ПКМ РУз № 737 вводит обязательную цифровую маркировку табачной продукции и систему «Asl belgisi» (п. 5). Теххарактеристики кода вынесены в отдельный порядок (п. 4) и здесь не верифицированы — формат и неотделяемость носителя приведены как отраслевая практика, а не как процитированная норма."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
