insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.mark.group.code.structure.and.aggregation$txt$, null, $txt$tobacco$txt$, $txt$Код групповой упаковки формируется в GS1 DataMatrix из групп AI (01), (21), (8005), (93); при агрегации сохраняется связь кодов вложенных потребительских упаковок с кодом групповой упаковки$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$структуру AI можно проверить, декодировав код с кадра, но сама агрегация — запись о связи кодов в информационной системе, которой на фотографии нет. ИСПРАВЛЕНО ПРИ ВЕРИФИКАЦИИ: отсюда удалена проверка mark.aggregation_link_in_system (presence «aggregation_record», severity critical) — она требовала выгрузки из «Asl belgisi»/ГИС МТ и по фотографии не выполнима в принципе; в чек-листе фотоконтроля е$txt$, array[$txt$EAEU$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"RU_FTS_CODE","clause":"«Структура кода маркировки табачной продукции», раздел «Код групповой упаковки». ОГОВОРКА: юрисдикция — РФ (ГИС МТ «Честный ЗНАК»); для Узбекистана эта структура источниками не подтверждена. Код транспортной упаковки в документе ФТС отсутствует.","quote_ru":"Код групповой упаковки — GS1-DataMatrix из 4 групп: AI (01) код товара, (21) серийный номер, (8005) сумма МРЦ вложенных пачек, (93) код проверки. Источник — ФТС России; для РУз не подтверждено."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
