insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$tobacco.transport.psi.carton.integrity.and.seal$txt$, null, $txt$tobacco$txt$, $txt$Короб целый (без смятия, разрывов, следов влаги) и заклеен лентой указанного типа и в указанное число полос — требование инспекционного чек-листа, а не нормы права$txt$, $txt$partial$txt$::public.photo_checkability, $txt$transport$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ ВЕРИФИКАЦИИ с checkable. Смятие, разрывы, влажные пятна, отслоение и следы повторной заклейки — именно те дефекты, которые фиксируются визуально, и это ядро фотоконтроля. Но требование сформулировано как «лентой УКАЗАННОГО ТИПА и в УКАЗАННОЕ ЧИСЛО ПОЛОС», а тип ленты и предписанное число полос заданы спецификацией покупателя, которой на фотографии нет: без неё по кадру видно только фа$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"PSI_PRACTICE","clause":"не применимо — отраслевая практика PSI, нормативный пункт отсутствует","quote_ru":"ЭТО НЕ НОРМА. Практика PSI: проверка коробов на деформацию, влагу, смятие, отслоение ленты; заклейка по спецификации покупателя. Обязательность — только из договора. AQL: critical 0%, major 2,5%."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
