insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$tobacco.transport.psi.carton.integrity.and.seal$txt$, $txt$psi.tape_not_lifting$txt$, 3, $txt$absence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$transport$txt$::public.photo_packaging_level, null, $txt$Отходит ли лента от картона — есть ли пузыри, задиры, незаклеенные участки шва, следы вскрытия и повторной заклейки?$txt$, null, $txt${"forbidden_terms":[],"forbidden_imagery":"приподнятые края ленты, пузыри воздуха, разрыв ленты, вторая полоса ленты поверх первой как признак вскрытия"}$txt$::jsonb, $txt$Отслоение ленты и следы повторной заклейки — признак несанкционированного вскрытия: снимать шов вдоль, крупно$txt$, null)
