insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.consumer.info.in.state.language$txt$, null, $txt$uzbekistan$txt$, $txt$Информация о товаре доводится до потребителя на государственном (узбекском) языке; другие языки допускаются только дополнительно$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ РЕВИЗИИ с checkable. Три причины: (1) по ч. 1 ст. 6 информация правомерно может доводиться технической документацией «или иным способом» — отсутствие узбекского текста на упаковке само по себе нарушения не доказывает; (2) норма требует, чтобы на госязыке была ВСЯ обязательная информация по ч. 2 ст. 6, а это проверяется только по полной развёртке всех панелей, а не по факту наличия отд$txt$, array[$txt$UZ$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"ZRU746","clause":"ст. 6 Закона «О защите прав потребителей» — часть о государственном языке (введена ЗРУ-746 как часть третья; после дополнения ст. 6 новой частью третьей Законом ЗРУ-1046 от 11.03.2025 актуальный номер части не установлен точно)","quote_ru":"Сверено дословно по lex.uz 02.08.2026: «Информация о товаре (работе, услуге) предоставляется потребителю на государственном языке. Данная информация может быть дополнительно предоставлена и на других языках.» Параллельная норма — ст. 5, часть пятая: «Информация об изготовителе (исполнителе, продавце), правилах торговли и обслуживания предоставляется потребителю на государственном языке. Данная инф"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.consumer.info.in.state.language$txt$, $txt$uz.lang.uz_text_present$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$dates_batch$txt$, $txt$batch_number$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на упаковке потребительская информация о товаре на узбекском языке (латиница или кириллица)?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["mahsulot","ishlab chiqaruvchi","tarkibi","yaroqlilik muddati","saqlash sharoiti","ишлаб чиқарувчи","таркиби","яроқлилик муддати"],"expected_value":null,"language":["uz"]}$txt$::jsonb, $txt$Снимите все стороны упаковки, включая наклеенный стикер-перевод — текст на госязыке часто вынесен именно на стикер$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.consumer.manufacturer.and.importer.identified$txt$, null, $txt$uzbekistan$txt$, $txt$Указаны полное наименование и местонахождение (юридический адрес) изготовителя, а для импортируемых товаров — изготовителя и импортёра$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ РЕВИЗИИ с checkable. Текст наименования и адреса действительно читается на фото, но: (1) по ч. 1 ст. 6 сведения могут правомерно находиться в технической документации, а не на упаковке; (2) вторая половина нормы (реквизиты импортёра) применяется только к импортируемым товарам, а импортный статус по фотографии упаковки не устанавливается; (3) по снимку нельзя проверить, что указанный а$txt$, array[$txt$UZ$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"ZRU746","clause":"ст. 6, часть вторая, абзац десятый Закона «О защите прав потребителей» (в редакции ЗРУ-746)","quote_ru":"Сверено дословно по lex.uz 02.08.2026: «полное наименование и местонахождение (юридический адрес) изготовителя (исполнителя, продавца), QR-код (матричный штрих код) лицензий и документов разрешительного характера, а для импортируемых товаров — наименование и местонахождение (юридический адрес) изготовителя и импортера». ИСПРАВЛЕНО: ранее ссылка давалась как «п. 2 перечня» — в законе это абзац деся"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.consumer.manufacturer.and.importer.identified$txt$, $txt$uz.mfr.name_address$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Указаны ли на упаковке полное наименование изготовителя и его юридический адрес (местонахождение)?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["ishlab chiqaruvchi","manzil","изготовитель","производитель","адрес","MChJ","ООО"],"expected_value":null,"language":["uz","ru"]}$txt$::jsonb, $txt$Ищите блок мелким шрифтом на боковой или задней панели$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.consumer.manufacturer.and.importer.identified$txt$, $txt$uz.importer.name_address$txt$, 1, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$manufacturer_address$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Если товар импортный — указаны ли наименование и юридический адрес импортёра в Узбекистане?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["import qiluvchi","importyor","импортёр","импортер","O'zbekiston","Toshkent","Ташкент"],"expected_value":null,"language":["uz","ru"]}$txt$::jsonb, $txt$Проверьте стикер: реквизиты импортёра почти всегда на нём$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.consumer.country.of.origin$txt$, null, $txt$uzbekistan$txt$, $txt$Указано наименование страны происхождения товара$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ РЕВИЗИИ с checkable. Сама строка на фото читается надёжно, но по ч. 1 ст. 6 сведения могут доводиться и технической документацией, поэтому отсутствие строки на упаковке нарушения не доказывает; кроме того, закон требует НАИМЕНОВАНИЕ СТРАНЫ, и надписи вида «Made in EU», «Произведено в ЕАЭС» или только адрес завода этому не удовлетворяют — различение требует смысловой оценки, а не прост$txt$, array[$txt$UZ$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"ZRU746","clause":"ст. 6, часть вторая, абзац одиннадцатый Закона «О защите прав потребителей» (абзац введён ЗРУ-746)","quote_ru":"Сверено дословно по lex.uz 02.08.2026: «наименование страны происхождения товара». ИСПРАВЛЕНО: ранее ссылка давалась как «п. 3 перечня» — в законе это абзац одиннадцатый части второй ст. 6."}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.consumer.country.of.origin$txt$, $txt$uz.origin.country$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$country_of_origin$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Указана ли на упаковке страна происхождения товара?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["ishlab chiqarilgan mamlakat","kelib chiqish mamlakati","страна происхождения","сделано в","Made in"],"expected_value":null,"language":["uz","ru","en"]}$txt$::jsonb, $txt$Может быть указана как «Made in ...» — этого достаточно только если продублировано на госязыке$txt$, null)
