insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.consumer.qr.licenses$txt$, null, $txt$uzbekistan$txt$, $txt$В информации об изготовителе (продавце) присутствует QR-код (матричный штрих-код) лицензий и документов разрешительного характера$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$наличие QR-кода на фото определяется, но что именно он кодирует (лицензии и разрешительные документы, а не сайт бренда, промо-акцию или ссылку на состав), без декодирования и проверки ссылки не установить; кроме того, по ч. 1 ст. 6 сведения могут доводиться «иным способом», а на практике этот QR-код чаще размещается в месте продажи, чем на каждой единице товара$txt$, array[$txt$UZ$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"ZRU746","clause":"ст. 6, часть вторая, абзац десятый Закона «О защите прав потребителей» (в редакции ЗРУ-746) — тот же абзац, что и реквизиты изготовителя","quote_ru":"Сверено дословно по lex.uz 02.08.2026: «полное наименование и местонахождение (юридический адрес) изготовителя (исполнителя, продавца), QR-код (матричный штрих код) лицензий и документов разрешительного характера, а для импортируемых товаров — наименование и местонахождение (юридический адрес) изготовителя и импортера». ИСПРАВЛЕНО: ранее ссылка давалась как «п. 2 перечня»; требование о QR-коде не "}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
