insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.consumer.marking.legible$txt$, null, $txt$uzbekistan$txt$, $txt$Маркировка нанесена чётко и легко читаема, надписи контрастны фону$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$контраст текста к фону измеряется по фото, но «легко читаемо» — оценочная категория, зависящая от кегля и условий съёмки$txt$, array[$txt$UZ$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"ZRU_ZPP","clause":"не установлен точно","quote_ru":"Действующего требования именно о КОНТРАСТНОСТИ и лёгкой читаемости маркировки в проверенных первичных текстах НЕ НАЙДЕНО. Ближайшая действующая опора — ст. 6, часть первая Закона «О защите прав потребителей» (сверено дословно 02.08.2026): «Изготовитель (исполнитель, продавец) обязан своевременно предоставлять потребителю необходимую, достоверную и ДОСТУПНУЮ информацию о реализуемых им товарах (раб"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
