insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.import.marking.state.language.sticker$txt$, null, $txt$uzbekistan$txt$, $txt$Импортируемые потребительские товары ИЗ ПЕРЕЧНЯ приложения № 1 к ПКМ № 127/2013, имеющие потребительскую упаковку и поступающие в розницу, маркируются на государственном языке (этикетка/стикер/лейбл)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$наличие стикера с переводом на госязык видно на фото, НО применимость нормы к конкретному товару по снимку не определяется: она зависит от попадания товара в перечень приложения № 1 к ПКМ № 127 от 13.05.2013 (перечень по коду ТН ВЭД, не выгружен) и от изъятий п. 4 Правил (ввоз для собственных нужд, дипломатический, выставочные образцы). ПЕРЕСМОТРЕНО ПРИ РЕВИЗИИ: прежнее обоснование ссылалось на пр$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"PKM22_2014","clause":"приложение № 1 к постановлению (Правила), п. 3 и п. 7 — ИСПРАВЛЕНО: нумерация относится к Правилам, а не к пунктам самого постановления","quote_ru":"Сверено дословно по lex.uz 02.08.2026. П. 3 Правил (в редакции ПКМ № 407 от 21.08.2023): «Обязательному маркированию на государственном языке, проставляемому изготовителем, уполномоченными лицами изготовителя и импортером, подлежат товары, ВКЛЮЧЁННЫЕ В ПРИЛОЖЕНИЕ № 1 к постановлению Кабинета Министров Республики Узбекистан от 13 мая 2013 г. № 127 <…> и имеющие потребительскую упаковку, являющуюся "}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
