insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.import.sticker.not.covering.original$txt$, null, $txt$uzbekistan$txt$, $txt$Запрещено наклеивать стикер поверх оригинальной маркировки изготовителя так, что это препятствует сверке сведений$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$перекрытие оригинальной маркировки стикером иногда видно (обрезанный текст, край стикера поверх блока состава), но доказать перекрытие можно только сравнив с непроклеенным образцом или отклеив стикер$txt$, array[$txt$UZ$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"PKM22_2014","clause":"приложение № 1 к постановлению (Правила), п. 8, абзац третий","quote_ru":"Сверено дословно по lex.uz 02.08.2026. П. 8: «Не допускается: внесение дополнительной информации на маркировке на государственном языке, которая не существует на маркировке предприятия-изготовителя на других языках; маркирование товара на государственном языке способом наклеивания стикера на упаковку товара поверх маркировок, проставленных предприятиями-изготовителями, не позволяющим провести анал"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
