insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.digital.datamatrix.on.consumer.pack$txt$, null, $txt$uzbekistan$txt$, $txt$На потребительскую упаковку товаров подконтрольных групп нанесено средство идентификации в формате Data Matrix (система «Asl Belgisi»)$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ РЕВИЗИИ с checkable. Само наличие двумерного кода детектируется надёжно, но соответствие норме по фото не доказывается: (1) Data Matrix на упаковке сплошь и рядом является технологическим (партия, дата, внутренняя логистика), а средством идентификации «Asl Belgisi» его делает структура GS1 (GTIN + серийный номер + криптохвост) — а это устанавливается только декодированием кода и сверк$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"SOLIQ_DIGITAL","clause":"официальное разъяснение Налогового комитета; базовый акт — ПКМ № 737 от 20.11.2020, п. 5","quote_ru":"«Цифровая маркировка — процесс нанесения на потребительскую упаковку отдельных видов товаров средств идентификации (Data Matrix)». Даты введения по группам: табачная и алкогольная продукция — с 01.01.2021; пивоваренная продукция — с 01.04.2021; бытовая техника — с 15.04.2022; лекарственные средства и медицинские изделия — с 01.09.2022; вода и прохладительные напитки — с 01.03.2024. ПКМ № 737, п. 5"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
