insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.digital.datamatrix.on.consumer.pack$txt$, $txt$uz.aslbelgisi.datamatrix_decodable$txt$, 1, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$codes$txt$, $txt$barcode_any$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$decodable_barcode$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Снимите код перпендикулярно, крупно и в фокусе, чтобы он поддавался декодированию: только по раскодированной структуре (GTIN + серийный номер + криптохвост) можно отличить средство идентификации «Asl Belgisi» от технологического Data Matrix$txt$, null)
