insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.digital.code.on.pack.not.on.removable.film$txt$, null, $txt$uzbekistan$txt$, $txt$Код маркировки нанесён непосредственно на упаковку (не на съёмную плёнку/обёртку) и сохраняется читаемым в течение срока годности$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$по фото видно, напечатан ли код на самой упаковке или на прозрачной плёнке, но сохранность кода на весь срок годности проверке по одному снимку не поддаётся$txt$, array[$txt$UZ$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"PKM737","clause":"не установлен точно","quote_ru":"Требование получено из справочного центра оператора системы (help.crpt-turon.uz, «Marking Requirement: GS1 DataMatrix»): код наносится на упаковку в специально отведённом месте, должен сохраняться в течение всего срока годности товара и не должен печататься на внешнем съёмном упаковочном материале (прозрачная плёнка, пластиковая обёртка). Прямой доступ к странице оператора при исследовании вернул "}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
