insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.excise.tobacco.stamp.placement$txt$, null, $txt$uzbekistan$txt$, $txt$Пачка табачных изделий оклеена акцизной маркой РУз в установленном месте так, что марка повреждается при вскрытии$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$наличие марки и место её наклейки на фото проверяются, но: (1) подлинность акцизной марки (защитные элементы, сверка серии и номера с базой) по фотографии не устанавливается; (2) сами правила размещения взяты из акта, утратившего силу 01.11.2024, и в действующей инструкции могли измениться — проверку места наклейки следует считать ориентировочной до сверки с рег. МЮ № 3566$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"ZRU844","clause":"ст. 36, часть девятая (обязанность маркировки); конкретные правила РАЗМЕЩЕНИЯ марки — не установлен точно","quote_ru":"Обязанность сверена дословно по lex.uz 02.08.2026, ЗРУ-844, ст. 36, часть девятая: «Производимая в Республике Узбекистан и ввозимая на ее территорию табачная продукция подлежит обязательной маркировке акцизными марками установленного образца». ПРАВИЛА РАЗМЕЩЕНИЯ: ранее файл ссылался на «ПКМ № 589 от 07.01.1999, п. 3, 18, 21» — это ошибка сразу в двух отношениях: акт является не постановлением КМ, "}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
