insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.excise.alcohol.stamp.on.cap$txt$, null, $txt$uzbekistan$txt$, $txt$Бутылка алкогольного напитка (кроме натуральных и игристых вин, пива и пивных напитков) оклеена акцизной маркой РУз на укупорочном колпачке горловины так, что марка разрывается при вскрытии$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$марка на колпачке видна на фото, но: (1) подлинность марки и целостность защитных элементов по снимку не проверяются; (2) применимость требования зависит от вида напитка — натуральные и игристые вина, пиво и пивные напитки акцизными марками не маркируются, а отнесение напитка к «натуральному вину» по этикетке устанавливается лишь предположительно; (3) правила наклейки взяты из акта, утратившего си$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2208$txt$]::text[], $txt${"act_id":"ZRU844","clause":"ст. 31, часть пятая (в редакции Закона ЗРУ-1034 от 20.02.2025) — обязанность и круг изъятий; правила НАКЛЕЙКИ — не установлен точно","quote_ru":"Обязанность сверена дословно по lex.uz 02.08.2026, ЗРУ-844, ст. 31, часть пятая: «Производимая в Республике Узбекистан и ввозимая на ее территорию алкогольная продукция (ЗА ИСКЛЮЧЕНИЕМ НАТУРАЛЬНЫХ И ИГРИСТЫХ ВИН, ПИВА И ПИВНЫХ НАПИТКОВ) подлежит обязательной маркировке акцизными марками установленного образца». СУЩЕСТВЕННОЕ ИСПРАВЛЕНИЕ: прежняя редакция файла знала только изъятие для пива (по утра"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
