insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.excise.beer.exempt$txt$, null, $txt$uzbekistan$txt$, $txt$Пиво и пивные напитки, а также натуральные и игристые вина не подлежат маркировке акцизными марками (пивоваренная продукция при этом подлежит цифровой маркировке Data Matrix с 01.04.2021)$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$разрешительная (исключающая) норма: отсутствие акцизной марки на пиве, пивном напитке, натуральном или игристом вине нарушения не образует, проверять на фото нечего — правило нужно исключительно для подавления ложных срабатываний детектора акцизных марок$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2208$txt$]::text[], $txt${"act_id":"ZRU844","clause":"ст. 31, часть пятая (в редакции Закона ЗРУ-1034 от 20.02.2025)","quote_ru":"Сверено дословно по lex.uz 02.08.2026: «Производимая в Республике Узбекистан и ввозимая на ее территорию алкогольная продукция (за исключением натуральных и игристых вин, пива и пивных напитков) подлежит обязательной маркировке акцизными марками установленного образца». РАСШИРЕНО ПРИ РЕВИЗИИ: прежняя редакция файла опиралась на п. 3 и п. 19 инструкции рег. № 589 («кроме пива»; «Пиво, производимое "}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.tobacco.health.warning.image.and.area$txt$, null, $txt$uzbekistan$txt$, $txt$Потребительская пачка табачной продукции несёт медицинское предупреждение в виде изображения последствий заболевания и текста, занимающее не менее 65% основной площади в верхней части передней стороны и не менее 65% основной площади в нижней части тыльной стороны; текст — на государственном и русско$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$нормативное значение теперь однозначно (65%), но фотопроверка остаётся частичной: нужны отдельные строго фронтальные кадры И передней, И тыльной стороны; на пачке с целлофаном и скруглёнными рёбрами граница «основной площади» и перспективные искажения дают ошибку измерения в единицы процентов, что критично при пороге ровно 65%; кроме того, по пп. 48-50 регламента в зачёт 65% идёт изображение ВМЕСТ$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"PKM290_TOBACCO","clause":"Технический регламент о табачной продукции (приложение № 1 к ПКМ № 290), п. 45; законодательная основа — ЗРУ-844, ст. 36, часть третья (введена в действие ок. 26.05.2024)","quote_ru":"СПОР 65% vs 40% РАЗРЕШЁН ПРИ РЕВИЗИИ: оба первичных текста сверены дословно по lex.uz 02.08.2026 и дают 65%; значение 40% относится к АЛКОГОЛЬНОЙ продукции (ст. 31, часть четвёртая ЗРУ-844) и попало в табачное требование по ошибке. ЗРУ-844, ст. 36, часть третья: «Потребительская упаковка (пачка) табачной продукции должна содержать медицинское предупреждение в виде изображения, иллюстрирующего посл"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
