insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.tobacco.health.warning.image.and.area$txt$, $txt$uz.tobacco.warning_area_front$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$warnings$txt$, $txt$warning_area$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$graphic_health_warning$txt$, null, $txt$area_fraction$txt$, $txt${"target":"graphic_health_warning","min_mm":null,"min_area_fraction":0.65,"surface":"front_panel_upper_part","reference_scale":"площадь предупреждения делится на площадь передней панели в том же кадре; масштабный эталон не нужен"}$txt$::jsonb, $txt$Фото строго перпендикулярно панели, вся панель в кадре, без перспективных искажений. Фиксируйте фактическую долю числом: порог ровно 65%, поэтому пограничные значения (60-70%) должны уходить на ручную проверку$txt$, null)
