insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.tobacco.health.warning.image.and.area$txt$, $txt$uz.tobacco.warning_area_back$txt$, 2, $txt$geometry$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$warnings$txt$, $txt$warning_area$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$graphic_health_warning$txt$, null, $txt$area_fraction$txt$, $txt${"target":"graphic_health_warning","min_mm":null,"min_area_fraction":0.65,"surface":"back_panel_lower_part","reference_scale":"площадь предупреждения делится на площадь тыльной панели в том же кадре"}$txt$::jsonb, $txt$Обязателен отдельный фронтальный кадр тыльной стороны. По п. 45 техрегламента ПКМ № 290 предупреждение на тыльной стороне размещается в НИЖНЕЙ части — фиксируйте не только долю площади, но и расположение блока$txt$, null)
