insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.tobacco.health.warning.image.and.area$txt$, $txt$uz.tobacco.warning_text_state_language$txt$, 3, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$marks$txt$, $txt$handling_marks$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Сопровождается ли изображение текстом предупреждения о вреде И на государственном (узбекском), И на русском языке, размещённым параллельно верхнему краю пачки?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["chekish","zararli","o'ldiradi","sog'liq","чекиш","зарарли","курение убивает","вредит здоровью","курение"],"expected_value":null,"language":["uz","ru"]}$txt$::jsonb, $txt$По п. 45 техрегламента ПКМ № 290 текст печатается на государственном И русском языках — наличие только одного из них является нарушением. Текст должен читаться в кадре, снимайте крупно$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.tobacco.forbidden.descriptors$txt$, null, $txt$uzbekistan$txt$, $txt$Запрещены обозначения, вводящие в заблуждение относительно вредности: «с низким содержанием смол», «лёгкие», «очень лёгкие», «мягкие», «экстра», «ультра», «тонкие»$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ПОНИЖЕНО ПРИ РЕВИЗИИ с checkable. Поиск конечного списка слов по фото действительно надёжен, но норма запрещает и однокоренные слова, и АНАЛОГИ на любых иностранных языках, и переводимые аналоги — это открытое множество, замкнутым словарём не покрываемое; параметр forbidden_imagery («светлая/пастельная цветовая кодировка как обозначение лёгкости») вообще является оценочным суждением, а не признако$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2402$txt$]::text[], $txt${"act_id":"ZRU844","clause":"ст. 36, часть восьмая, абзац седьмой","quote_ru":"Сверено дословно по lex.uz 02.08.2026. Часть восьмая: «Запрещается нанесение на потребительскую упаковку (пачку) табачной продукции и устройств для употребления табака и никотина: <…> информации, прямо или косвенно вводящей потребителя в заблуждение относительно вредности табачной продукции, в том числе такие слова, как «с низким содержанием смол», «легкие», «очень легкие», «мягкие», «экстра», «ул"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.tobacco.forbidden.descriptors$txt$, $txt$uz.tobacco.no_misleading_terms$txt$, 0, $txt$absence$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$composition$txt$, $txt$tar_nicotine_co$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на пачке слова «лёгкие», «очень лёгкие», «мягкие», «экстра», «ультра», «тонкие», «с низким содержанием смол» или их эквиваленты на любом языке?$txt$, null, $txt${"forbidden_terms":["лёгкие","легкие","очень лёгкие","мягкие","экстра","ультра","тонкие","с низким содержанием смол","light","lights","ultra light","mild","extra","slims","superlight","yengil","yumshoq","ingichka","past qatronli"],"note_ru":"Список является ОТКРЫТЫМ: закон запрещает также однокоренные слова, аналоги на иностранных языках и их переводы, поэтому отрицательный результат по словарю не равен соблюдению нормы. Оценка графических приёмов (пастельная цветовая кодировка как намёк на «лёгкость») по фото не производится — это правовая квалификация, а не признак изображения"}$txt$::jsonb, $txt$Снимите все шесть сторон пачки: запрещённое слово часто вынесено на торец или боковину. Совпадение по словарю считать сигналом высокой достоверности, отсутствие совпадения — слабым сигналом$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.alcohol.health.warning.40pct.label$txt$, null, $txt$uzbekistan$txt$, $txt$Потребительская тара алкогольной продукции (кроме натуральных и игристых вин) несёт медицинское предупреждение текстом и/или рисунком не менее 40% основной площади этикетки$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$долю площади можно измерить только если этикетка снята фронтально и целиком; на цилиндрической бутылке край этикетки уходит за габарит, что искажает измерение площади$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$2208$txt$]::text[], $txt${"act_id":"ZRU844","clause":"ст. 31, часть четвёртая","quote_ru":"ПОДТВЕРЖДЕНО ДОСЛОВНО по lex.uz 02.08.2026: «Потребительская тара алкогольной продукции (за исключением натуральных и игристых вин) должна содержать медицинское предупреждение в виде текстовой надписи и (или) рисунка, занимающее не менее сорока процентов основной площади этикетки». Обратите внимание: изъятие здесь (только натуральные и игристые вина) НЕ совпадает с изъятием по акцизной маркировке "}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.alcohol.health.warning.40pct.label$txt$, $txt$uz.alcohol.warning_text_present$txt$, 0, $txt$text_semantic$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$warnings$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, null, $txt$Есть ли на этикетке медицинское предупреждение о вреде употребления алкогольной продукции?$txt$, null, $txt${"expect":"any_mention","unit":null,"pattern_hints":["spirtli ichimlik","sog'liq uchun zararli","чрезмерное употребление","вредит здоровью","алкоголь"],"expected_value":null,"language":["uz","ru"]}$txt$::jsonb, $txt$Снимите основную этикетку целиком и фронтально$txt$, null)
