insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.alcohol.health.warning.40pct.label$txt$, $txt$uz.alcohol.warning_area_fraction$txt$, 1, $txt$geometry$txt$::public.photo_check_kind, $txt$critical$txt$::public.photo_severity, $txt$warnings$txt$, $txt$warning_area$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$health_warning_block$txt$, null, $txt$area_fraction$txt$, $txt${"target":"health_warning_block","min_mm":null,"min_area_fraction":0.4,"surface":"main_label","reference_scale":"доля площади предупреждения к площади основной этикетки; для цилиндрической тары требуется развёртка или несколько кадров"}$txt$::jsonb, $txt$Для бутылки сделайте 3-4 кадра с поворотом, чтобы восстановить полную площадь этикетки. Норма не применяется к натуральным и игристым винам — сначала определите тип напитка$txt$, null)
