insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.packaging.material.identification.and.symbols$txt$, null, $txt$uzbekistan$txt$, $txt$На упаковке и укупорочных средствах нанесена маркировка, идентифицирующая материал, пригодность для контакта с пищевой продукцией и возможность утилизации$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$сами символы (код материала, петля Мёбиуса, знак «бокал-вилка») на фото детектируются, но точный обязательный перечень по действующему ПКМ № 109 не подтверждён — возможны как ложные тревоги, так и пропуски$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$04$txt$, $txt$24$txt$]::text[], $txt${"act_id":"PKM109_PACKAGING","clause":"не установлен точно","quote_ru":"НОРМА НЕ ПОДТВЕРЖДЕНА ПЕРВИЧНЫМ ТЕКСТОМ. Технический регламент о безопасности упаковки и укупорочных средств утверждён ПКМ № 109 от 24.02.2025 (карточка lex.uz: постановление в силе с 26.02.2025), однако текст регламента на lex.uz приводится только на узбекском языке в виде вложения-PDF и при ревизии 02.08.2026 машиночитаемо не выгружен; прежнее утверждение «регламент вводится через 6 месяцев посл"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
