insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.conformity.mark.on.certified.products$txt$, null, $txt$uzbekistan$txt$, $txt$Сертифицированная продукция маркируется национальным знаком соответствия на упаковке, таре и в сопроводительной документации$txt$, $txt$partial$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$сам знак на упаковке распознаётся, но по фото нельзя установить, входит ли товар в перечень обязательного подтверждения соответствия и действителен ли сертификат, на который знак ссылается$txt$, array[$txt$UZ$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"OZDST_MARK","clause":"O'z DSt 1.19:2000 (форма, начертание и основные размеры знаков подтверждения соответствия); O'z DSt 5.8:2006 (правила применения)","quote_ru":"СЛАБЫЙ ИСТОЧНИК: изложение взято с сайта аккредитованного органа по сертификации (коммерческий сайт), первичные тексты O'z DSt 1.19:2000 и O'z DSt 5.8:2006 не сверялись. «Сертифицированная серийно производимая продукция маркируется знаком соответствия на упаковке, таре и сопроводительной документации под ответственность изготовителя/импортёра; допускается цветное или чёрно-белое исполнение; примен"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
