insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.conformity.mark.on.certified.products$txt$, $txt$uz.conformity.mark_present$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$major$txt$::public.photo_severity, $txt$identity$txt$, $txt$other:check$txt$, $txt$consumer$txt$::public.photo_packaging_level, $txt$uz_conformity_mark$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Знак соответствия РУз — не то же, что EAC; снимите его крупно вместе с кодом органа по сертификации, если он есть$txt$, null)
