insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.food.label.composition$txt$, null, $txt$uzbekistan$txt$, $txt$На этикетке пищевого продукта указан состав — наименования входящих ингредиентов, включая пищевые добавки$txt$, $txt$checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$блок состава — печатный текст, наличие проверяется по фото упаковки; оговорка: ст. 12 Закона № 483-I допускает размещение сведений на листке-вкладыше, поэтому отсутствие их на самой упаковке ещё не доказывает нарушения — при отрицательном результате нужен кадр вложенного листка, если он есть$txt$, array[$txt$UZ$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$04$txt$, $txt$24$txt$]::text[], $txt${"act_id":"ZRU_FOOD_QUALITY","clause":"ст. 12 «Расфасовка, упаковка и маркировка пищевых продуктов»","quote_ru":"Сверено дословно по lex.uz 02.08.2026 (прежде приводился пересказ по разъяснению уполномоченного органа). Ст. 12, часть вторая Закона № 483-I: «Расфасованные и упакованные пищевые продукты, биологически активные добавки к пище, пищевые добавки должны иметь этикетки (листки-вкладыши), где указываются: … наименования входящих в пищевой продукт ингредиентов, включая пищевые добавки …». ВАЖНАЯ ОГОВОРК"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
