insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.eaeu.trts.not.binding.national.conformity.required$txt$, null, $txt$uzbekistan$txt$, $txt$Технические регламенты ЕАЭС в Узбекистане обязательной силы не имеют: знак EAC на упаковке допустим, но не заменяет национальное подтверждение соответствия РУз$txt$, $txt$partial$txt$::public.photo_checkability, $txt$both$txt$::public.photo_packaging_level, $txt$знак EAC на фото детектируется и служит информативным сигналом (упаковка сделана под рынок ЕАЭС), но сам по себе ни нарушением, ни выполнением требований РУз не является$txt$, array[$txt$EAEU$txt$]::text[], $txt$all_products$txt$, array[]::text[], $txt${"act_id":"EEC_TR","clause":"правовой статус (в связке с решением ВЕЭС от 11.12.2020 — источник EEC_OBSERVER — и Законом РУз «О техническом регулировании» ЗРУ-819)","quote_ru":"Технические регламенты Союза устанавливают «обязательные для применения и исполнения на территории Союза требования»; территория Союза — пять государств-членов (Армения, Беларусь, Казахстан, Кыргызстан, Россия). Узбекистан с 11.12.2020 имеет статус государства-наблюдателя при ЕАЭС: право присутствовать на заседаниях органов Союза без права участия в принятии решений; обязательности актов Союза это"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;
insert into public.requirement_photo_checks (rule_ref, check_id, ord, kind, severity, group_key, subject, packaging_level, target, question_ru, measure, params, hint_ru, title_ru) values ($txt$uzbekistan.uz.eaeu.trts.not.binding.national.conformity.required$txt$, $txt$uz.eaeu.eac_mark_informational$txt$, 0, $txt$presence$txt$::public.photo_check_kind, $txt$info$txt$::public.photo_severity, $txt$marks$txt$, $txt$eac_mark$txt$, $txt$both$txt$::public.photo_packaging_level, $txt$eac_mark$txt$, null, null, $txt${"min_count":1}$txt$::jsonb, $txt$Если EAC есть, а национального знака соответствия РУз и маркировки на узбекском языке нет — это сигнал, что упаковка не адаптирована под рынок Узбекистана$txt$, null)
  on conflict (rule_ref, check_id) do update set ord = excluded.ord, kind = excluded.kind, severity = excluded.severity, group_key = excluded.group_key, subject = excluded.subject, packaging_level = excluded.packaging_level, target = excluded.target, question_ru = excluded.question_ru, measure = excluded.measure, params = excluded.params, hint_ru = excluded.hint_ru, title_ru = excluded.title_ru;

insert into public.requirement_photo (rule_ref, requirement_id, pack, title_ru, checkability, packaging_level, why, markets, scope, hs_prefixes, source, ruleset_sha256) values ($txt$uzbekistan.uz.ikpu.in.invoice.and.receipt.not.on.pack$txt$, null, $txt$uzbekistan$txt$, $txt$ИКПУ (идентификационный код продукции и услуг) указывается в электронном счёте-фактуре и чеке онлайн-ККМ; требования печатать ИКПУ на упаковке не установлено$txt$, $txt$not_checkable$txt$::public.photo_checkability, $txt$consumer$txt$::public.photo_packaging_level, $txt$ИКПУ — реквизит электронного счёта-фактуры и кассового чека, а не элемент упаковки; по фото упаковки проверке не подлежит$txt$, array[$txt$ANY$txt$]::text[], $txt$hs_prefix$txt$, array[$txt$85$txt$]::text[], $txt${"act_id":"SOLIQ_IKPU","clause":"не установлен точно","quote_ru":"По данным Налогового комитета, ИКПУ применяются при оформлении электронных счетов-фактур (ЭСФ) и выдаче чеков онлайн-ККМ; единый электронный национальный каталог — tasnif.soliq.uz. Требования наносить ИКПУ на потребительскую упаковку в изученных официальных источниках не обнаружено. Санкция за неверный ИКПУ (штраф ~1% от суммы реализации) указана в отраслевых публикациях, первичная норма не подтве"}$txt$::jsonb, $txt$8ac8e4a4c539011c06c956a9a87b211497a3a6b04f4427745b96b3bb9383b32e$txt$)
  on conflict (rule_ref) do update set requirement_id = excluded.requirement_id, pack = excluded.pack, title_ru = excluded.title_ru, checkability = excluded.checkability, packaging_level = excluded.packaging_level, why = excluded.why, markets = excluded.markets, scope = excluded.scope, hs_prefixes = excluded.hs_prefixes, source = excluded.source, ruleset_sha256 = excluded.ruleset_sha256;

